type OrderStatus = "new" | "preparing" | "ready" | "completed";
type NavKey = "overview" | "admin" | "accounts" | "files" | "branches" | "orders" | "pos" | "kds" | "menu" | "tables" | "inventory" | "team" | "marketing" | "reservations" | "remote" | "security" | "health";

type Order = { id: string; table: string; items: string; total: number; status: OrderStatus; time: string; channel: string };
type InstallPromptEvent = Event & { prompt: () => Promise<void>; userChoice: Promise<{ outcome: "accepted" | "dismissed" }> };

const navItems: { key: NavKey; label: string; icon: typeof LayoutDashboard }[] = [
  { key: "overview", label: "نظرة عامة", icon: LayoutDashboard },
  { key: "files", label: "مدير الملفات", icon: HardDrive },
  { key: "admin", label: "Super Admin", icon: ShieldCheck },
  { key: "branches", label: "الفروع والإعدادات", icon: Store },
  { key: "orders", label: "الطلبات", icon: ShoppingBag },
  { key: "pos", label: "نقطة البيع POS", icon: WalletCards },
  { key: "kds", label: "شاشة المطبخ KDS", icon: ChefHat },
  { key: "menu", label: "المنيو والأصناف", icon: Utensils },
  { key: "tables", label: "الطاولات", icon: Table2 },
  { key: "inventory", label: "المخزون والمشتريات", icon: Boxes },
  { key: "team", label: "الموظفون والحضور", icon: Users },
  { key: "marketing", label: "التسويق والحملات", icon: Megaphone },
  { key: "reservations", label: "الحجوزات والانتظار", icon: Clock3 },
  { key: "remote", label: "التوظيف عن بُعد", icon: Users },
  { key: "security", label: "أمان الحساب والجلسات", icon: ShieldCheck },
  { key: "health", label: "صحة النظام", icon: Activity },
];

const navTranslationKeys: Record<NavKey, TranslationKey> = { overview: "overview", admin: "platformAdmin", accounts: "platformAdmin", files: "platformAdmin", branches: "branches", orders: "orders", pos: "pos", kds: "kds", menu: "menu", tables: "tables", inventory: "inventory", team: "team", marketing: "marketing", reservations: "reservations", remote: "remote", security: "security", health: "health" };
const statusLabels: Record<OrderStatus, string> = { new: "جديد", preparing: "قيد التحضير", ready: "جاهز", completed: "مكتمل" };
const statusStyles: Record<OrderStatus, string> = { new: "bg-amber-50 text-amber-700 border-amber-200", preparing: "bg-blue-50 text-blue-700 border-blue-200", ready: "bg-emerald-50 text-emerald-700 border-emerald-200", completed: "bg-slate-100 text-slate-600 border-slate-200" };

function money(value: number) { return `${value.toLocaleString("ar-SA")} ر.س`; }

export default function Home() {
  const { user, loading, logout } = useAuth();
  const { direction, language, locale, t } = useLanguage();
  const [testEmail, setTestEmail] = useState("fooncards@gmail.com");
  const [testPassword, setTestPassword] = useState("");
  const [showRegister, setShowRegister] = useState(false);
  const testLogin = trpc.auth.testLogin.useMutation({ onSuccess: () => { toast.success("تم تسجيل الدخول لحساب الاختبار"); window.location.reload(); }, onError: (error) => toast.error(error.message || "بيانات الدخول غير صحيحة") });
  const adminReturn = trpc.auth.adminReturn.useMutation({ onSuccess: () => window.location.reload(), onError: (error) => toast.error(error.message || "تعذرت العودة إلى جلسة Admin") });
  const [active, setActive] = useState<NavKey>("overview");
  const localizedNavItems = useMemo(() => navItems.map((item) => ({ ...item, label: t(navTranslationKeys[item.key]) })), [language, t]);
  const visibleNavItems = useMemo(() => { const role = user?.testRole as string | undefined; const keys = getVisibleNavigation(role, user?.role === "admin" || role === "admin"); return localizedNavItems.filter((item) => keys.includes(item.key)); }, [user?.role, user?.testRole, localizedNavItems]);
  useEffect(() => { if (user && !visibleNavItems.some((item) => item.key === active)) setActive("overview"); }, [user, active, visibleNavItems]);
  const [selectedRestaurantId, setSelectedRestaurantId] = useState(() => { if (typeof window === "undefined") return 1; const stored = Number(window.localStorage.getItem("nfood-selected-restaurant")); return Number.isInteger(stored) && stored > 0 ? stored : 1; });
  const isCentralAdmin = user?.role === "admin" || (user?.testRole as string | undefined) === "admin";
  const platformRestaurantsQuery = trpc.platform.restaurants.useQuery(undefined, { enabled: Boolean(user && !isCentralAdmin), retry: 2 });
  const centralRestaurantsQuery = trpc.admin.restaurants.useQuery(undefined, { enabled: Boolean(user && isCentralAdmin), retry: 2 });
  const restaurantsQuery = isCentralAdmin ? centralRestaurantsQuery : platformRestaurantsQuery;
  useEffect(() => { const restaurants = restaurantsQuery.data ?? []; if (!restaurants.length) return; const available = restaurants.some((restaurant) => restaurant.id === selectedRestaurantId); const nextId = available ? selectedRestaurantId : restaurants[0].id; if (nextId !== selectedRestaurantId) setSelectedRestaurantId(nextId); window.localStorage.setItem("nfood-selected-restaurant", String(nextId)); }, [restaurantsQuery.data, selectedRestaurantId]);
  const workspaceState = getWorkspaceState(restaurantsQuery.data ?? [], selectedRestaurantId);
  const workspaceReady = Boolean(user && (isCentralAdmin || workspaceState === "ready"));
  const showRestaurantContext = !isCentralAdmin && user?.testRole !== "customer";
  useEffect(() => { if (restaurantsQuery.isError && !isCentralAdmin) toast.error("تعذر تحميل قائمة المطاعم الآن؛ يمكنك متابعة الدخول وإعادة المحاولة من محدد المطعم."); }, [restaurantsQuery.isError, isCentralAdmin]);
  const [profileOpen, setProfileOpen] = useState(false);
  const [showCustomerProfile, setShowCustomerProfile] = useState(false);
  const [showVcardBinding, setShowVcardBinding] = useState(false);
  const vcardFeatureQuery = trpc.platform.vcardFeature.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const [notificationOpen, setNotificationOpen] = useState(false);
  const [commandOpen, setCommandOpen] = useState(false);
  const [mobileSidebarOpen, setMobileSidebarOpen] = useState(false);
  const [commandQuery, setCommandQuery] = useState("");
  const globalSearchQuery = trpc.platform.globalSearch.useQuery({ restaurantId: selectedRestaurantId, query: commandQuery, limit: 20 }, { enabled: commandOpen && commandQuery.trim().length >= 2 && workspaceReady, retry: false });
  const workspaceBranches = trpc.platform.branches.useQuery({ restaurantId: selectedRestaurantId }, { enabled: workspaceReady, retry: 2 });
  const activeBranchId = workspaceBranches.data?.find((branch) => branch.status === "open")?.id ?? workspaceBranches.data?.[0]?.id;
  const roleSummaryQuery = trpc.platform.roleSummary.useQuery({ restaurantId: selectedRestaurantId, branchId: activeBranchId }, { enabled: Boolean(user && selectedRestaurantId > 0 && workspaceReady), retry: 2 });
  const brandingQuery = trpc.platform.branding.useQuery({ restaurantId: selectedRestaurantId }, { enabled: workspaceReady, retry: false });
  const [globalForbiddenAction, setGlobalForbiddenAction] = useState<string | null>(null);
  useEffect(() => {
    if (isCentralAdmin) {
      setGlobalForbiddenAction(null);
      return;
    }
    if (globalSearchQuery.error?.data?.code === "FORBIDDEN") setGlobalForbiddenAction("global.search");
    else if (roleSummaryQuery.error?.data?.code === "FORBIDDEN") setGlobalForbiddenAction("dashboard.summary");
  }, [globalSearchQuery.error, roleSummaryQuery.error, isCentralAdmin]);
  useEffect(() => {
    const onForbidden = (event: Event) => {
      if (isCentralAdmin) return;
      const action = (event as CustomEvent<{ action?: string }>).detail?.action;
      setGlobalForbiddenAction(action || "protected.action");
    };
    window.addEventListener("nfood:forbidden", onForbidden);
    return () => window.removeEventListener("nfood:forbidden", onForbidden);
  }, [isCentralAdmin]);
  const [installPrompt, setInstallPrompt] = useState<InstallPromptEvent | null>(null);
  const [pwaInstalled, setPwaInstalled] = useState(() => typeof window !== "undefined" && window.matchMedia?.("(display-mode: standalone)").matches);
  const [pushStatus, setPushStatus] = useState<NotificationPermission | "unsupported">(() => typeof Notification === "undefined" ? "unsupported" : Notification.permission);
  const pushSubscribe = trpc.notifications.pushSubscribe.useMutation();
  const enablePush = async () => { if (typeof Notification === "undefined" || !("serviceWorker" in navigator)) { toast.error("المتصفح الحالي لا يدعم إشعارات Push"); return; } const permission = await Notification.requestPermission(); setPushStatus(permission); if (permission !== "granted") { toast.info("لم يتم تفعيل الإشعارات"); return; } try { const registration = await navigator.serviceWorker.ready; const subscription = await registration.pushManager.getSubscription(); if (subscription) { const json = subscription.toJSON(); if (json.endpoint && json.keys?.p256dh && json.keys.auth) { await pushSubscribe.mutateAsync({ endpoint: json.endpoint, keys: { p256dh: json.keys.p256dh, auth: json.keys.auth }, userAgent: navigator.userAgent }); toast.success("تم تفعيل إشعارات NFOOD وحفظ الجهاز"); return; } } toast.info("تم السماح بالإشعارات. يلزم ربط مفتاح Push للإرسال الإنتاجي."); } catch { toast.error("تعذر حفظ اشتراك الإشعارات"); } };
  useEffect(() => { const capture = (event: Event) => { event.preventDefault(); setInstallPrompt(event as InstallPromptEvent); }; const installed = () => { setPwaInstalled(true); setInstallPrompt(null); toast.success("تم تثبيت تطبيق NFOOD"); }; window.addEventListener("beforeinstallprompt", capture); window.addEventListener("appinstalled", installed); return () => { window.removeEventListener("beforeinstallprompt", capture); window.removeEventListener("appinstalled", installed); }; }, []);
  useEffect(() => {
    const manifestLink = document.querySelector<HTMLLinkElement>('link[rel="manifest"]');
    const themeMeta = document.querySelector<HTMLMetaElement>('meta[name="theme-color"]');
    if (!manifestLink) return;
    const defaultTitle = "NFOOD Restaurant SaaS";
    if (!user) {
      document.title = defaultTitle;
      if (themeMeta) themeMeta.content = "#e76f3c";
      manifestLink.href = "/manifest.webmanifest";
      return;
    }
    const role = user.testRole ?? (user.role === "admin" ? "restaurant_admin" : "customer");
    const brand = brandingQuery.data;
    document.title = brand?.brandName || defaultTitle;
    if (themeMeta) themeMeta.content = brand?.brandColor || "#e76f3c";
    let objectUrl: string | null = null;
    if (brand?.brandName) {
      const icon = brand.brandLogoUrl || "/icon-maskable.svg";
      const manifest = { name: brand.brandName, short_name: brand.brandName.slice(0, 32), lang: "ar", dir: "rtl", start_url: "/", display: "standalone", theme_color: brand.brandColor || "#e76f3c", background_color: "#f6f7f9", description: brand.brandDescription || `تطبيق ${brand.brandName}`, icons: [{ src: icon, sizes: "512x512", type: "image/png", purpose: "any maskable" }] };
      objectUrl = URL.createObjectURL(new Blob([JSON.stringify(manifest)], { type: "application/manifest+json" }));
      manifestLink.href = objectUrl;
    } else {
      manifestLink.href = `/manifest.${role}.webmanifest`;
    }
    return () => {
      if (objectUrl) URL.revokeObjectURL(objectUrl);
      manifestLink.href = "/manifest.webmanifest";
      document.title = defaultTitle;
      if (themeMeta) themeMeta.content = "#e76f3c";
    };
  }, [brandingQuery.data, user?.role, user?.testRole, Boolean(workspaceReady)]);
  useEffect(() => { const onKeyDown = (event: KeyboardEvent) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen(true); } if (event.key === "Escape") setCommandOpen(false); }; window.addEventListener("keydown", onKeyDown); return () => window.removeEventListener("keydown", onKeyDown); }, []);
  const notificationsQuery = trpc.notifications.mine.useQuery(undefined, { enabled: Boolean(user) && notificationOpen, retry: 2 });
  const markNotificationRead = trpc.notifications.markRead.useMutation({ onSuccess: () => notificationsQuery.refetch() });
  const remoteOrders = trpc.platform.ordersByRestaurant.useQuery({ restaurantId: selectedRestaurantId }, { enabled: workspaceReady && user?.role !== "admin" && (user?.testRole as string | undefined) !== "admin", retry: false, refetchInterval: 5000 });
  const updateOrderStatus = trpc.platform.updateOrderStatus.useMutation({ onSuccess: () => { remoteOrders.refetch(); toast.success("تم حفظ حالة الطلب في قاعدة البيانات"); }, onError: (error) => toast.error(`تعذر تحديث الطلب: ${error.message}`) });
  const [branch, setBranch] = useState("");
  useEffect(() => { const firstBranch = workspaceBranches.data?.[0]; setBranch((current) => current && workspaceBranches.data?.some((item) => item.name === current) ? current : firstBranch?.name ?? ""); }, [workspaceBranches.data]);
  const [query, setQuery] = useState("");
  const orders = useMemo(() => (remoteOrders.data ?? []).map((order) => ({ id: `#${order.id}`, table: order.tableName ?? "بدون طاولة", items: "بنود محفوظة في الطلب", total: Number(order.total), status: order.status === "cancelled" ? "completed" : order.status, time: new Date(order.createdAt).toLocaleTimeString("ar-SA", { hour: "2-digit", minute: "2-digit" }), channel: order.channel === "dine_in" ? "داخل المطعم" : order.channel === "takeaway" ? "استلام" : "توصيل" })), [remoteOrders.data]);
  const visibleOrders = useMemo(() => orders.filter((order) => `${order.id} ${order.table} ${order.items}`.includes(query)), [orders, query]);
  const advanceOrder = (id: string) => {
    const current = orders.find((order) => order.id === id);
    if (!current) return;
    const next: OrderStatus = current.status === "new" ? "preparing" : current.status === "preparing" ? "ready" : "completed";
    const numericId = Number(id.replace("#", ""));
    if (!remoteOrders.data?.some((order) => order.id === numericId)) { toast.error("الطلب غير موجود في بيانات backend الحالية"); return; }
    updateOrderStatus.mutate({ restaurantId: selectedRestaurantId, orderId: numericId, status: next });
  };

  if (loading) return <div dir={direction} className="flex min-h-screen items-center justify-center bg-[#f6f7f9] text-slate-500">جارٍ التحقق من الجلسة...</div>;
    if (!user) return showRegister ? <RegisterScreen onBack={() => setShowRegister(false)} onOAuth={() => startLogin()} /> : <TestLoginScreen email={testEmail} password={testPassword} setEmail={setTestEmail} setPassword={setTestPassword} onSubmit={() => testLogin.mutate({ email: testEmail, password: testPassword })} pending={testLogin.isPending} onOAuth={() => startLogin()} onRegister={() => setShowRegister(true)} />;
  const title = localizedNavItems.find((item) => item.key === active)?.label ?? t("overview");
  const todayLabel = new Date().toLocaleDateString(locale, { weekday: "long", day: "numeric", month: "long", year: "numeric" });
  const roleDashboardTitle = "";
  const sidebarGroups = [
    { label: "نظرة عامة", keys: ["overview", "admin"] as NavKey[] },
    { label: "التشغيل", keys: ["orders", "pos", "kds", "menu", "tables", "inventory", "team", "marketing", "reservations", "remote"] as NavKey[] },
    { label: "الحساب والمنصة", keys: ["branches", "security", "health"] as NavKey[] },
  ].map((group) => ({ ...group, items: group.keys.map((key) => visibleNavItems.find((item) => item.key === key)).filter((item): item is (typeof visibleNavItems)[number] => Boolean(item)) })).filter((group) => group.items.length > 0);
  const handleLogout = async () => { await executeLogoutFlow({ logout, closeMenu: () => setProfileOpen(false), redirect: () => { window.location.href = "/"; }, notifySuccess: () => toast.success("تم تسجيل الخروج"), notifyError: (message) => toast.error(message) }); };
  const handleSwitchAccount = async () => { await executeSwitchAccountFlow({ logout, closeMenu: () => setProfileOpen(false), startLogin, redirect: () => undefined, notifyError: (message) => toast.error(message) }); };
  return (
    <div dir={direction} lang={language} className="min-h-screen bg-[#f6f7f9] text-[#182230]">
      <aside className={`fixed inset-y-0 z-20 hidden w-[272px] border-slate-200 bg-[#111c2e] text-white lg:flex lg:flex-col ${direction === "rtl" ? "right-0 border-l" : "left-0 border-r"}`}>
        <div className="flex h-20 items-center gap-3 border-b border-white/10 px-7">
          <div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-[#e76f3c] shadow-lg shadow-orange-900/20"><Utensils className="h-5 w-5" /></div>
          <div><div className="text-[17px] font-bold tracking-tight">NFOOD</div><div className="text-[10px] font-medium text-slate-400">RESTAURANT OPERATING SYSTEM</div></div>
        </div>
        <div className="space-y-5 px-4 pt-6">
          <div className="rounded-2xl border border-white/10 bg-white/[.04] p-3">
            <p className="mb-2 px-2 text-[10px] font-bold tracking-[.14em] text-slate-500">مساحة العمل</p>
            <div className="space-y-2"><select aria-label="اختيار المطعم" value={selectedRestaurantId} onChange={(e) => setSelectedRestaurantId(Number(e.target.value))} className="h-10 w-full rounded-xl border border-white/10 bg-[#17263d] px-3 text-xs text-white outline-none"><option value={selectedRestaurantId}>{restaurantsQuery.data?.length ? "اختر المطعم" : restaurantsQuery.isLoading ? t("loadingRestaurants") : t("noRestaurants")}</option>{(restaurantsQuery.data ?? []).map((restaurant) => <option key={restaurant.id} value={restaurant.id}>{restaurant.name}</option>)}</select><select aria-label="اختيار الفرع" value={branch} onChange={(e) => setBranch(e.target.value)} disabled={(workspaceBranches.isLoading && !workspaceBranches.data) || workspaceBranches.isError || workspaceBranches.data?.length === 0} className="h-10 w-full rounded-xl border border-white/10 bg-[#17263d] px-3 text-xs text-white outline-none"><option value="">{workspaceBranches.data?.length ? t("selectBranch") : workspaceBranches.isLoading ? t("loadingBranches") : workspaceBranches.isError ? "تعذر تحميل الفروع" : t("noBranches")}</option>{(workspaceBranches.data ?? []).map((item) => <option key={item.id} value={item.name}>{item.name}</option>)}</select><button type="button" onClick={() => setCommandOpen(true)} className="flex h-10 w-full items-center gap-2 rounded-xl border border-white/10 bg-[#17263d] px-3 text-xs text-slate-300 hover:text-white"><Search className="h-4 w-4" /> بحث شامل <span className="mr-auto text-[10px] text-slate-500">Ctrl K</span></button></div>
          </div>
          {(isCentralAdmin || user?.testRole === "restaurant_admin") && <div className="rounded-2xl border border-orange-300/20 bg-orange-400/10 p-3"><p className="mb-2 px-2 text-[10px] font-bold tracking-[.14em] text-orange-200">الإعدادات والتكاملات</p><div className="space-y-1">{isCentralAdmin && <button type="button" onClick={() => setActive("admin")} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-right text-[13px] transition-all ${active === "admin" ? "bg-[#e76f3c] font-semibold text-white shadow-lg shadow-orange-950/20" : "text-slate-300 hover:bg-white/10 hover:text-white"}`}><Settings2 className="h-[18px] w-[18px]" /><span>مركز إعدادات المنصة</span></button>}<button type="button" onClick={() => { window.location.href = isCentralAdmin ? "/integrations?scope=platform" : `/integrations?scope=restaurant&restaurantId=${selectedRestaurantId}`; }} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-right text-[13px] text-slate-300 transition-all hover:bg-white/10 hover:text-white"><Settings2 className="h-[18px] w-[18px]" /><span>{isCentralAdmin ? "مركز البوابات والتكاملات" : "بوابات المطعم"}</span></button></div></div>}
          <nav className="space-y-4">{sidebarGroups.map((group) => <div key={group.label}><p className="mb-2 px-3 text-[10px] font-bold tracking-[.14em] text-slate-500">{group.label}</p><div className="space-y-1">{group.items.map((item) => { const Icon = item.icon; const isActive = item.key === active; return <button key={item.key} onClick={() => setActive(item.key)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-right text-[13px] transition-all ${isActive ? "bg-[#e76f3c] font-semibold text-white shadow-lg shadow-orange-950/20" : "text-slate-400 hover:bg-white/5 hover:text-white"}`}><Icon className="h-[18px] w-[18px]" /><span>{item.label}</span>{item.key === "orders" && <span className="mr-auto rounded-full bg-white/15 px-2 py-0.5 text-[10px] text-white">{remoteOrders.isLoading ? "…" : remoteOrders.data?.length ?? 0}</span>}</button>; })}</div></div>)}</nav>
        </div>
        <div className="mt-auto space-y-4 p-5"><div className="rounded-2xl border border-white/10 bg-white/[.04] p-4"><div className="mb-2 flex items-center gap-2 text-xs font-semibold"><Zap className="h-4 w-4 text-[#f0ad65]" /> الاشتراك</div><p className="text-sm font-bold">{t("managePlan")}</p><p className="mt-1 text-[11px] leading-5 text-slate-400">تظهر تفاصيل الباقة والفترة من بيانات الاشتراك المحفوظة في لوحة الإدارة.</p></div>{pushStatus === "default" && <button onClick={enablePush} className="flex w-full items-center gap-3 px-3 py-2 text-sm text-slate-400 hover:text-white"><Bell className="h-4 w-4" /> تفعيل إشعارات NFOOD</button>}{pushStatus === "granted" && <p className="px-3 py-2 text-xs text-emerald-400">إشعارات NFOOD مفعّلة</p>}{pwaInstalled ? <p className="px-3 py-2 text-xs text-emerald-400">تطبيق NFOOD مثبت على هذا الجهاز</p> : installPrompt ? <button onClick={async () => { await installPrompt.prompt(); const result = await installPrompt.userChoice; if (result.outcome === "accepted") toast.success("تم بدء تثبيت تطبيق NFOOD"); setInstallPrompt(null); }} className="flex w-full items-center gap-3 px-3 py-2 text-sm text-[#f0ad65] hover:text-white"><Zap className="h-4 w-4" /> تثبيت تطبيق NFOOD</button> : <p className="px-3 py-2 text-xs text-slate-500">التثبيت متاح من قائمة المتصفح عند استيفاء الشروط</p>}<button onClick={() => setActive("branches")} className="flex w-full items-center gap-3 px-3 py-2 text-sm text-slate-400 hover:text-white"><Settings2 className="h-4 w-4" /> الإعدادات العامة</button></div>
      </aside>
      <main className={direction === "rtl" ? "lg:mr-[272px]" : "lg:ml-[272px]"}>{user?.loginMethod === "admin_impersonation" && <button type="button" disabled={adminReturn.isPending} onClick={() => adminReturn.mutate()} className="fixed bottom-5 left-5 z-50 rounded-2xl bg-[#101d31] px-4 py-3 text-sm font-bold text-white shadow-xl hover:bg-[#17263d]">{adminReturn.isPending ? "جارٍ الرجوع..." : "العودة إلى Admin"}</button>}
        <header className="sticky top-0 z-10 flex h-20 items-center justify-between border-b border-slate-200/80 bg-[#f6f7f9]/90 px-5 backdrop-blur-xl md:px-8"><div>{showRestaurantContext && <div className="mb-1 flex items-center gap-2 text-xs text-slate-500"><span>{t("workspace")}</span><span>/</span><span className="font-medium text-slate-700">{restaurantsQuery.data?.find((restaurant) => restaurant.id === selectedRestaurantId)?.name ?? (restaurantsQuery.isLoading ? t("loadingRestaurant") : t("noRestaurant"))}</span></div>}<h1 className="text-xl font-bold tracking-tight md:text-2xl">{title}</h1></div><div className="flex items-center gap-3"><LanguageSwitcher compact />{showRestaurantContext && restaurantsQuery.data?.find((restaurant) => restaurant.id === selectedRestaurantId)?.slug && <button type="button" aria-label="فتح منيو المطعم العامة" title="فتح منيو المطعم العامة" onClick={() => { const slug = restaurantsQuery.data?.find((restaurant) => restaurant.id === selectedRestaurantId)?.slug; if (slug) window.location.assign(publicMenuUrl(window.location.origin, slug)); }} className="rounded-xl border border-slate-200 bg-white p-2.5 text-slate-500 shadow-sm transition hover:text-[#e76f3c]"><Utensils className="h-[18px] w-[18px]" /></button>}<div className="relative"><button aria-label="فتح الإشعارات" aria-expanded={notificationOpen} onClick={() => setNotificationOpen((open) => !open)} className="relative rounded-xl border border-slate-200 bg-white p-2.5 text-slate-500 shadow-sm hover:text-[#e76f3c]"><Bell className="h-[18px] w-[18px]" />{(notificationsQuery.data ?? []).some((item) => !item.readAt) && <span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-[#e76f3c]" />}</button>{notificationOpen && <div className="absolute left-0 top-12 z-50 w-80 rounded-2xl border border-slate-200 bg-white p-2 shadow-xl"><div className="flex items-center justify-between border-b border-slate-100 px-3 py-2"><p className="text-sm font-bold">{t("notifications")}</p><span className="text-[10px] text-slate-400">{notificationsQuery.data?.length ?? 0}</span></div><div className="max-h-72 overflow-y-auto">{(notificationsQuery.data ?? []).length === 0 ? <p className="px-3 py-8 text-center text-xs text-slate-500">{t("noNotifications")}</p> : (notificationsQuery.data ?? []).map((item) => <button key={item.id} onClick={() => markNotificationRead.mutate({ notificationId: item.id })} className={`w-full rounded-xl px-3 py-3 text-right hover:bg-orange-50 ${item.readAt ? "opacity-60" : ""}`}><p className="text-xs font-bold">{item.title}</p><p className="mt-1 text-xs text-slate-500">{item.body}</p></button>)}</div></div>}</div><div className="relative block"><button aria-label="فتح قائمة الملف الشخصي" aria-expanded={profileOpen} onClick={() => setProfileOpen((open) => !open)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#e76f3c] text-sm font-bold text-white shadow-sm transition hover:bg-[#d85f2e]">{user?.name?.[0] || "م"}</button>{profileOpen && <div className="absolute left-0 top-11 z-50 w-[min(16rem,calc(100vw-2rem))] rounded-2xl border border-slate-200 bg-white p-2 text-right shadow-xl"><div className="border-b border-slate-100 px-3 py-3"><p className="text-sm font-bold">{user?.name || "حساب NFOOD"}</p><p className="mt-1 truncate text-xs text-slate-500">{user?.email || "لم يتم تسجيل الدخول"}</p></div>{user?.testRole === "customer" && <button onClick={() => { setShowCustomerProfile(true); setProfileOpen(false); }} className="mt-2 flex w-full items-center rounded-xl px-3 py-2.5 text-sm text-slate-700 hover:bg-orange-50 hover:text-[#e76f3c]">إعدادات الملف والبريد</button>}<button onClick={handleLogout} className="flex w-full items-center rounded-xl px-3 py-2.5 text-sm text-red-600 hover:bg-red-50">تسجيل الخروج</button></div>}</div></div><button type="button" aria-label="فتح قائمة التنقل" onClick={() => setMobileSidebarOpen(true)} className="fixed right-3 top-3 z-50 rounded-xl border border-slate-200 bg-white p-2.5 text-slate-600 shadow-sm lg:hidden"><MenuIcon className="h-5 w-5" /></button></header>{commandOpen && <div className="fixed inset-0 z-[80] flex items-start justify-center bg-slate-950/30 px-4 pt-24" onMouseDown={() => setCommandOpen(false)}><div className="w-full max-w-2xl overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-2xl" onMouseDown={(event) => event.stopPropagation()}><div className="flex items-center gap-3 border-b border-slate-100 px-4 py-3"><Search className="h-5 w-5 text-slate-400" /><input autoFocus value={commandQuery} onChange={(event) => setCommandQuery(event.target.value)} placeholder={t("globalSearch")} className="flex-1 bg-transparent text-sm outline-none" /><kbd className="rounded bg-slate-100 px-2 py-1 text-[10px] text-slate-500">Esc</kbd></div><div className="max-h-[55vh] overflow-y-auto p-2">{globalSearchQuery.isLoading && <p className="px-3 py-3 text-xs text-slate-500">جارٍ البحث داخل بيانات المطعم...</p>}{globalSearchQuery.isError && <p className="px-3 py-3 text-xs text-red-600">تعذر البحث الآن. Request ID: search-{selectedRestaurantId}</p>}{globalSearchQuery.data?.results.map((result) => <button key={`${result.type}-${result.id}`} onClick={() => { setActive(result.action as NavKey); setCommandOpen(false); setCommandQuery(""); }} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-right hover:bg-orange-50"><Search className="h-4 w-4 text-[#e76f3c]" /><span className="text-sm font-semibold">{result.title}</span><span className="mr-auto text-xs text-slate-400">{result.subtitle}</span></button>)}{localizedNavItems.filter((item) => visibleNavItems.some((visible) => visible.key === item.key) && item.label.includes(commandQuery)).map((item) => { const Icon = item.icon; return <button key={item.key} onClick={() => { setActive(item.key); setCommandOpen(false); setCommandQuery(""); }} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-right hover:bg-orange-50"><Icon className="h-4 w-4 text-[#e76f3c]" /><span className="text-sm font-semibold">{item.label}</span><span className="mr-auto text-xs text-slate-400">وحدة</span></button>; })}{orders.filter((order) => `${order.id} ${order.table} ${order.items}`.includes(commandQuery)).slice(0, 5).map((order) => <button key={order.id} onClick={() => { setActive("orders"); setCommandOpen(false); setCommandQuery(""); }} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-right hover:bg-slate-50"><ShoppingBag className="h-4 w-4 text-slate-400" /><span className="text-sm font-semibold">{order.id} · {order.table}</span><span className="mr-auto text-xs text-slate-400">طلب</span></button>)}{localizedNavItems.filter((item) => visibleNavItems.some((visible) => visible.key === item.key) && item.label.includes(commandQuery)).length === 0 && orders.filter((order) => `${order.id} ${order.table} ${order.items}`.includes(commandQuery)).length === 0 && (globalSearchQuery.data?.results.length ?? 0) === 0 && !globalSearchQuery.isLoading && <p className="px-3 py-10 text-center text-sm text-slate-500">لا توجد نتائج مطابقة.</p>}</div></div></div>}\n        <div className="p-5 pb-24 md:p-8"><div className="mb-7 flex items-end justify-between gap-4"><div><p className="text-sm text-slate-500">{todayLabel}</p><h2 className="mt-1 text-2xl font-bold">{roleDashboardTitle}</h2></div></div>
          {showCustomerProfile ? <CustomerProfileSettings embedded onClose={() => setShowCustomerProfile(false)} /> : showVcardBinding ? <VcardAccountBinding role={user?.testRole === "driver" ? "driver" : "restaurant"} onClose={() => setShowVcardBinding(false)} /> : globalForbiddenAction ? <AccessDeniedView feature={globalForbiddenAction} /> : active === "overview" ? isCentralAdmin ? <PlatformOverview onNavigate={setActive} /> : <Overview orders={visibleOrders} advanceOrder={advanceOrder} query={query} setQuery={setQuery} role={user?.testRole} onNavigate={setActive} summary={roleSummaryQuery.data} summaryLoading={roleSummaryQuery.isLoading} summaryError={roleSummaryQuery.isError} /> : !visibleNavItems.some((item) => item.key === active) ? <AccessDeniedView feature={active} /> : <ModuleView active={active} orders={visibleOrders} advanceOrder={advanceOrder} setActive={setActive} restaurantId={selectedRestaurantId} ordersLoading={remoteOrders.isLoading} ordersError={remoteOrders.isError} role={user?.testRole} />}
        </div>
        {mobileSidebarOpen && <div className="fixed inset-0 z-[70] lg:hidden" role="dialog" aria-modal="true" aria-label="قائمة التنقل"><button type="button" aria-label="إغلاق قائمة التنقل" className="absolute inset-0 bg-slate-950/40" onClick={() => setMobileSidebarOpen(false)} /><aside className="absolute inset-y-0 right-0 w-[min(86vw,320px)] overflow-y-auto bg-[#111c2e] p-5 text-white shadow-2xl"><div className="mb-6 flex items-center justify-between"><p className="text-base font-bold">قائمة الوحدات</p><button type="button" onClick={() => setMobileSidebarOpen(false)} className="rounded-xl bg-white/10 px-3 py-2 text-sm">إغلاق</button></div><div className="space-y-2">{visibleNavItems.map((item) => { const Icon = item.icon; return <button key={item.key} type="button" onClick={() => { setActive(item.key); setMobileSidebarOpen(false); }} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-right text-sm ${active === item.key ? "bg-[#e76f3c] font-semibold" : "text-slate-300 hover:bg-white/10"}`}><Icon className="h-5 w-5" /><span>{item.label}</span></button>; })}</div>{(isCentralAdmin || user?.testRole === "restaurant_admin") && <div className="mt-5 border-t border-white/10 pt-5"><p className="mb-2 px-3 text-xs font-bold text-orange-200">الإعدادات والتكاملات</p><button type="button" onClick={() => { setActive("admin"); setMobileSidebarOpen(false); }} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-right text-sm text-slate-300 hover:bg-white/10"><Settings2 className="h-5 w-5" />مركز إعدادات المنصة</button><button type="button" onClick={() => { window.location.href = isCentralAdmin ? "/integrations?scope=platform" : `/integrations?scope=restaurant&restaurantId=${selectedRestaurantId}`; }} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-right text-sm text-slate-300 hover:bg-white/10"><Settings2 className="h-5 w-5" />{isCentralAdmin ? "مركز البوابات والتكاملات" : "بوابات المطعم"}</button></div>}</aside></div>}
      </main>
    </div>
  );
}

function EmptyWorkspaceView() { return <div className="flex min-h-[58vh] items-center justify-center rounded-3xl border border-dashed border-slate-200 bg-white/60"><div className="max-w-md px-6 text-center"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-orange-50 text-[#e76f3c]"><LayoutDashboard className="h-6 w-6" /></div><h2 className="mt-4 text-xl font-bold text-slate-800">مساحة العمل جاهزة</h2><p className="mt-2 text-sm leading-7 text-slate-500">اختر أي عنصر من الشريط الجانبي لفتح تفاصيله هنا. عند إغلاق العنصر يعود الوسط إلى مساحة فارغة للرسوم البيانية والبيانات النشطة.</p></div></div>; }

function PlatformOverview({ onNavigate }: { onNavigate: (key: NavKey) => void }) { const restaurantsQuery = trpc.admin.restaurants.useQuery(undefined, { retry: 2 }); const subscriptionsQuery = trpc.admin.subscriptions.useQuery({}, { retry: 2 }); const restaurants = restaurantsQuery.data ?? []; const subscriptions = subscriptionsQuery.data ?? []; const activeRestaurants = restaurants.filter((restaurant) => restaurant.status === "active").length; const inactiveRestaurants = restaurants.filter((restaurant) => restaurant.status !== "active").length; const todayKey = new Date().toISOString().slice(0, 10); const dailySubscriptionSales = subscriptions.filter((subscription) => new Date(subscription.startedAt).toISOString().slice(0, 10) === todayKey).reduce((sum, subscription) => sum + Number(subscription.monthlyPrice ?? 0), 0); const monthlyRecurringRevenue = subscriptions.filter((subscription) => subscription.status === "active").reduce((sum, subscription) => sum + Number(subscription.monthlyPrice ?? 0), 0); const cards = [{ label: "المطاعم النشطة", value: activeRestaurants, icon: Store, tint: "emerald" }, { label: "المطاعم غير النشطة", value: inactiveRestaurants, icon: TrendingDown, tint: "slate" }, { label: "مبيعات الباقات اليوم", value: `${dailySubscriptionSales.toLocaleString("ar-SA")} ر.س`, icon: CircleDollarSign, tint: "orange" }, { label: "الإيراد الشهري المتكرر", value: `${monthlyRecurringRevenue.toLocaleString("ar-SA")} ر.س`, icon: WalletCards, tint: "violet" }]; const loading = !restaurantsQuery.data || !subscriptionsQuery.data; const error = restaurantsQuery.isError || subscriptionsQuery.isError; return <div>{error && <div className="mb-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-xs text-red-700">تعذر تحميل مؤشرات المنصة. Request ID: platform-overview</div>}<Card className="mb-5 rounded-2xl border-orange-100 bg-gradient-to-l from-orange-50 to-white shadow-sm"><CardContent className="flex flex-wrap items-center justify-between gap-4 p-5"><div><p className="text-xs font-semibold text-[#e76f3c]">نظرة عامة للمنصة</p><h3 className="mt-1 text-lg font-bold">مركز نشاط NFOOD</h3><p className="mt-1 text-sm text-slate-500">تابع حالة المطاعم والاشتراكات والإيراد المتكرر من مكان واحد.</p></div><Button onClick={() => onNavigate("admin")} className="rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">إدارة المنصة</Button></CardContent></Card><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map((card) => { const Icon = card.icon; return <Card key={card.label} className="rounded-2xl border-slate-200/80 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-start justify-between"><div className={`flex h-10 w-10 items-center justify-center rounded-xl ${card.tint === "orange" ? "bg-orange-50 text-orange-600" : card.tint === "violet" ? "bg-violet-50 text-violet-600" : card.tint === "emerald" ? "bg-emerald-50 text-emerald-600" : "bg-slate-100 text-slate-600"}`}><Icon className="h-5 w-5" /></div><span className="text-[11px] font-bold text-slate-400">من البيانات</span></div><p className="mt-5 text-xs font-medium text-slate-500">{card.label}</p><p className="mt-1 text-2xl font-bold tracking-tight">{loading ? "جارٍ..." : card.value}</p></CardContent></Card>; })}</div><Card className="mt-6 rounded-2xl border-slate-200/80 bg-white shadow-sm"><CardContent className="p-5"><p className="text-sm font-bold">نشاط المنصة</p><p className="mt-1 text-xs text-slate-500">تُستبدل هذه اللوحة بمحتوى الوحدة عند اختيار عنصر من الشريط الجانبي، وتعود عند الضغط على «نظرة عامة».</p></CardContent></Card></div>; }

function Overview({ orders, advanceOrder, query, setQuery, role, onNavigate, summary, summaryLoading, summaryError }: { orders: Order[]; advanceOrder: (id: string) => void; query: string; setQuery: (value: string) => void; role?: string; onNavigate: (key: NavKey) => void; summary?: { available: boolean; sales: number; orders: number; average: number; avgFulfillmentMinutes: number; newOrders: number; preparing: number; ready: number; completed: number; tables: number }; summaryLoading: boolean; summaryError: boolean }) {
  const statsByRole: Record<string, { label: string; value: string; change: string; icon: typeof CircleDollarSign; tint: string }[]> = { restaurant_admin: [{ label: "مبيعات اليوم", value: "12,840 ر.س", change: "+18.4%", icon: CircleDollarSign, tint: "orange" }, { label: "الطلبات اليوم", value: "186", change: "+12.2%", icon: ShoppingBag, tint: "blue" }, { label: "متوسط قيمة الطلب", value: "69.03 ر.س", change: "+5.6%", icon: WalletCards, tint: "violet" }, { label: "الطاولات المشغولة", value: "18 / 32", change: "56% إشغال", icon: Table2, tint: "emerald" }], waiter: [{ label: "طلبات تنتظر الخدمة", value: "24", change: "جديد", icon: ShoppingBag, tint: "orange" }, { label: "طاولات بها طلبات", value: "0", change: "من بيانات المطعم", icon: Table2, tint: "blue" }, { label: "متوسط دورة الطلب", value: "0 د", change: "من البيانات الفعلية", icon: WalletCards, tint: "violet" }, { label: "طلبات تحتاج متابعة", value: "6", change: "اليوم", icon: CircleDollarSign, tint: "emerald" }], kitchen: [{ label: "طلبات جديدة", value: "14", change: "عاجل", icon: ChefHat, tint: "orange" }, { label: "قيد التحضير", value: "22", change: "الآن", icon: ShoppingBag, tint: "blue" }, { label: "متوسط دورة الطلب", value: "0 د", change: "من البيانات الفعلية", icon: WalletCards, tint: "violet" }, { label: "جاهز للتسليم", value: "9", change: "بانتظار النادل", icon: CheckCircle2, tint: "emerald" }], cashier: [{ label: "طلبات بانتظار الدفع", value: "12", change: "الآن", icon: WalletCards, tint: "orange" }, { label: "مدفوعات اليوم", value: "8,460 ر.س", change: "+9.4%", icon: CircleDollarSign, tint: "blue" }, { label: "متوسط التحصيل", value: "68.20 ر.س", change: "+3.1%", icon: ShoppingBag, tint: "violet" }, { label: "مرتجعات معلقة", value: "2", change: "تحتاج مراجعة", icon: Table2, tint: "emerald" }], customer: [{ label: "الطلبات الجديدة", value: "0", change: "من بيانات المطعم", icon: ShoppingBag, tint: "orange" }, { label: "طلبات مكتملة", value: "0", change: "من بيانات المطعم", icon: CheckCircle2, tint: "blue" }, { label: "إجمالي الطلبات", value: "0", change: "من بيانات المطعم", icon: CircleDollarSign, tint: "violet" }, { label: "طلبات جاهزة", value: "0", change: "من بيانات المطعم", icon: WalletCards, tint: "emerald" }], driver: [{ label: "طلبات مخصصة", value: "7", change: "اليوم", icon: ShoppingBag, tint: "orange" }, { label: "قيد التوصيل", value: "3", change: "الآن", icon: Table2, tint: "blue" }, { label: "متوسط دورة الطلب", value: "0 د", change: "من البيانات الفعلية", icon: WalletCards, tint: "violet" }, { label: "تسليمات مكتملة", value: "31", change: "+12.5%", icon: CheckCircle2, tint: "emerald" }] };
  const baseStats = statsByRole[role ?? "restaurant_admin"] ?? statsByRole.restaurant_admin;
  const liveValues: Record<string, string[]> = { restaurant_admin: [`${(summary?.sales ?? 0).toLocaleString("ar-SA")} ر.س`, String(summary?.orders ?? 0), `${(summary?.average ?? 0).toFixed(2)} ر.س`, `${summary?.tables ?? 0}`], waiter: [String(summary?.newOrders ?? 0), String(summary?.tables ?? 0), `${(summary?.average ?? 0).toFixed(2)} ر.س`, String(summary?.ready ?? 0)], kitchen: [String(summary?.newOrders ?? 0), String(summary?.preparing ?? 0), `${(summary?.avgFulfillmentMinutes ?? 0).toFixed(1)} د`, String(summary?.ready ?? 0)], cashier: [String(summary?.newOrders ?? 0), `${(summary?.sales ?? 0).toLocaleString("ar-SA")} ر.س`, `${(summary?.average ?? 0).toFixed(2)} ر.س`, String(summary?.completed ?? 0)], customer: [String(summary?.newOrders ?? 0), String(summary?.completed ?? 0), String(summary?.orders ?? 0), String(summary?.ready ?? 0)], driver: [String(summary?.newOrders ?? 0), String(summary?.preparing ?? 0), `${(summary?.avgFulfillmentMinutes ?? 0).toFixed(1)} د`, String(summary?.completed ?? 0)] };
  const stats = baseStats.map((stat, index) => ({ ...stat, value: summary ? liveValues[role ?? "restaurant_admin"]?.[index] ?? "غير متاح" : summaryLoading ? "جارٍ..." : "غير متاح", change: summary ? "من البيانات" : summaryLoading ? "جارٍ التحقق" : "من backend فقط" }));
  const roleFocus: Record<string, { title: string; body: string; action: string; target: NavKey }> = { restaurant_admin: { title: "مركز إدارة المطعم", body: "راجع الطلبات والفروع والعمليات اليومية من مساحة المطعم.", action: "فتح الطلبات", target: "orders" }, waiter: { title: "مركز خدمة الطاولات", body: "تابع الطلبات الجديدة وإشغال الطاولات وتواصل مع فريق المطبخ.", action: "فتح الطلبات", target: "orders" }, kitchen: { title: "مركز تشغيل المطبخ", body: "ابدأ بالطلبات الجديدة ثم انقلها إلى التحضير والجاهزية.", action: "فتح KDS", target: "kds" }, cashier: { title: "مركز الكاشير", body: "أنشئ طلبًا جديدًا وتحقق من حالة الدفع والطلبات المكتملة.", action: "فتح POS", target: "pos" }, customer: { title: "مركز العميل", body: "استعرض طلباتك الأخيرة وأعد الطلب من المساحة الموحدة.", action: "عرض الطلبات", target: "orders" }, driver: { title: "مركز التوصيل", body: "تابع الطلبات المخصصة لك وتحديثات مهام التوصيل.", action: "فتح الطلبات", target: "orders" } };
  const focus = dashboardProfiles[(role as keyof typeof dashboardProfiles) ?? "restaurant_admin"] ?? dashboardProfiles.restaurant_admin;
  return <>{summaryError && <div className="mb-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-xs text-red-700">تعذر تحميل مؤشرات الدور. Request ID: role-summary-{role ?? "unknown"}</div>}{summary && summary.orders === 0 && <div className="mb-4 flex items-center gap-3 rounded-xl border border-slate-200 bg-slate-50 px-4 py-4 text-sm text-slate-600"><ShoppingBag className="h-5 w-5 text-slate-400" /><div><p className="font-semibold">لا توجد بيانات تشغيلية بعد</p><p className="mt-1 text-xs text-slate-500">ستظهر مؤشرات هذا الدور بعد تسجيل أول طلب في المطعم.</p></div></div>}<Card className="mb-5 rounded-2xl border-orange-100 bg-gradient-to-l from-orange-50 to-white shadow-sm"><CardContent className="flex flex-wrap items-center justify-between gap-4 p-5"><div><p className="text-xs font-semibold text-[#e76f3c]">مساحة الدور</p><h3 className="mt-1 text-lg font-bold">{focus.title}</h3><p className="mt-1 text-sm text-slate-500">{focus.body}</p></div><div className="flex flex-wrap gap-2"><Button onClick={() => onNavigate(focus.target as NavKey)} className="rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">{focus.action}</Button>{focus.secondary.map((item) => <Button key={item.target} variant="outline" onClick={() => onNavigate(item.target as NavKey)} className="rounded-xl border-orange-200 text-[#c65325] hover:bg-orange-50">{item.label}</Button>)}</div></CardContent></Card><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{stats.map((stat) => { const Icon = stat.icon; return <Card key={stat.label} className="rounded-2xl border-slate-200/80 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-start justify-between"><div className={`flex h-10 w-10 items-center justify-center rounded-xl ${stat.tint === "orange" ? "bg-orange-50 text-orange-600" : stat.tint === "blue" ? "bg-blue-50 text-blue-600" : stat.tint === "violet" ? "bg-violet-50 text-violet-600" : "bg-emerald-50 text-emerald-600"}`}><Icon className="h-5 w-5" /></div><span className="flex items-center gap-1 text-[11px] font-bold text-emerald-600"><ArrowUpLeft className="h-3 w-3" />{stat.change}</span></div><p className="mt-5 text-xs font-medium text-slate-500">{stat.label}</p><p className="mt-1 text-2xl font-bold tracking-tight">{stat.value}</p></CardContent></Card>; })}</div>
    <div className="mt-6 grid gap-6 xl:grid-cols-[1.4fr_1fr]"><Card className="rounded-2xl border-slate-200/80 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-base">أداء المبيعات</CardTitle><p className="mt-1 text-xs text-slate-500">نظرة على مبيعات آخر 7 أيام</p></div><Badge variant="outline" className="rounded-lg border-slate-200 bg-slate-50 px-3 py-1.5 text-xs">هذا الأسبوع <ChevronDown className="mr-1 inline h-3 w-3" /></Badge></CardHeader><CardContent className="p-5"><div className="flex h-[180px] items-center justify-center rounded-xl bg-slate-50 p-6 text-center text-sm text-slate-500">لا تتوفر سلسلة مبيعات يومية محفوظة بعد. ستظهر هنا بعد ربط تقرير الفترة ببيانات الطلبات اليومية.</div><div className="mt-3 flex items-center gap-2 border-t border-slate-100 pt-4 text-xs text-slate-500"><span className="h-2 w-2 rounded-full bg-[#e76f3c]" /> إجمالي المبيعات من المؤشر الحالي <strong className="mr-auto text-sm text-slate-800">{summary ? `${summary.sales.toLocaleString("ar-SA")} ر.س` : "غير متاح"}</strong></div></CardContent></Card>
      <Card className="rounded-2xl border-slate-200/80 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-base">الأصناف الأكثر مبيعاً</CardTitle><p className="mt-1 text-xs text-slate-500">حسب عدد الطلبات</p></div><Button variant="ghost" size="sm" className="text-xs text-[#e76f3c]" onClick={() => onNavigate("menu")}>عرض المنيو</Button></CardHeader><CardContent className="p-5"><div className="rounded-xl bg-slate-50 p-6 text-center text-sm text-slate-500">لا يتوفر تقرير أصناف فعلي بعد. سيظهر الترتيب عند ربط الطلبات ببنودها المحفوظة في orderItems.</div></CardContent></Card></div>
    <Card className="mt-6 rounded-2xl border-slate-200/80 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-base">آخر الطلبات</CardTitle><p className="mt-1 text-xs text-slate-500">تحديث مباشر من نقطة البيع والمطبخ</p></div><div className="flex items-center gap-2"><div className="relative hidden sm:block"><Search className="absolute right-3 top-2.5 h-4 w-4 text-slate-400" /><Input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="بحث في الطلبات" className="h-9 w-44 rounded-lg border-slate-200 pr-9 text-xs" /></div><Button variant="outline" size="sm" className="rounded-lg text-xs" onClick={() => onNavigate("orders")}>عرض الطلبات <ArrowUpLeft className="mr-1 h-3 w-3" /></Button></div></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-right text-sm"><thead className="bg-slate-50/70 text-[11px] text-slate-500"><tr><th className="px-5 py-3 font-medium">رقم الطلب</th><th className="px-5 py-3 font-medium">الطاولة / القناة</th><th className="px-5 py-3 font-medium">الأصناف</th><th className="px-5 py-3 font-medium">الإجمالي</th><th className="px-5 py-3 font-medium">الحالة</th><th className="px-5 py-3 font-medium">إجراء</th></tr></thead><tbody>{orders.length === 0 ? <tr><td colSpan={6} className="px-5 py-12 text-center"><div className="flex flex-col items-center text-slate-400"><ShoppingBag className="mb-3 h-8 w-8" /><p className="text-sm font-semibold">لا توجد طلبات حتى الآن</p><p className="mt-1 text-xs">ستظهر الطلبات الجديدة هنا عند استقبالها من نقطة البيع.</p></div></td></tr> : orders.map((order) => <tr key={order.id} className="border-t border-slate-100 transition-colors hover:bg-slate-50/60"><td className="px-5 py-4 font-bold">{order.id}<div className="mt-0.5 text-[10px] font-normal text-slate-400">{order.time}</div></td><td className="px-5 py-4"><div className="font-medium">{order.table}</div><div className="mt-0.5 text-[11px] text-slate-400">{order.channel}</div></td><td className="max-w-[240px] truncate px-5 py-4 text-xs text-slate-500">{order.items}</td><td className="px-5 py-4 font-bold">{money(order.total)}</td><td className="px-5 py-4"><Badge variant="outline" className={`rounded-lg px-2.5 py-1 text-[11px] ${statusStyles[order.status]}`}>{statusLabels[order.status]}</Badge></td><td className="px-5 py-4"><button onClick={() => order.status !== "completed" ? advanceOrder(order.id) : toast.info("الطلب مكتمل بالفعل")} className="rounded-lg p-2 text-slate-400 hover:bg-orange-50 hover:text-[#e76f3c]" title="تحديث الحالة">{order.status !== "completed" ? <CheckCircle2 className="h-4 w-4" /> : <Eye className="h-4 w-4" />}</button></td></tr>)}</tbody></table></div></CardContent></Card></>;
}

function ModuleView({ active, orders, advanceOrder, setActive, restaurantId, ordersLoading, ordersError, role }: { active: NavKey; orders: Order[]; advanceOrder: (id: string) => void; setActive: (key: NavKey) => void; restaurantId: number; ordersLoading: boolean; ordersError: boolean; role?: string }) {
  const labels: Record<NavKey, { title: string; description: string; icon: typeof LayoutDashboard }> = { overview: { title: "نظرة عامة", description: "", icon: LayoutDashboard }, admin: { title: "Super Admin", description: "إدارة المطاعم والعملاء والاشتراكات والصلاحيات.", icon: ShieldCheck }, accounts: { title: "مركز الحسابات", description: "إدارة الدخول والحالة وبيانات جميع أدوار النظام.", icon: Users }, files: { title: "مدير الملفات", description: "رفع وتنظيم ملفات الحساب أو المطعم ضمن مساحة معزولة.", icon: HardDrive }, branches: { title: "الفروع والإعدادات", description: "إدارة الفروع وساعات العمل وإعداداتها التشغيلية.", icon: Store }, orders: { title: "إدارة الطلبات", description: "تابع الطلبات وحدّث مراحلها من شاشة واحدة.", icon: ShoppingBag }, pos: { title: "نقطة البيع POS", description: "أنشئ طلباً جديداً بسرعة واربطه بالفرع والطاولة.", icon: WalletCards }, kds: { title: "شاشة المطبخ KDS", description: "تنظيم الطلبات الواردة ومتابعة زمن التحضير لحظياً.", icon: ChefHat }, menu: { title: "المنيو والأصناف", description: "إدارة التصنيفات والأصناف والأسعار والتوفر.", icon: Utensils }, tables: { title: "الطاولات", description: "عرض إشغال الطاولات وربطها بالطلبات الحالية.", icon: Table2 }, inventory: { title: "المخزون والمشتريات", description: "متابعة المواد الخام والتنبيهات وتسجيل المشتريات.", icon: Package }, team: { title: "الموظفون والحضور", description: "إدارة الفريق والأدوار وسجل الحضور.", icon: Users }, marketing: { title: "التسويق والحملات", description: "العروض والكوبونات والحملات في مكان واحد.", icon: Megaphone }, reservations: { title: "الحجوزات وقائمة الانتظار", description: "إدارة مواعيد الضيوف وحالات الوصول من مساحة المطعم.", icon: Clock3 }, remote: { title: "التوظيف عن بُعد", description: "أنشئ مهامًا مدفوعة وتواصل مع الموظفين من مكان واحد.", icon: Users }, security: { title: "أمان الحساب والجلسات", description: "أدر الأجهزة والجلسات والتحقق بخطوتين.", icon: ShieldCheck }, health: { title: "صحة النظام", description: "راقب حالة API وقاعدة البيانات والخدمات الأساسية.", icon: Activity } };
  const info = labels[active]; const Icon = info.icon;
  if (active === "orders" && role === "driver") return <DriverDeliveryView restaurantId={restaurantId} />;
  if (active === "orders" || active === "kds") return <><div className="mb-6 flex items-center gap-3"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-orange-50 text-[#e76f3c]"><Icon className="h-6 w-6" /></div><div><h2 className="text-xl font-bold">{info.title}</h2><p className="text-sm text-slate-500">{info.description}</p></div></div>{ordersLoading && <div className="mb-4 rounded-xl bg-slate-100 px-4 py-3 text-sm text-slate-500">جارٍ تحميل الطلبات من قاعدة البيانات...</div>}{ordersError && <div className="mb-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">تعذر تحميل الطلبات. Request ID: orders-{restaurantId}</div>}{!ordersLoading && !ordersError && orders.length === 0 && <div className="mb-4 rounded-xl border border-slate-200 bg-slate-50 px-4 py-4 text-sm text-slate-600">لا توجد طلبات محفوظة لهذا الفرع بعد.</div>}<div className="grid gap-4 md:grid-cols-4">{(["new", "preparing", "ready", "completed"] as OrderStatus[]).map((status) => <Card key={status} className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="px-4 pb-2 pt-4"><CardTitle className="flex items-center justify-between text-sm">{statusLabels[status]}<span className="rounded-full bg-slate-100 px-2 py-0.5 text-xs">{orders.filter((o) => o.status === status).length}</span></CardTitle></CardHeader><CardContent className="space-y-3 p-4 pt-2">{orders.filter((o) => o.status === status).map((order) => <div key={order.id} className="rounded-xl border border-slate-100 bg-slate-50/70 p-3"><div className="flex justify-between text-xs font-bold"><span>{order.id}</span><span className="text-slate-400">{order.time}</span></div><p className="mt-2 text-xs font-medium">{order.table}</p><p className="mt-1 text-[11px] leading-5 text-slate-500">{order.items}</p>{status !== "completed" && <Button onClick={() => advanceOrder(order.id)} size="sm" className="mt-3 h-8 w-full rounded-lg bg-[#e76f3c] text-xs hover:bg-[#d85f2e]">نقل إلى {statusLabels[status === "new" ? "preparing" : status === "preparing" ? "ready" : "completed"]}</Button>}</div>)}</CardContent></Card>)}</div>{active === "kds" && <><KitchenTicketBoard restaurantId={restaurantId} orders={orders} /><KitchenPrinterSettings restaurantId={restaurantId} /></>}</>;
  if (active === "pos") return <PosView restaurantId={restaurantId} />;
  if (active === "menu") return <MenuView restaurantId={restaurantId} />;
  if (active === "tables") return <TablesView restaurantId={restaurantId} />;
  if (active === "inventory") return <InventoryView restaurantId={restaurantId} />;
  if (active === "team") return <TeamView restaurantId={restaurantId} />;
  if (active === "marketing") return <MarketingView restaurantId={restaurantId} />;
  if (active === "reservations") return <ReservationsView restaurantId={restaurantId} />;
  if (active === "admin") return <SuperAdminRestaurantCatalog />;
  if (active === "accounts") return <AccountManagementPanel />;
  if (active === "files") return <MediaLibraryPanel isCentralAdmin={role === "admin"} restaurantId={restaurantId} />;
  if (active === "branches") return <BranchesView restaurantId={restaurantId} />;
  if (active === "remote") return <RemoteWorkView restaurantId={restaurantId} />;
  if (active === "security") return <SecurityView restaurantId={restaurantId} />;
  if (active === "health") return <SystemHealthView />;
  return <div><div className="mb-6 flex items-center gap-3"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-orange-50 text-[#e76f3c]"><Icon className="h-6 w-6" /></div><div><h2 className="text-xl font-bold">{info.title}</h2><p className="text-sm text-slate-500">{info.description}</p></div></div><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="flex min-h-[380px] flex-col items-center justify-center p-8 text-center"><div className="mb-4 flex h-16 w-16 items-center justify-center rounded-3xl bg-orange-50 text-[#e76f3c]"><Icon className="h-8 w-8" /></div><h3 className="text-lg font-bold">وحدة {info.title}</h3><p className="mt-2 max-w-md text-sm leading-7 text-slate-500">تم تجهيز مساحة العمل لهذه الوحدة ضمن النظام الموحد. ستظهر هنا أدوات الإدارة والتقارير والعمليات المرتبطة بالفرع المختار.</p><Button onClick={() => { setActive("overview"); toast.success("تم الرجوع إلى لوحة النظرة العامة"); }} className="mt-6 rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">العودة للوحة الرئيسية</Button></CardContent></Card></div>;
}


type MenuProduct = { id: number; name: string; category: string; price: number; available: boolean };

function MenuView({ restaurantId }: { restaurantId: number }) {
  const { user } = useAuth();
  const remoteMenu = trpc.platform.menuItems.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false });
  const remoteCategories = trpc.platform.menuCategories.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false });
  const kitchenSections = trpc.platform.listKitchenSections.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false });
  const products = useMemo(() => (remoteMenu.data ?? []).map((item) => ({ id: item.id, name: item.name, category: remoteCategories.data?.find((categoryItem) => categoryItem.id === item.categoryId)?.name ?? `تصنيف ${item.categoryId}`, kitchenSectionId: item.kitchenSectionId ?? null, price: Number(item.price), available: item.isAvailable })), [remoteMenu.data, remoteCategories.data]);
  const [category, setCategory] = useState("الكل");
  const [showCreate, setShowCreate] = useState(false);
  const [showCategoryCreate, setShowCategoryCreate] = useState(false);
  const [newCategoryName, setNewCategoryName] = useState("");
  const [newCategoryId, setNewCategoryId] = useState("1");
  const [newKitchenSectionId, setNewKitchenSectionId] = useState("");
  const [newName, setNewName] = useState("");
  const [newPrice, setNewPrice] = useState("");
  const [editingCategoryId, setEditingCategoryId] = useState<number | null>(null);
  const [editingCategoryName, setEditingCategoryName] = useState("");
  const [editingItemId, setEditingItemId] = useState<number | null>(null);
  const [editingItemName, setEditingItemName] = useState("");
  const [editingItemPrice, setEditingItemPrice] = useState("");
  const utils = trpc.useUtils();
  const createMenuCategory = trpc.platform.createMenuCategory.useMutation({ onSuccess: async () => { await utils.platform.menuCategories.invalidate({ restaurantId }); setShowCategoryCreate(false); setNewCategoryName(""); toast.success("تمت إضافة التصنيف"); }, onError: (error) => toast.error(`تعذر إضافة التصنيف: ${error.message}`) });
  const updateMenuCategory = trpc.platform.updateMenuCategory.useMutation({ onSuccess: async () => { await utils.platform.menuCategories.invalidate({ restaurantId }); setEditingCategoryId(null); setEditingCategoryName(""); toast.success("تم تحديث التصنيف"); }, onError: (error) => toast.error(`تعذر تحديث التصنيف: ${error.message}`) });
  const deleteMenuCategory = trpc.platform.deleteMenuCategory.useMutation({ onSuccess: async () => { await utils.platform.menuCategories.invalidate({ restaurantId }); toast.success("تم حذف التصنيف"); }, onError: (error) => toast.error(`تعذر حذف التصنيف: ${error.message}`) });
  const createMenuItem = trpc.platform.createMenuItem.useMutation({ onSuccess: async () => { await utils.platform.menuItems.invalidate({ restaurantId }); setShowCreate(false); setNewName(""); setNewPrice(""); toast.success("تمت إضافة الصنف إلى المنيو"); }, onError: (error) => toast.error(`تعذر إضافة الصنف: ${error.message}`) });
  const updateMenuItem = trpc.platform.updateMenuItem.useMutation({ onSuccess: async () => { await utils.platform.menuItems.invalidate({ restaurantId }); setEditingItemId(null); setEditingItemName(""); setEditingItemPrice(""); toast.success("تم تحديث الصنف"); }, onError: (error) => toast.error(`تعذر تحديث الصنف: ${error.message}`) });
  const deleteMenuItem = trpc.platform.deleteMenuItem.useMutation({ onSuccess: async () => { await utils.platform.menuItems.invalidate({ restaurantId }); toast.success("تم حذف الصنف"); }, onError: (error) => toast.error(`تعذر حذف الصنف: ${error.message}`) });
  const categories = ["الكل", ...(remoteCategories.data ?? []).map((item) => item.name)];
  const shown = products.filter((product) => category === "الكل" || product.category === category);
  return <div><div className="mb-6 flex items-center justify-between"><div><h2 className="text-xl font-bold">المنيو والأصناف</h2><p className="mt-1 text-sm text-slate-500">تحكم سريع في الأصناف والأسعار والتوفر.</p></div><div className="flex gap-2"><Button variant="outline" onClick={() => setShowCategoryCreate((value) => !value)} className="rounded-xl border-slate-200">تصنيف جديد</Button><Button onClick={() => setShowCreate((value) => !value)} className="gap-2 rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]"><Plus className="h-4 w-4" /> إضافة صنف</Button></div></div>{showCreate && <Card className="mb-5 rounded-2xl border-orange-100 bg-orange-50/40"><CardContent className="grid gap-3 p-4 sm:grid-cols-[180px_1fr_180px_auto]"><select value={newCategoryId} onChange={(event) => setNewCategoryId(event.target.value)} className="rounded-xl border border-slate-200 bg-white px-3 text-sm outline-none"><option value="1">اختر التصنيف</option>{(remoteCategories.data ?? []).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><Input value={newName} onChange={(event) => setNewName(event.target.value)} placeholder="اسم الصنف" className="rounded-xl bg-white" /><Input value={newPrice} onChange={(event) => setNewPrice(event.target.value)} placeholder="السعر" inputMode="decimal" className="rounded-xl bg-white" /><select value={newKitchenSectionId} onChange={(event) => setNewKitchenSectionId(event.target.value)} className="rounded-xl border border-slate-200 bg-white px-3 text-sm outline-none"><option value="">قسم المطبخ (اختياري)</option>{(kitchenSections.data ?? []).map((section) => <option key={section.id} value={section.id}>{section.name}</option>)}</select><Button disabled={createMenuItem.isPending || newName.trim().length < 2 || !newPrice} onClick={() => createMenuItem.mutate({ restaurantId, categoryId: Number(newCategoryId), kitchenSectionId: newKitchenSectionId ? Number(newKitchenSectionId) : null, name: newName.trim(), price: newPrice })} className="rounded-xl bg-[#111c2e] hover:bg-[#1b2b43]">{createMenuItem.isPending ? "جارٍ الحفظ..." : "حفظ الصنف"}</Button></CardContent></Card>}{showCategoryCreate && <Card className="mb-5 rounded-2xl border-slate-200 bg-white"><CardContent className="flex gap-3 p-4"><Input value={newCategoryName} onChange={(event) => setNewCategoryName(event.target.value)} placeholder="اسم التصنيف" className="rounded-xl" /><select value={newKitchenSectionId} onChange={(event) => setNewKitchenSectionId(event.target.value)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="">قسم المطبخ (اختياري)</option>{(kitchenSections.data ?? []).map((section) => <option key={section.id} value={section.id}>{section.name}</option>)}</select><Button disabled={createMenuCategory.isPending || newCategoryName.trim().length < 2} onClick={() => createMenuCategory.mutate({ restaurantId, name: newCategoryName.trim(), sortOrder: remoteCategories.data?.length ?? 0, kitchenSectionId: newKitchenSectionId ? Number(newKitchenSectionId) : null })} className="rounded-xl bg-[#111c2e] hover:bg-[#1b2b43]">{createMenuCategory.isPending ? "جارٍ الحفظ..." : "حفظ التصنيف"}</Button></CardContent></Card>}{editingCategoryId && <Card className="mb-5 rounded-2xl border-orange-100 bg-orange-50/40"><CardContent className="grid gap-3 p-4 sm:grid-cols-[1fr_auto_auto]"><Input value={editingCategoryName} onChange={(event) => setEditingCategoryName(event.target.value)} placeholder="اسم التصنيف" className="rounded-xl bg-white" /><Button variant="outline" onClick={() => { setEditingCategoryId(null); setEditingCategoryName(""); }} className="rounded-xl">إلغاء</Button><Button disabled={updateMenuCategory.isPending || editingCategoryName.trim().length < 2} onClick={() => updateMenuCategory.mutate({ restaurantId, id: editingCategoryId, name: editingCategoryName.trim() })} className="rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">{updateMenuCategory.isPending ? "جارٍ الحفظ..." : "حفظ التعديل"}</Button></CardContent></Card>}{editingItemId && <Card className="mb-5 rounded-2xl border-orange-100 bg-orange-50/40"><CardContent className="grid gap-3 p-4 sm:grid-cols-[1fr_180px_auto_auto]"><Input value={editingItemName} onChange={(event) => setEditingItemName(event.target.value)} placeholder="اسم الصنف" className="rounded-xl bg-white" /><Input value={editingItemPrice} onChange={(event) => setEditingItemPrice(event.target.value)} placeholder="السعر" inputMode="decimal" className="rounded-xl bg-white" /><Button variant="outline" onClick={() => { setEditingItemId(null); setEditingItemName(""); setEditingItemPrice(""); }} className="rounded-xl">إلغاء</Button><Button disabled={updateMenuItem.isPending || editingItemName.trim().length < 2 || !editingItemPrice.trim()} onClick={() => updateMenuItem.mutate({ restaurantId, id: editingItemId, name: editingItemName.trim(), price: editingItemPrice.trim() })} className="rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">{updateMenuItem.isPending ? "جارٍ الحفظ..." : "حفظ التعديل"}</Button></CardContent></Card>}{showCategoryCreate && (remoteCategories.data?.length ?? 0) > 0 ? <Card className="mb-5 rounded-2xl border-slate-200 bg-white"><CardContent className="space-y-2 p-4">{(remoteCategories.data ?? []).map((item) => <div key={item.id} className="flex items-center justify-between rounded-xl bg-slate-50 px-3 py-2"><span className="text-sm font-semibold">{item.name}</span><div className="flex gap-1"><button onClick={() => { setEditingCategoryId(item.id); setEditingCategoryName(item.name); setShowCategoryCreate(true); }} className="rounded-lg px-2 py-1 text-xs text-slate-500 hover:bg-orange-50">تعديل</button><button onClick={() => { deleteMenuCategory.mutate({ restaurantId, id: item.id }); }} className="rounded-lg px-2 py-1 text-xs text-red-500 hover:bg-red-50">حذف</button></div></div>)}</CardContent></Card> : null}<div className="mb-5 flex gap-2 overflow-x-auto">{categories.map((item) => <button key={item} onClick={() => setCategory(item)} className={`shrink-0 rounded-xl px-4 py-2 text-xs font-semibold ${category === item ? "bg-[#111c2e] text-white" : "bg-white text-slate-500 shadow-sm"}`}>{item}</button>)}</div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{remoteMenu.isLoading ? <div className="col-span-full rounded-2xl bg-slate-50 p-10 text-center text-sm text-slate-500">جارٍ تحميل الأصناف من قاعدة البيانات...</div> : remoteMenu.isError ? <div className="col-span-full rounded-2xl border border-red-200 bg-red-50 p-10 text-center text-sm text-red-700">تعذر تحميل الأصناف. <button onClick={() => void remoteMenu.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : shown.length === 0 ? <div className="col-span-full rounded-2xl bg-slate-50 p-10 text-center text-sm text-slate-500">لا توجد أصناف محفوظة لهذا المطعم بعد.</div> : shown.map((product) => <Card key={product.name} className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="mb-4 flex items-start justify-between"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-orange-50 text-xl">🍽</div><button onClick={() => { const next = !product.available; if (remoteMenu.data?.some((item) => item.id === product.id)) updateMenuItem.mutate({ restaurantId, id: product.id, isAvailable: next }); }} className={`rounded-lg px-2.5 py-1 text-[10px] font-bold ${product.available ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-500"}`}>{product.available ? "متوفر" : "غير متوفر"}</button></div><h3 className="font-bold">{product.name}</h3><p className="mt-1 text-xs text-slate-400">{product.category}</p><div className="mt-4 flex items-center justify-between border-t border-slate-100 pt-3"><span className="text-lg font-bold">{money(product.price)}</span><div className="flex items-center gap-1"><button onClick={() => { setEditingItemId(product.id); setEditingItemName(product.name); setEditingItemPrice(String(product.price)); setShowCreate(true); }} className="rounded-lg p-2 text-slate-400 hover:bg-orange-50 hover:text-[#e76f3c]" aria-label={`تعديل ${product.name}`}><MoreHorizontal className="h-4 w-4" /></button><button onClick={() => { if (remoteMenu.data?.some((item) => item.id === product.id)) deleteMenuItem.mutate({ restaurantId, id: product.id }); }} className="rounded-lg px-2 py-1 text-[10px] font-semibold text-red-500 hover:bg-red-50">حذف</button></div></div></CardContent></Card>)}</div></div>;
}

function PosView({ restaurantId }: { restaurantId: number }) {
  const { user } = useAuth();
  const { t } = useLanguage();
  const remoteMenu = trpc.platform.menuItems.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false });
  const remoteBranches = trpc.platform.branches.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false });
  const branchId = remoteBranches.data?.[0]?.id;
  const posProducts: MenuProduct[] = (remoteMenu.data ?? []).map((item) => ({ id: item.id, name: item.name, category: String(item.categoryId), price: Number(item.price), available: item.isAvailable }));
  const [cart, setCart] = useState<{ product: MenuProduct; quantity: number }[]>([]);
  const [isOnline, setIsOnline] = useState(() => typeof navigator === "undefined" ? true : navigator.onLine);
  const [queuedCount, setQueuedCount] = useState(0);
  const [tableName, setTableName] = useState("");
  const [paymentMethod, setPaymentMethod] = useState<"cash" | "card" | "bank_transfer" | "online" | "other">("cash");
  const createOrder = trpc.platform.createOrder.useMutation({ onSuccess: (result) => { toast.success(`تم حفظ الطلب #${result.orderId} وإرساله للمطبخ`); setCart([]); }, onError: (error) => toast.error(`تعذر حفظ الطلب: ${error.message}`) });
  const queueKey = `nfood-offline-orders:${restaurantId ?? "none"}:${branchId ?? "none"}`;
  const readQueue = () => readOfflineQueue<Parameters<typeof createOrder.mutate>[0]>(localStorage, queueKey);
  const syncQueue = async () => { if (!navigator.onLine || !branchId) return; const queue = readQueue(); let remaining = [...queue]; for (const payload of queue) { try { const { offlineId: _offlineId, ...orderPayload } = payload; await createOrder.mutateAsync(orderPayload); remaining = remaining.slice(1); writeOfflineQueue(localStorage, queueKey, remaining); setQueuedCount(remaining.length); } catch { break; } } if (queue.length > 0 && remaining.length === 0) toast.success(`تمت مزامنة ${queue.length} طلبات محفوظة`); };
  const submitOrder = () => { if (!branchId) { toast.error("لا يوجد فرع مرتبط لاستقبال الطلب"); return; } const payload = { restaurantId, branchId, channel: channel === "داخل المطعم" ? "dine_in" as const : channel === "استلام" ? "takeaway" as const : "delivery" as const, total: total.toFixed(2), tableName: tableName.trim() || undefined, paymentMethod, items: cart.map((item) => ({ menuItemId: item.product.id, quantity: item.quantity, unitPrice: item.product.price.toFixed(2) })) }; if (!isOnline) { const queue = enqueueOfflineItem(localStorage, queueKey, payload, crypto.randomUUID()); setQueuedCount(queue.length); setCart([]); toast.info("تم حفظ الطلب محليًا وسيُرسل تلقائيًا عند عودة الاتصال"); return; } createOrder.mutate(payload); };
  useEffect(() => { const refresh = () => { setIsOnline(navigator.onLine); setQueuedCount(readQueue().length); if (navigator.onLine) void syncQueue(); }; setQueuedCount(readQueue().length); window.addEventListener("online", refresh); window.addEventListener("offline", refresh); window.addEventListener("nfood:sync-request", refresh); if (navigator.onLine) void syncQueue(); return () => { window.removeEventListener("online", refresh); window.removeEventListener("offline", refresh); window.removeEventListener("nfood:sync-request", refresh); }; }, [queueKey, branchId, createOrder]);
  const [channel, setChannel] = useState("داخل المطعم");
  const total = cart.reduce((sum, item) => sum + item.product.price * item.quantity, 0);
  const add = (product: MenuProduct) => setCart((items) => { const found = items.find((item) => item.product.name === product.name); return found ? items.map((item) => item.product.name === product.name ? { ...item, quantity: item.quantity + 1 } : item) : [...items, { product, quantity: 1 }]; });
  return <div><div className="mb-6 flex items-center justify-between"><div><h2 className="text-xl font-bold">نقطة البيع POS</h2><p className="mt-1 text-sm text-slate-500">أنشئ طلباً جديداً واختر القناة والطاولة ووسيلة الدفع؛ تُحفظ حالة الدفع غير مدفوعة حتى تأكيد مزود خارجي.</p></div><Badge className={`rounded-lg ${isOnline ? "bg-emerald-50 text-emerald-700 hover:bg-emerald-50" : "bg-amber-50 text-amber-700 hover:bg-amber-50"}`}><Activity className="ml-1 h-3.5 w-3.5" /> {isOnline ? "متصل" : "وضع عدم الاتصال"}{queuedCount > 0 && ` · ${queuedCount} بانتظار المزامنة`}</Badge></div><div className="grid gap-5 xl:grid-cols-[1fr_360px]"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="border-b border-slate-100 px-5 py-4"><div className="flex items-center justify-between"><CardTitle className="text-base">الأصناف المتاحة</CardTitle><div className="flex gap-2">{["داخل المطعم", "استلام", "توصيل"].map((item) => <button key={item} onClick={() => setChannel(item)} className={`rounded-lg px-3 py-1.5 text-[11px] font-semibold ${channel === item ? "bg-orange-50 text-[#e76f3c]" : "text-slate-400"}`}>{item}</button>)}</div></div></CardHeader><CardContent className="grid gap-3 p-5 sm:grid-cols-2 lg:grid-cols-3">{remoteMenu.isLoading ? <div className="col-span-full rounded-2xl bg-slate-50 p-10 text-center text-sm text-slate-500">جارٍ تحميل الأصناف...</div> : remoteMenu.isError ? <div className="col-span-full rounded-2xl border border-red-200 bg-red-50 p-10 text-center text-sm text-red-700">تعذر تحميل الأصناف. <button onClick={() => void remoteMenu.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : posProducts.filter((product) => product.available).length === 0 ? <div className="col-span-full rounded-2xl bg-slate-50 p-10 text-center text-sm text-slate-500">لا توجد أصناف متاحة للبيع لهذا المطعم.</div> : posProducts.filter((product) => product.available).map((product) => <button key={product.name} onClick={() => add(product)} className="rounded-2xl border border-slate-100 bg-slate-50/60 p-4 text-right transition hover:border-orange-200 hover:bg-orange-50/40"><div className="flex items-center justify-between"><span className="text-xl">🍽</span><Plus className="h-4 w-4 text-[#e76f3c]" /></div><p className="mt-4 text-sm font-bold">{product.name}</p><p className="mt-1 text-xs text-slate-500">{money(product.price)}</p></button>)}</CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="border-b border-slate-100 px-5 py-4"><CardTitle className="flex items-center justify-between text-base">الطلب الحالي<span className="text-xs font-normal text-slate-400">{channel}</span></CardTitle></CardHeader><CardContent className="p-5"><div className="mb-4 grid gap-2 sm:grid-cols-2"><Input value={tableName} onChange={(event) => setTableName(event.target.value)} placeholder="رقم الطاولة (اختياري)" className="rounded-xl" /><select value={paymentMethod} onChange={(event) => setPaymentMethod(event.target.value as typeof paymentMethod)} aria-label="وسيلة الدفع" className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-xs text-slate-700 outline-none focus:border-orange-400"><option value="cash">نقدي</option><option value="card">بطاقة</option><option value="bank_transfer">تحويل بنكي</option><option value="online">دفع إلكتروني</option><option value="other">أخرى</option></select></div><div className="min-h-[220px] space-y-3">{cart.length === 0 ? <div className="flex h-[220px] flex-col items-center justify-center text-center text-slate-400"><ShoppingBag className="mb-3 h-8 w-8" /><p className="text-sm">السلة فارغة</p><p className="mt-1 text-xs">اختر صنفاً لإضافته للطلب</p></div> : cart.map((item) => <div key={item.product.name} className="flex items-center justify-between rounded-xl bg-slate-50 p-3"><div><p className="text-xs font-bold">{item.product.name}</p><p className="mt-1 text-[11px] text-slate-400">{item.quantity} × {money(item.product.price)}</p></div><div className="flex items-center gap-2"><button onClick={() => setCart((items) => items.flatMap((current) => current.product.name === item.product.name ? current.quantity > 1 ? [{ ...current, quantity: current.quantity - 1 }] : [] : [current]))} className="rounded-md bg-white px-2 py-1 text-xs">−</button><span className="text-xs font-bold">{item.quantity}</span><button onClick={() => add(item.product)} className="rounded-md bg-white px-2 py-1 text-xs">+</button></div></div>)}</div><div className="border-t border-slate-100 pt-4"><div className="mb-3 flex justify-between text-sm"><span className="text-slate-500">الإجمالي</span><strong className="text-lg">{money(total)}</strong></div><Button disabled={!cart.length || !branchId || createOrder.isPending} onClick={submitOrder} className="w-full rounded-xl bg-[#e76f3c] py-5 hover:bg-[#d85f2e]">{remoteBranches.isLoading ? t("loadingBranches") : !branchId ? "لا يوجد فرع مرتبط" : createOrder.isPending ? "جارٍ حفظ الطلب..." : "إرسال الطلب للمطبخ"}</Button></div></CardContent></Card></div></div>;
}


function AccessDeniedView({ feature }: { feature: string }) {
  return <Card className="rounded-2xl border-amber-200 bg-amber-50 shadow-sm"><CardContent className="flex min-h-[360px] flex-col items-center justify-center p-8 text-center"><div className="mb-4 flex h-16 w-16 items-center justify-center rounded-3xl bg-white text-amber-600 shadow-sm"><ShieldCheck className="h-8 w-8" /></div><h2 className="text-xl font-bold text-slate-900">403 · الوصول غير مسموح</h2><p className="mt-3 max-w-md text-sm leading-7 text-slate-600">لا تملك صلاحية استخدام هذه الوحدة أو أن الميزة غير مفعّلة ضمن باقة مطعمك.</p><p className="mt-2 font-mono text-[11px] text-slate-400">feature: {feature}</p></CardContent></Card>;
}

function SystemHealthView() {
  const [timestamp] = useState(() => Date.now());
  const health = trpc.system.health.useQuery({ timestamp }, { retry: false, refetchInterval: 30000 });
  const auditLogsQuery = trpc.platform.auditLogs.useQuery(undefined, { retry: false, refetchInterval: 15000 });
  const requestId = `health-${timestamp.toString(36)}`;
  return <div><div className="mb-6"><h2 className="text-xl font-bold">صحة النظام</h2><p className="mt-1 text-sm text-slate-500">مراقبة سريعة لحالة API وقاعدة البيانات والخدمات الأساسية.</p></div>{health.isError ? <Card className="rounded-2xl border-red-200 bg-red-50 shadow-sm"><CardContent className="p-6"><p className="font-bold text-red-700">تعذر فحص صحة النظام</p><p className="mt-2 text-xs text-red-600">رقم الطلب: {requestId}</p><Button onClick={() => health.refetch()} className="mt-4 rounded-xl bg-red-600 hover:bg-red-700">إعادة المحاولة</Button></CardContent></Card> : <div className="grid gap-4 md:grid-cols-3"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><p className="text-xs text-slate-500">واجهة API</p><p className="mt-2 text-lg font-bold text-emerald-700">{health.isLoading ? "جارٍ الفحص..." : health.data?.api === "healthy" ? "تعمل" : "غير متاحة"}</p></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><p className="text-xs text-slate-500">قاعدة البيانات</p><p className="mt-2 text-lg font-bold">{health.isLoading ? "جارٍ الفحص..." : health.data?.database === "configured" ? "مهيأة" : "غير متاحة"}</p></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><p className="text-xs text-slate-500">آخر فحص</p><p className="mt-2 text-sm font-bold">{health.data?.checkedAt ? new Date(health.data.checkedAt).toLocaleString("ar-SA") : "—"}</p><p className="mt-2 text-[10px] text-slate-400">Request ID: {requestId}</p></CardContent></Card></div>}<Card className="mt-5 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="flex flex-row items-center justify-between border-b border-slate-100"><CardTitle className="text-base">آخر أحداث التدقيق</CardTitle><Button variant="outline" onClick={() => auditLogsQuery.refetch()} className="rounded-xl text-xs">تحديث</Button></CardHeader><CardContent className="space-y-2 p-5">{auditLogsQuery.isLoading ? <div className="h-14 animate-pulse rounded-xl bg-slate-100" /> : auditLogsQuery.isError ? <p className="rounded-xl bg-red-50 p-4 text-sm text-red-700">تعذر تحميل سجل التدقيق. Request ID: audit-{timestamp.toString(36)}</p> : (auditLogsQuery.data ?? []).length === 0 ? <p className="rounded-xl bg-slate-50 p-5 text-center text-sm text-slate-500">لا توجد أحداث تدقيق بعد.</p> : (auditLogsQuery.data ?? []).slice(0, 8).map((event) => <div key={event.id} className="flex items-center justify-between rounded-xl border border-slate-100 p-3"><div><p className="text-sm font-semibold">{event.action}</p><p className="mt-1 text-[11px] text-slate-500">{event.entityType || "نظام"} {event.entityId ? `#${event.entityId}` : ""} · {event.actorRole || "غير معروف"}</p></div><div className="text-left"><Badge className={event.outcome === "success" ? "bg-emerald-50 text-emerald-700" : "bg-red-50 text-red-700"}>{event.outcome === "success" ? "ناجح" : event.outcome === "denied" ? "مرفوض" : "فشل"}</Badge><p className="mt-1 text-[10px] text-slate-400">{new Date(event.createdAt).toLocaleString("ar-SA")}</p></div></div>)}</CardContent></Card></div>;
}
function RestaurantRolePanel({ restaurantId }: { restaurantId: number }) { const { user } = useAuth(); const utils = trpc.useUtils(); const rolesQuery = trpc.platform.restaurantRoles.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false }); const permissionsQuery = trpc.platform.restaurantPermissions.useQuery(undefined, { enabled: Boolean(user), retry: false }); const [selectedRoleId, setSelectedRoleId] = useState<number | undefined>(); const rolePermissionsQuery = trpc.platform.restaurantRolePermissions.useQuery({ restaurantId, roleId: selectedRoleId ?? 0 }, { enabled: Boolean(selectedRoleId), retry: false }); const [selectedPermissionIds, setSelectedPermissionIds] = useState<number[]>([]); const [roleFormOpen, setRoleFormOpen] = useState(false); const [roleName, setRoleName] = useState(""); const [editingRoleId, setEditingRoleId] = useState<number | null>(null); const [pendingDeleteRoleId, setPendingDeleteRoleId] = useState<number | null>(null); useEffect(() => { setSelectedRoleId((current) => current && (rolesQuery.data ?? []).some((role) => role.id === current) ? current : rolesQuery.data?.[0]?.id); }, [rolesQuery.data]); useEffect(() => { setSelectedPermissionIds((rolePermissionsQuery.data ?? []).map((permission) => permission.permissionId)); }, [rolePermissionsQuery.data]); const createRole = trpc.platform.createRestaurantRole.useMutation({ onSuccess: () => { void utils.platform.restaurantRoles.invalidate(); toast.success("تم إنشاء دور المطعم"); }, onError: (error) => toast.error(`تعذر إنشاء الدور: ${error.message}`) }); const updateRole = trpc.platform.updateRestaurantRole.useMutation({ onSuccess: () => { void utils.platform.restaurantRoles.invalidate(); toast.success("تم تحديث دور المطعم"); }, onError: (error) => toast.error(`تعذر تحديث الدور: ${error.message}`) }); const deleteRole = trpc.platform.deleteRestaurantRole.useMutation({ onSuccess: () => { void utils.platform.restaurantRoles.invalidate(); toast.success("تم حذف دور المطعم"); }, onError: (error) => toast.error(`تعذر حذف الدور: ${error.message}`) }); const setPermissions = trpc.platform.setRestaurantRolePermissions.useMutation({ onSuccess: () => { void rolePermissionsQuery.refetch(); toast.success("تم حفظ صلاحيات الدور"); }, onError: (error) => toast.error(`تعذر حفظ الصلاحيات: ${error.message}`) }); const roles = rolesQuery.data ?? []; return <Card className="mt-5 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader><CardTitle className="text-base">أدوار المطعم وصلاحياته</CardTitle><p className="mt-1 text-xs text-slate-500">إدارة أدوار فريق هذا المطعم فقط مع حفظ الصلاحيات في قاعدة البيانات.</p></CardHeader><CardContent>{roleFormOpen && <div className="mb-4 grid gap-2 rounded-2xl border border-orange-100 bg-orange-50/50 p-4 sm:grid-cols-[1fr_auto_auto]"><Input value={roleName} onChange={(event) => setRoleName(event.target.value)} placeholder="اسم الدور" className="rounded-xl bg-white" /><Button disabled={roleName.trim().length < 2 || createRole.isPending || updateRole.isPending} onClick={() => { if (editingRoleId !== null) updateRole.mutate({ restaurantId, id: editingRoleId, name: roleName.trim() }); else createRole.mutate({ restaurantId, name: roleName.trim() }); setRoleFormOpen(false); setEditingRoleId(null); setRoleName(""); }} className="rounded-xl bg-[#e76f3c]">{createRole.isPending || updateRole.isPending ? "جارٍ الحفظ..." : editingRoleId !== null ? "حفظ التعديل" : "إنشاء الدور"}</Button><Button variant="outline" onClick={() => { setRoleFormOpen(false); setEditingRoleId(null); setRoleName(""); }} className="rounded-xl">إلغاء</Button></div>}{rolesQuery.isError || permissionsQuery.isError ? <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">تعذر تحميل أدوار المطعم. Request ID: restaurant-roles-{restaurantId} <button onClick={() => { void rolesQuery.refetch(); void permissionsQuery.refetch(); }} className="font-bold underline">إعادة المحاولة</button></div> : rolesQuery.isLoading || permissionsQuery.isLoading ? <div className="h-28 animate-pulse rounded-xl bg-slate-100" /> : roles.length === 0 ? <div className="space-y-3"><p className="rounded-xl bg-slate-50 p-5 text-center text-sm text-slate-500">لا توجد أدوار مخصصة لهذا المطعم بعد.</p><Button onClick={() => { setEditingRoleId(null); setRoleName(""); setRoleFormOpen(true); }} className="rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">إنشاء أول دور</Button></div> : <div className="space-y-4"><div className="flex flex-wrap gap-2">{roles.map((role) => <div key={role.id} className={`flex items-center gap-2 rounded-xl border px-3 py-2 text-xs ${selectedRoleId === role.id ? "border-orange-300 bg-orange-50" : "border-slate-200"}`}><button onClick={() => setSelectedRoleId(role.id)} className="font-semibold">{role.name}</button><button onClick={() => { setEditingRoleId(role.id); setRoleName(role.name); setRoleFormOpen(true); }} className="text-slate-500">تعديل</button><button onClick={() => setPendingDeleteRoleId(role.id)} className="text-red-500">حذف</button>{pendingDeleteRoleId === role.id && <span className="flex items-center gap-1 rounded-lg bg-red-50 px-2 py-1 text-[10px] text-red-700"><span>تأكيد؟</span><button onClick={() => { deleteRole.mutate({ restaurantId, id: role.id }); setPendingDeleteRoleId(null); }} className="font-bold underline">نعم</button><button onClick={() => setPendingDeleteRoleId(null)} className="font-bold underline">لا</button></span>}</div>)}<Button variant="outline" onClick={() => { setEditingRoleId(null); setRoleName(""); setRoleFormOpen(true); }} className="rounded-xl text-xs">دور جديد</Button></div>{rolePermissionsQuery.isError ? <p className="rounded-xl bg-red-50 p-4 text-sm text-red-700">تعذر تحميل صلاحيات الدور. Request ID: restaurant-role-permissions-{restaurantId}</p> : rolePermissionsQuery.isLoading ? <div className="h-20 animate-pulse rounded-xl bg-slate-100" /> : <><div className="grid gap-2 sm:grid-cols-2">{(permissionsQuery.data ?? []).map((permission) => <label key={permission.id} className="flex items-center gap-2 rounded-xl border border-slate-100 p-3 text-xs"><input type="checkbox" checked={selectedPermissionIds.includes(permission.id)} onChange={(event) => setSelectedPermissionIds((current) => event.target.checked ? Array.from(new Set([...current, permission.id])) : current.filter((id) => id !== permission.id))} /><span>{permission.label}</span></label>)}</div><Button disabled={!selectedRoleId || setPermissions.isPending} onClick={() => selectedRoleId && setPermissions.mutate({ restaurantId, roleId: selectedRoleId, permissionIds: selectedPermissionIds })} className="rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">{setPermissions.isPending ? "جارٍ الحفظ..." : "حفظ صلاحيات الدور"}</Button></>}</div>}</CardContent></Card>; }

function SecurityView({ restaurantId }: { restaurantId?: number }) {
  const sessionsQuery = trpc.security.sessions.useQuery(undefined, { retry: false });
  const securityQuery = trpc.security.security.useQuery(undefined, { retry: false });
  const utils = trpc.useUtils();
  const revokeAll = trpc.security.revokeAllSessions.useMutation({ onSuccess: () => { toast.success("تم تسجيل الخروج من جميع الأجهزة"); sessionsQuery.refetch(); } });
  const setTwoFactor = trpc.security.setTwoFactor.useMutation({ onSuccess: (result) => { toast.success(result.enabled ? "تم تفعيل 2FA" : "تم تعطيل 2FA"); utils.security.security.invalidate(); } });
  const twoFactorEnabled = securityQuery.data?.twoFactorEnabled ?? false;
  return <div><div className="mb-6"><h2 className="text-xl font-bold">أمان الحساب والجلسات</h2><p className="mt-1 text-sm text-slate-500">إدارة الأجهزة المسجلة وخيارات الحماية من داخل الحساب.</p></div><div className="grid gap-5 lg:grid-cols-[1fr_360px]"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="flex flex-row items-center justify-between border-b border-slate-100"><CardTitle className="text-base">الأجهزة والجلسات</CardTitle><Button variant="outline" onClick={() => revokeAll.mutate()} disabled={revokeAll.isPending} className="rounded-xl text-xs text-red-600">تسجيل الخروج من الجميع</Button></CardHeader><CardContent className="space-y-3 p-5">{sessionsQuery.isLoading ? <div className="h-16 animate-pulse rounded-xl bg-slate-100" /> : (sessionsQuery.data ?? []).length === 0 ? <p className="rounded-xl bg-slate-50 p-6 text-center text-sm text-slate-500">لا توجد جلسات محفوظة.</p> : (sessionsQuery.data ?? []).map((session) => <div key={session.id} className="flex items-center justify-between rounded-xl border border-slate-100 p-4"><div><p className="text-sm font-semibold">{session.deviceLabel || "جهاز غير معروف"}</p><p className="mt-1 text-xs text-slate-500">{session.ipAddress || "IP غير متاح"} · آخر نشاط {new Date(session.lastSeenAt).toLocaleString("ar-SA")}</p></div><Badge className={session.revokedAt ? "bg-slate-100 text-slate-500" : "bg-emerald-50 text-emerald-700"}>{session.revokedAt ? "منتهية" : "نشطة"}</Badge></div>)}</CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader><CardTitle className="text-base">التحقق بخطوتين</CardTitle></CardHeader><CardContent><p className="mb-5 text-sm leading-6 text-slate-500">أضف طبقة حماية إضافية للحساب. تفعيل 2FA هنا محفوظ فعليًا ويمكن ربطه بمزود OTP في المرحلة التالية.</p><Button onClick={() => setTwoFactor.mutate({ enabled: !twoFactorEnabled })} disabled={setTwoFactor.isPending} className={`w-full rounded-xl ${twoFactorEnabled ? "bg-emerald-600 hover:bg-emerald-700" : "bg-[#e76f3c] hover:bg-[#d85f2e]"}`}>{twoFactorEnabled ? "2FA مفعّل — تعطيل" : "تفعيل 2FA"}</Button></CardContent></Card></div>{restaurantId ? <RestaurantRolePanel restaurantId={restaurantId} /> : null}</div>;
}

function SectionHeading({ title, description, action, onAction }: { title: string; description: string; action?: string; onAction?: () => void }) { return <div className="mb-6 flex items-center justify-between"><div><h2 className="text-xl font-bold">{title}</h2><p className="mt-1 text-sm text-slate-500">{description}</p></div>{action && onAction ? <Button onClick={onAction} className="gap-2 rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]"><Plus className="h-4 w-4" /> {action}</Button> : null}</div>; }

function TablesView({ restaurantId }: { restaurantId: number }) { const { user } = useAuth(); const utils = trpc.useUtils(); const [tableFormOpen, setTableFormOpen] = useState(false); const [tableBranchId, setTableBranchId] = useState(""); const [tableName, setTableName] = useState(""); const [tableSeats, setTableSeats] = useState("2"); const remoteTables = trpc.platform.tables.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false }); const createTable = trpc.platform.createTable.useMutation({ onSuccess: () => { void utils.platform.tables.invalidate(); toast.success("تمت إضافة الطاولة"); }, onError: (error) => toast.error(`تعذر إضافة الطاولة: ${error.message}`) }); const updateTable = trpc.platform.updateTableStatus.useMutation({ onSuccess: () => { void utils.platform.tables.invalidate(); toast.success("تم تحديث حالة الطاولة"); }, onError: (error) => toast.error(`تعذر تحديث الطاولة: ${error.message}`) }); const deleteTable = trpc.platform.deleteTable.useMutation({ onSuccess: () => { void utils.platform.tables.invalidate(); toast.success("تم حذف الطاولة"); }, onError: (error) => toast.error(`تعذر حذف الطاولة: ${error.message}`) }); const tables = remoteTables.data ?? []; return <div><SectionHeading title="إدارة الطاولات" description="حالة الطاولات محفوظة في قاعدة البيانات مع عزل المطعم." action="إضافة طاولة" onAction={() => setTableFormOpen((value) => !value)} />{tableFormOpen && <Card className="mb-4 rounded-2xl border-orange-100 bg-orange-50/40"><CardContent className="grid gap-3 p-4 sm:grid-cols-[150px_1fr_150px_auto]"><Input value={tableBranchId} onChange={(event) => setTableBranchId(event.target.value)} inputMode="numeric" placeholder="رقم الفرع" className="rounded-xl bg-white" /><Input value={tableName} onChange={(event) => setTableName(event.target.value)} placeholder="اسم الطاولة" className="rounded-xl bg-white" /><Input value={tableSeats} onChange={(event) => setTableSeats(event.target.value)} inputMode="numeric" placeholder="عدد المقاعد" className="rounded-xl bg-white" /><Button disabled={createTable.isPending || !Number.isInteger(Number(tableBranchId)) || Number(tableBranchId) < 1 || tableName.trim().length < 1 || !Number.isInteger(Number(tableSeats)) || Number(tableSeats) < 1} onClick={() => createTable.mutate({ restaurantId, branchId: Number(tableBranchId), name: tableName.trim(), seats: Number(tableSeats) })} className="rounded-xl bg-[#e76f3c]">{createTable.isPending ? "جارٍ الحفظ..." : "حفظ الطاولة"}</Button></CardContent></Card>}<Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="grid grid-cols-2 gap-4 p-6 sm:grid-cols-3 md:grid-cols-4 xl:grid-cols-6">{remoteTables.isError ? <div className="col-span-full p-6 text-sm text-red-600">تعذر تحميل الطاولات. Request ID: tables-{restaurantId} <button onClick={() => void remoteTables.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : remoteTables.isLoading ? <div className="col-span-full p-6 text-center text-sm text-slate-400">جارٍ تحميل الطاولات...</div> : tables.length === 0 ? <div className="col-span-full p-8 text-center text-sm text-slate-400">لا توجد طاولات محفوظة لهذا المطعم.</div> : tables.map((table) => { const occupied = table.status === "occupied"; return <div key={table.id} onClick={() => updateTable.mutate({ restaurantId, tableId: table.id, status: occupied ? "available" : "occupied" })} className={`relative flex aspect-square flex-col items-center justify-center rounded-3xl border-2 transition-all ${occupied ? "border-orange-200 bg-orange-50 text-orange-700" : "border-emerald-200 bg-emerald-50 text-emerald-700"}`}><Table2 className="mb-2 h-7 w-7" /><span className="text-sm font-bold">{table.name}</span><span className="mt-1 text-[10px]">{occupied ? "مشغولة" : table.status === "reserved" ? "محجوزة" : "متاحة"}</span>{occupied && <span className="absolute right-3 top-3 h-2 w-2 rounded-full bg-orange-500" />}<button type="button" onClick={(event) => { event.stopPropagation(); deleteTable.mutate({ restaurantId, tableId: table.id }); }} className="absolute bottom-3 rounded-md bg-white/80 px-2 py-1 text-[10px] text-red-500">حذف</button></div>; })}</CardContent></Card></div>; }

function InventoryView({ restaurantId }: { restaurantId: number }) { const { user } = useAuth(); const utils = trpc.useUtils(); const [inventoryFormOpen, setInventoryFormOpen] = useState(false); const [purchaseFormOpen, setPurchaseFormOpen] = useState(false); const [inventoryName, setInventoryName] = useState(""); const [inventoryUnit, setInventoryUnit] = useState("كجم"); const [inventoryQuantity, setInventoryQuantity] = useState("0"); const [inventoryMinimum, setInventoryMinimum] = useState("0"); const [purchaseSupplier, setPurchaseSupplier] = useState(""); const [purchaseTotal, setPurchaseTotal] = useState(""); const [editingInventoryId, setEditingInventoryId] = useState<number | null>(null); const [editingInventoryName, setEditingInventoryName] = useState(""); const [editingInventoryUnit, setEditingInventoryUnit] = useState(""); const [editingInventoryMinimum, setEditingInventoryMinimum] = useState("0"); const [editingPurchaseId, setEditingPurchaseId] = useState<number | null>(null); const [editingPurchaseSupplier, setEditingPurchaseSupplier] = useState(""); const [editingPurchaseTotal, setEditingPurchaseTotal] = useState(""); const [editingPurchaseStatus, setEditingPurchaseStatus] = useState<"draft" | "received" | "cancelled">("received"); const remoteInventory = trpc.platform.inventory.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false }); const remotePurchases = trpc.platform.purchases.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false }); const createInventoryItem = trpc.platform.createInventoryItem.useMutation({ onSuccess: () => { void utils.platform.inventory.invalidate(); toast.success("تمت إضافة مادة المخزون"); }, onError: (error) => toast.error(`تعذر إضافة المادة: ${error.message}`) }); const updateInventoryItem = trpc.platform.updateInventoryItem.useMutation({ onSuccess: () => { void utils.platform.inventory.invalidate(); toast.success("تم تحديث الكمية"); }, onError: (error) => toast.error(`تعذر تحديث المخزون: ${error.message}`) }); const deleteInventoryItem = trpc.platform.deleteInventoryItem.useMutation({ onSuccess: () => { void utils.platform.inventory.invalidate(); toast.success("تم حذف مادة المخزون"); }, onError: (error) => toast.error(`تعذر حذف المادة: ${error.message}`) }); const createPurchase = trpc.platform.createPurchase.useMutation({ onSuccess: () => { void utils.platform.purchases.invalidate(); toast.success("تم تسجيل الشراء"); }, onError: (error) => toast.error(`تعذر تسجيل الشراء: ${error.message}`) }); const updatePurchase = trpc.platform.updatePurchase.useMutation({ onSuccess: () => { void utils.platform.purchases.invalidate(); toast.success("تم تحديث الشراء"); }, onError: (error) => toast.error(`تعذر تحديث الشراء: ${error.message}`) }); const deletePurchase = trpc.platform.deletePurchase.useMutation({ onSuccess: () => { void utils.platform.purchases.invalidate(); toast.success("تم حذف الشراء"); }, onError: (error) => toast.error(`تعذر حذف الشراء: ${error.message}`) }); const items = (remoteInventory.data ?? []).map((item) => ({ id: item.id, name: item.name, quantity: Number(item.quantity), unit: item.unit, minimum: Number(item.minimumQuantity) })); return <div><div className="mb-6 flex flex-wrap items-center justify-between gap-2"><SectionHeading title="المخزون والمشتريات" description="بيانات المخزون تُقرأ من قاعدة البيانات مع عزل المطعم." action="إضافة مادة" onAction={() => setInventoryFormOpen((value) => !value)} /><Button variant="outline" className="rounded-xl" onClick={() => setPurchaseFormOpen((value) => !value)}>تسجيل شراء</Button></div>{inventoryFormOpen && <Card className="mb-4 rounded-2xl border-orange-100 bg-orange-50/40"><CardContent className="grid gap-3 p-4 sm:grid-cols-[1fr_130px_150px_150px_auto]"><Input value={inventoryName} onChange={(event) => setInventoryName(event.target.value)} placeholder="اسم المادة" className="rounded-xl bg-white" /><Input value={inventoryUnit} onChange={(event) => setInventoryUnit(event.target.value)} placeholder="الوحدة" className="rounded-xl bg-white" /><Input value={inventoryQuantity} onChange={(event) => setInventoryQuantity(event.target.value)} inputMode="decimal" placeholder="الكمية الحالية" className="rounded-xl bg-white" /><Input value={inventoryMinimum} onChange={(event) => setInventoryMinimum(event.target.value)} inputMode="decimal" placeholder="الحد الأدنى" className="rounded-xl bg-white" /><Button disabled={createInventoryItem.isPending || inventoryName.trim().length < 1 || inventoryUnit.trim().length < 1 || !/^\d+(\.\d{1,2})?$/.test(inventoryQuantity) || !/^\d+(\.\d{1,2})?$/.test(inventoryMinimum)} onClick={() => createInventoryItem.mutate({ restaurantId, name: inventoryName.trim(), unit: inventoryUnit.trim(), quantity: inventoryQuantity, minimumQuantity: inventoryMinimum })} className="rounded-xl bg-[#e76f3c]">{createInventoryItem.isPending ? "جارٍ الحفظ..." : "حفظ المادة"}</Button></CardContent></Card>}{purchaseFormOpen && <Card className="mb-4 rounded-2xl border-slate-200 bg-slate-50"><CardContent className="grid gap-3 p-4 sm:grid-cols-[1fr_180px_auto]"><Input value={purchaseSupplier} onChange={(event) => setPurchaseSupplier(event.target.value)} placeholder="اسم المورد" className="rounded-xl bg-white" /><Input value={purchaseTotal} onChange={(event) => setPurchaseTotal(event.target.value)} inputMode="decimal" placeholder="إجمالي الشراء" className="rounded-xl bg-white" /><Button disabled={createPurchase.isPending || purchaseSupplier.trim().length < 1 || !/^\d+(\.\d{1,2})?$/.test(purchaseTotal)} onClick={() => createPurchase.mutate({ restaurantId, supplier: purchaseSupplier.trim(), total: purchaseTotal, status: "received" })} className="rounded-xl bg-[#111c2e]">{createPurchase.isPending ? "جارٍ الحفظ..." : "حفظ الشراء"}</Button></CardContent></Card>}{editingInventoryId !== null && <Card className="mb-4 rounded-2xl border-slate-200 bg-slate-50"><CardContent className="grid gap-3 p-4 sm:grid-cols-[1fr_130px_150px_auto]"><Input value={editingInventoryName} onChange={(event) => setEditingInventoryName(event.target.value)} placeholder="اسم المادة" className="rounded-xl bg-white" /><Input value={editingInventoryUnit} onChange={(event) => setEditingInventoryUnit(event.target.value)} placeholder="الوحدة" className="rounded-xl bg-white" /><Input value={editingInventoryMinimum} onChange={(event) => setEditingInventoryMinimum(event.target.value)} inputMode="decimal" placeholder="الحد الأدنى" className="rounded-xl bg-white" /><div className="flex gap-2"><Button disabled={updateInventoryItem.isPending || editingInventoryName.trim().length < 1 || editingInventoryUnit.trim().length < 1 || !/^\d+(\.\d{1,2})?$/.test(editingInventoryMinimum)} onClick={() => { updateInventoryItem.mutate({ restaurantId, id: editingInventoryId, name: editingInventoryName.trim(), unit: editingInventoryUnit.trim(), minimumQuantity: editingInventoryMinimum }); setEditingInventoryId(null); }} className="rounded-xl bg-[#111c2e]">حفظ التعديل</Button><Button variant="outline" onClick={() => setEditingInventoryId(null)} className="rounded-xl">إلغاء</Button></div></CardContent></Card>}{editingPurchaseId !== null && <Card className="mb-4 rounded-2xl border-slate-200 bg-slate-50"><CardContent className="grid gap-3 p-4 sm:grid-cols-[1fr_180px_150px_auto]"><Input value={editingPurchaseSupplier} onChange={(event) => setEditingPurchaseSupplier(event.target.value)} placeholder="اسم المورد" className="rounded-xl bg-white" /><Input value={editingPurchaseTotal} onChange={(event) => setEditingPurchaseTotal(event.target.value)} inputMode="decimal" placeholder="الإجمالي" className="rounded-xl bg-white" /><select value={editingPurchaseStatus} onChange={(event) => setEditingPurchaseStatus(event.target.value as typeof editingPurchaseStatus)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="draft">مسودة</option><option value="received">مستلم</option><option value="cancelled">ملغى</option></select><div className="flex gap-2"><Button disabled={updatePurchase.isPending || editingPurchaseSupplier.trim().length < 1 || !/^\d+(\.\d{1,2})?$/.test(editingPurchaseTotal)} onClick={() => { updatePurchase.mutate({ restaurantId, id: editingPurchaseId, supplier: editingPurchaseSupplier.trim(), total: editingPurchaseTotal, status: editingPurchaseStatus }); setEditingPurchaseId(null); }} className="rounded-xl bg-[#111c2e]">حفظ</Button><Button variant="outline" onClick={() => setEditingPurchaseId(null)} className="rounded-xl">إلغاء</Button></div></CardContent></Card>}<div className="mb-5 grid gap-4 sm:grid-cols-3"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><p className="text-xs text-slate-500">قيمة المخزون التقديرية</p><p className="mt-2 text-2xl font-bold">{remoteInventory.isLoading ? "..." : `${items.length} مادة`}</p></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><p className="text-xs text-slate-500">أصناف منخفضة</p><p className="mt-2 text-2xl font-bold text-amber-600">{items.filter((item) => item.quantity < item.minimum).length}</p></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><p className="text-xs text-slate-500">آخر عملية شراء</p><p className="mt-2 text-lg font-bold">{remotePurchases.isLoading ? "جارٍ التحميل" : remotePurchases.data?.length ? `آخر شراء #${remotePurchases.data[0].id}` : "لا توجد مشتريات"}</p></CardContent></Card></div><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-0">{remoteInventory.isError ? <div className="p-6 text-sm text-red-600">تعذر تحميل المخزون. Request ID: inventory-{restaurantId} <button onClick={() => void remoteInventory.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : remoteInventory.isLoading ? <div className="p-10 text-center text-sm text-slate-500">جارٍ تحميل المخزون...</div> : items.length === 0 ? <div className="p-10 text-center text-sm text-slate-400">لا توجد مواد مخزنة بعد.</div> : <table className="w-full text-right text-sm"><thead className="bg-slate-50 text-xs text-slate-500"><tr><th className="px-5 py-3">المادة</th><th className="px-5 py-3">الكمية الحالية</th><th className="px-5 py-3">الحد الأدنى</th><th className="px-5 py-3">الحالة</th><th className="px-5 py-3">إجراء</th></tr></thead><tbody>{items.map((item) => { const low = item.quantity < item.minimum; return <tr key={item.name} className="border-t border-slate-100"><td className="px-5 py-4 font-semibold">{item.name}</td><td className="px-5 py-4">{item.quantity} {item.unit}</td><td className="px-5 py-4 text-slate-500">{item.minimum} {item.unit}</td><td className="px-5 py-4"><Badge variant="outline" className={`rounded-lg text-[11px] ${low ? "border-amber-200 bg-amber-50 text-amber-700" : "border-emerald-200 bg-emerald-50 text-emerald-700"}`}>{low ? "يحتاج إعادة طلب" : "مستقر"}</Badge></td><td className="px-5 py-4"><div className="flex gap-2"><button onClick={() => { setEditingInventoryId(item.id); setEditingInventoryName(item.name); setEditingInventoryUnit(item.unit); setEditingInventoryMinimum(String(item.minimum)); }} className="text-xs font-semibold text-slate-600">تعديل</button><button onClick={() => updateInventoryItem.mutate({ restaurantId, id: item.id, quantity: (item.quantity + 10).toFixed(2) })} className="text-xs font-semibold text-[#e76f3c]">+ إضافة كمية</button><button onClick={() => deleteInventoryItem.mutate({ restaurantId, id: item.id })} className="text-xs font-semibold text-red-500">حذف</button></div></td></tr>; })}</tbody></table>}</CardContent></Card><Card className="mt-5 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader><CardTitle className="text-base">سجل المشتريات</CardTitle></CardHeader><CardContent className="p-0">{remotePurchases.isError ? <div className="p-6 text-sm text-red-600">تعذر تحميل المشتريات. Request ID: purchases-{restaurantId} <button onClick={() => void remotePurchases.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : remotePurchases.isLoading ? <div className="p-8 text-center text-sm text-slate-400">جارٍ تحميل المشتريات...</div> : (remotePurchases.data ?? []).length === 0 ? <div className="p-8 text-center text-sm text-slate-400">لا توجد مشتريات محفوظة بعد.</div> : <div className="overflow-x-auto"><table className="w-full text-right text-sm"><thead className="bg-slate-50 text-xs text-slate-500"><tr><th className="px-5 py-3">المورد</th><th className="px-5 py-3">الإجمالي</th><th className="px-5 py-3">الحالة</th><th className="px-5 py-3">إجراءات</th></tr></thead><tbody>{(remotePurchases.data ?? []).map((purchase) => <tr key={purchase.id} className="border-t border-slate-100"><td className="px-5 py-4 font-semibold">{purchase.supplier}</td><td className="px-5 py-4">{purchase.total} ر.س</td><td className="px-5 py-4">{purchase.status}</td><td className="px-5 py-4"><div className="flex gap-2"><button onClick={() => { setEditingPurchaseId(purchase.id); setEditingPurchaseSupplier(purchase.supplier); setEditingPurchaseTotal(String(purchase.total)); setEditingPurchaseStatus(purchase.status as typeof editingPurchaseStatus); }} className="text-xs font-semibold text-slate-600">تعديل</button><button onClick={() => { setEditingPurchaseId(purchase.id); setEditingPurchaseSupplier(purchase.supplier); setEditingPurchaseTotal(String(purchase.total)); setEditingPurchaseStatus(purchase.status as typeof editingPurchaseStatus); }} className="text-xs font-semibold text-[#e76f3c]">تحديث الحالة</button><button onClick={() => deletePurchase.mutate({ restaurantId, id: purchase.id })} className="text-xs font-semibold text-red-500">حذف</button></div></td></tr>)}</tbody></table></div>}</CardContent></Card></div>; }

function TeamView({ restaurantId }: { restaurantId: number }) { const { user } = useAuth(); const [pendingDeleteEmployeeId, setPendingDeleteEmployeeId] = useState<number | null>(null); const utils = trpc.useUtils(); const [employeeFormOpen, setEmployeeFormOpen] = useState(false); const [employeeName, setEmployeeName] = useState(""); const [employeeRole, setEmployeeRole] = useState<"waiter" | "kitchen" | "cashier" | "driver" | "manager" | "host">("waiter"); const [employeeBranchId, setEmployeeBranchId] = useState(""); const [editingEmployeeId, setEditingEmployeeId] = useState<number | null>(null); const remoteEmployees = trpc.platform.employees.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false }); const employeeLimit = trpc.platform.employeeLimit.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false }); const attendanceQuery = trpc.platform.attendanceByRestaurant.useQuery({ restaurantId, workDate: new Date().toISOString().slice(0, 10) }, { enabled: Boolean(user), retry: false }); const createEmployee = trpc.platform.createEmployee.useMutation({ onSuccess: () => { void utils.platform.employees.invalidate(); void employeeLimit.refetch(); toast.success("تمت إضافة الموظف"); }, onError: (error) => toast.error(`تعذر إضافة الموظف: ${error.message}`) }); const updateEmployee = trpc.platform.updateEmployee.useMutation({ onSuccess: () => { void utils.platform.employees.invalidate(); toast.success("تم تحديث الموظف"); }, onError: (error) => toast.error(`تعذر تحديث الموظف: ${error.message}`) }); const deleteEmployee = trpc.platform.deleteEmployee.useMutation({ onSuccess: () => { void utils.platform.employees.invalidate(); toast.success("تم حذف الموظف"); }, onError: (error) => toast.error(`تعذر حذف الموظف: ${error.message}`) }); const recordAttendance = trpc.platform.recordAttendance.useMutation({ onSuccess: () => toast.success("تم تسجيل حضور اليوم"), onError: (error) => toast.error(`تعذر تسجيل الحضور: ${error.message}`) }); const staff = remoteEmployees.data ?? []; const todayAttendance = attendanceQuery.data ?? []; return <div><SectionHeading title="الموظفون والحضور" description="بيانات الموظفين محفوظة في قاعدة البيانات مع عزل المطعم." action="إضافة موظف" onAction={() => { if (employeeLimit.data && !employeeLimit.data.canCreate) { toast.error(`تم بلوغ حد الموظفين في باقة ${employeeLimit.data.plan ?? "الحالية"}. قم بترقية الباقة لإضافة النادل أو السائق.`); return; } setEmployeeFormOpen((value) => !value); }} />{employeeFormOpen && <Card className="mb-4 rounded-2xl border-orange-100 bg-orange-50/40"><CardContent className="grid gap-3 p-4 sm:grid-cols-[1fr_180px_150px_auto]"><Input value={employeeName} onChange={(event) => setEmployeeName(event.target.value)} placeholder="اسم الموظف" className="rounded-xl bg-white" /><select value={employeeRole} onChange={(event) => setEmployeeRole(event.target.value as typeof employeeRole)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="waiter">نادل</option><option value="kitchen">مطبخ</option><option value="cashier">كاشير</option><option value="driver">سائق</option><option value="manager">مدير</option><option value="host">استقبال</option></select><Input value={employeeBranchId} onChange={(event) => setEmployeeBranchId(event.target.value)} inputMode="numeric" placeholder="رقم الفرع اختياري" className="rounded-xl bg-white" /><Button disabled={createEmployee.isPending || employeeName.trim().length < 2 || (employeeBranchId.trim() !== "" && (!Number.isInteger(Number(employeeBranchId)) || Number(employeeBranchId) < 1))} onClick={() => createEmployee.mutate({ restaurantId, branchId: employeeBranchId.trim() ? Number(employeeBranchId) : null, name: employeeName.trim(), role: employeeRole, status: "active" })} className="rounded-xl bg-[#e76f3c]">{createEmployee.isPending ? "جارٍ الحفظ..." : "حفظ الموظف"}</Button></CardContent></Card>}<Card className="mb-4 rounded-2xl border-orange-100 bg-orange-50/50 shadow-sm"><CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-bold text-slate-800">حصة الموظفين حسب الباقة</p><p className="mt-1 text-xs text-slate-500">تشمل النادل والسائق والكاشير والمطبخ وبقية فريق المطعم.</p></div>{employeeLimit.isLoading ? <span className="text-xs text-slate-500">جارٍ حساب الحد...</span> : employeeLimit.isError ? <span className="text-xs text-red-600">تعذر تحميل حد الموظفين. Request ID: employee-limit-{restaurantId}</span> : <div className="rounded-xl bg-white px-4 py-2 text-center"><span className="text-lg font-bold text-[#e76f3c]">{employeeLimit.data?.used ?? 0}</span><span className="mx-1 text-xs text-slate-400">/</span><span className="text-sm font-semibold text-slate-700">{employeeLimit.data?.limit === null ? "غير محدود" : employeeLimit.data?.limit ?? 0}</span><p className="text-[10px] text-slate-400">{employeeLimit.data?.plan ? `باقة ${employeeLimit.data.plan}` : "الحد الافتراضي"}</p></div>}</CardContent></Card><div className="mb-4 rounded-2xl border border-slate-200 bg-white p-4 text-sm"><span className="font-semibold">حضور اليوم: </span>{attendanceQuery.isLoading ? "جارٍ تحميل سجل الحضور..." : attendanceQuery.isError ? <span className="text-red-600">تعذر تحميل السجل. Request ID: attendance-{restaurantId} <button onClick={() => void attendanceQuery.refetch()} className="font-bold underline">إعادة المحاولة</button></span> : `${todayAttendance.filter((item) => item.status === "present").length} حاضر · ${todayAttendance.filter((item) => item.status === "late").length} متأخر · ${todayAttendance.filter((item) => item.status === "absent").length} غائب`}</div><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="grid gap-3 p-5 md:grid-cols-2">{remoteEmployees.isError ? <div className="p-6 text-sm text-red-600">تعذر تحميل الموظفين. Request ID: employees-{restaurantId} <button onClick={() => void remoteEmployees.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : remoteEmployees.isLoading ? <div className="col-span-full p-8 text-center text-sm text-slate-400">جارٍ تحميل الموظفين...</div> : staff.length === 0 ? <div className="p-8 text-center text-sm text-slate-400">لا يوجد موظفون محفوظون بعد.</div> : staff.map((member) => <div key={member.name} className="flex items-center gap-3 rounded-2xl border border-slate-100 p-4"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#111c2e] text-sm font-bold text-white">{member.name[0]}</div><div className="min-w-0 flex-1"><p className="text-sm font-bold">{member.name}</p><p className="mt-1 text-xs text-slate-500">{member.role}</p></div><button onClick={() => { setEditingEmployeeId(member.id); setEmployeeName(member.name); setEmployeeRole(member.role as typeof employeeRole); setEmployeeBranchId(member.branchId ? String(member.branchId) : ""); }} className="text-xs font-semibold text-[#e76f3c]">تعديل</button>{editingEmployeeId === member.id && <div className="absolute inset-x-4 bottom-14 z-10 grid gap-2 rounded-xl border border-orange-100 bg-white p-3 shadow-lg"><Input value={employeeName} onChange={(event) => setEmployeeName(event.target.value)} placeholder="اسم الموظف" className="h-9 rounded-lg text-xs" /><select value={employeeRole} onChange={(event) => setEmployeeRole(event.target.value as typeof employeeRole)} className="h-9 rounded-lg border border-slate-200 bg-white px-2 text-xs"><option value="waiter">نادل</option><option value="kitchen">مطبخ</option><option value="cashier">كاشير</option><option value="driver">سائق</option><option value="manager">مدير</option><option value="host">استقبال</option></select><Input value={employeeBranchId} onChange={(event) => setEmployeeBranchId(event.target.value)} placeholder="رقم الفرع" inputMode="numeric" className="h-9 rounded-lg text-xs" /><div className="flex gap-2"><Button size="sm" disabled={updateEmployee.isPending || employeeName.trim().length < 2 || (employeeBranchId.trim() !== "" && (!Number.isInteger(Number(employeeBranchId)) || Number(employeeBranchId) < 1))} onClick={() => { updateEmployee.mutate({ restaurantId, id: member.id, branchId: employeeBranchId.trim() ? Number(employeeBranchId) : undefined, name: employeeName.trim(), role: employeeRole }); setEditingEmployeeId(null); }} className="h-8 flex-1 rounded-lg text-xs">حفظ</Button><Button size="sm" variant="outline" onClick={() => setEditingEmployeeId(null)} className="h-8 rounded-lg text-xs">إلغاء</Button></div></div>}<button onClick={() => updateEmployee.mutate({ restaurantId, id: member.id, status: member.status === "active" ? "inactive" : "active" })} className={`rounded-lg px-3 py-1.5 text-[11px] font-bold ${member.status === "active" ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-500"}`}>{member.status === "active" ? "نشط" : "غير نشط"}</button><button onClick={() => recordAttendance.mutate({ restaurantId, employeeId: member.id, workDate: new Date().toISOString().slice(0, 10), status: "present" })} className="text-xs font-semibold text-emerald-600">حضور اليوم</button><button onClick={() => setPendingDeleteEmployeeId(member.id)} className="text-xs font-semibold text-red-500">حذف</button>{pendingDeleteEmployeeId === member.id && <span className="flex items-center gap-1 rounded-lg bg-red-50 px-2 py-1 text-[10px] text-red-700"><span>تأكيد؟</span><button onClick={() => { deleteEmployee.mutate({ restaurantId, id: member.id }); setPendingDeleteEmployeeId(null); }} className="font-bold underline">نعم</button><button onClick={() => setPendingDeleteEmployeeId(null)} className="font-bold underline">لا</button></span>}</div>)}</CardContent></Card></div>;
}

function MarketingView({ restaurantId }: { restaurantId: number }) { const { user } = useAuth(); const utils = trpc.useUtils(); const [campaignFormOpen, setCampaignFormOpen] = useState(false); const [couponFormOpen, setCouponFormOpen] = useState(false); const [campaignName, setCampaignName] = useState(""); const [campaignKind, setCampaignKind] = useState<"birthday" | "reengagement" | "general">("general"); const [reengagementDays, setReengagementDays] = useState("30"); const [couponCampaignId, setCouponCampaignId] = useState(""); const [couponCode, setCouponCode] = useState(""); const [couponDiscount, setCouponDiscount] = useState("10"); const [couponUsageLimit, setCouponUsageLimit] = useState(""); const [editingCouponId, setEditingCouponId] = useState<number | null>(null); const [campaignCron, setCampaignCron] = useState("0 0 9 * * *"); const remoteCampaigns = trpc.platform.campaigns.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false }); const audiencePreview = trpc.platform.campaignAudiencePreview.useQuery({ restaurantId, kind: campaignKind, reengagementDays: campaignKind === "reengagement" ? Number(reengagementDays) : undefined }, { enabled: Boolean(user && campaignFormOpen && (campaignKind !== "reengagement" || Number(reengagementDays) >= 1)), retry: false }); const remoteCoupons = trpc.platform.coupons.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false }); const createCampaign = trpc.platform.createCampaign.useMutation({ onSuccess: () => { void utils.platform.campaigns.invalidate(); toast.success("تم إنشاء الحملة"); }, onError: (error) => toast.error(`تعذر إنشاء الحملة: ${error.message}`) }); const scheduleCampaign = trpc.platform.scheduleCampaign.useMutation({ onSuccess: () => { void utils.platform.campaigns.invalidate(); toast.success("تم حفظ جدولة الحملة"); }, onError: (error) => toast.error(`تعذر جدولة الحملة: ${error.message}`) }); const updateCampaign = trpc.platform.updateCampaign.useMutation({ onSuccess: () => { void utils.platform.campaigns.invalidate(); toast.success("تم تحديث الحملة"); }, onError: (error) => toast.error(`تعذر تحديث الحملة: ${error.message}`) }); const deleteCampaign = trpc.platform.deleteCampaign.useMutation({ onSuccess: () => { void utils.platform.campaigns.invalidate(); toast.success("تم حذف الحملة"); }, onError: (error) => toast.error(`تعذر حذف الحملة: ${error.message}`) }); const createCoupon = trpc.platform.createCoupon.useMutation({ onSuccess: () => { void utils.platform.coupons.invalidate(); toast.success("تم إنشاء الكوبون"); }, onError: (error) => toast.error(`تعذر إنشاء الكوبون: ${error.message}`) }); const updateCoupon = trpc.platform.updateCoupon.useMutation({ onSuccess: () => { void utils.platform.coupons.invalidate(); toast.success("تم تحديث الكوبون"); }, onError: (error) => toast.error(`تعذر تحديث الكوبون: ${error.message}`) }); const deleteCoupon = trpc.platform.deleteCoupon.useMutation({ onSuccess: () => { void utils.platform.coupons.invalidate(); toast.success("تم حذف الكوبون"); }, onError: (error) => toast.error(`تعذر حذف الكوبون: ${error.message}`) }); const campaigns = remoteCampaigns.data ?? []; const coupons = remoteCoupons.data ?? []; return <div><SectionHeading title="التسويق والحملات" description="الحملات محفوظة في قاعدة البيانات مع عزل المطعم." action="حملة جديدة" onAction={() => setCampaignFormOpen((value) => !value)} />{campaignFormOpen && <Card className="mb-5 rounded-2xl border-violet-100 bg-violet-50/40"><CardContent className="grid gap-3 p-4 sm:grid-cols-[1fr_180px_150px_auto]"><Input value={campaignName} onChange={(event) => setCampaignName(event.target.value)} placeholder="اسم الحملة" className="rounded-xl bg-white" /><select value={campaignKind} onChange={(event) => setCampaignKind(event.target.value as typeof campaignKind)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="general">عامة</option><option value="birthday">أعياد الميلاد</option><option value="reengagement">إعادة تفاعل</option></select><Input value={reengagementDays} onChange={(event) => setReengagementDays(event.target.value)} disabled={campaignKind !== "reengagement"} inputMode="numeric" placeholder="أيام الخمول" className="rounded-xl bg-white" /><Button disabled={createCampaign.isPending || campaignName.trim().length < 2 || (campaignKind === "reengagement" && Number(reengagementDays) < 1)} onClick={() => createCampaign.mutate({ restaurantId, name: campaignName.trim(), kind: campaignKind, reengagementDays: campaignKind === "reengagement" ? Number(reengagementDays) : undefined, status: "draft" })} className="rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">{createCampaign.isPending ? "جارٍ الحفظ..." : "حفظ الحملة"}</Button><p className="sm:col-span-4 text-xs text-slate-500">{audiencePreview.isLoading ? "جارٍ حساب الجمهور..." : audiencePreview.isError ? "تعذر حساب الجمهور الآن." : `الجمهور المتوقع: ${audiencePreview.data?.count ?? 0} عميل · الإرسال متوقف حتى إعداد مزود الرسائل من لوحة الإعدادات.`}</p></CardContent></Card>}<div className="grid gap-4 md:grid-cols-3">{remoteCampaigns.isError ? <div className="p-6 text-sm text-red-600">تعذر تحميل الحملات. Request ID: campaigns-{restaurantId} <button onClick={() => void remoteCampaigns.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : remoteCampaigns.isLoading ? <div className="col-span-full p-8 text-center text-sm text-slate-400">جارٍ تحميل الحملات...</div> : campaigns.length === 0 ? <div className="p-8 text-center text-sm text-slate-400">لا توجد حملات محفوظة بعد.</div> : campaigns.map((campaign) => <Card key={campaign.id} className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-start justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-violet-50 text-violet-600"><Megaphone className="h-5 w-5" /></div><Badge variant="outline" className="rounded-lg border-emerald-200 bg-emerald-50 text-[10px] text-emerald-700">{campaign.status}</Badge></div><h3 className="mt-5 font-bold">{campaign.name}</h3><p className="mt-2 inline-block rounded-lg bg-slate-100 px-2 py-1 font-mono text-xs text-slate-600">#{campaign.id} · {campaign.kind === "birthday" ? "ميلاد" : campaign.kind === "reengagement" ? `استرجاع بعد ${campaign.reengagementDays ?? 30} يومًا` : "عامة"}</p><div className="mt-5 flex items-center justify-between border-t border-slate-100 pt-3 text-xs"><span className="text-slate-500">الحالة</span><div className="flex gap-2"><select value={campaign.status} onChange={(event) => updateCampaign.mutate({ restaurantId, id: campaign.id, status: event.target.value as "draft" | "scheduled" | "active" | "ended" })} className="rounded-lg border border-slate-200 bg-white px-2 py-1 text-xs font-semibold text-[#e76f3c]"><option value="draft">مسودة</option><option value="scheduled">مجدولة</option><option value="active">نشطة</option><option value="ended">منتهية</option></select><div className="flex items-center gap-1"><Input value={campaignCron} onChange={(event) => setCampaignCron(event.target.value)} aria-label="جدول Cron للحملة" className="h-8 w-36 rounded-lg text-[10px]" /><button onClick={() => scheduleCampaign.mutate({ restaurantId, id: campaign.id, cron: campaignCron.trim() })} disabled={scheduleCampaign.isPending || campaignCron.trim().split(/\s+/).length !== 6} className="font-semibold text-sky-600 disabled:opacity-50">جدولة</button></div><button onClick={() => deleteCampaign.mutate({ restaurantId, id: campaign.id })} className="font-semibold text-red-500">حذف</button></div></div></CardContent></Card>)}</div><Card className="mt-5 rounded-2xl border-slate-200 bg-white shadow-sm">{couponFormOpen && <CardContent className="grid gap-3 border-b border-slate-100 bg-orange-50/40 p-4 sm:grid-cols-[180px_1fr_150px_150px_auto]"><select value={couponCampaignId} onChange={(event) => setCouponCampaignId(event.target.value)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="">اختر الحملة</option>{campaigns.map((campaign) => <option key={campaign.id} value={campaign.id}>{campaign.name}</option>)}</select><Input value={couponCode} onChange={(event) => setCouponCode(event.target.value.toUpperCase())} placeholder="رمز الكوبون" className="rounded-xl bg-white" /><Input value={couponDiscount} onChange={(event) => setCouponDiscount(event.target.value)} inputMode="numeric" placeholder="الخصم %" className="rounded-xl bg-white" /><Input value={couponUsageLimit} onChange={(event) => setCouponUsageLimit(event.target.value)} inputMode="numeric" placeholder="حد الاستخدام" className="rounded-xl bg-white" /><Button disabled={createCoupon.isPending || !couponCampaignId || couponCode.trim().length < 2 || Number(couponDiscount) < 0 || Number(couponDiscount) > 100} onClick={() => editingCouponId !== null ? updateCoupon.mutate({ restaurantId, id: editingCouponId, code: couponCode.trim(), discountPercent: Number(couponDiscount), usageLimit: couponUsageLimit ? Number(couponUsageLimit) : null }) : createCoupon.mutate({ restaurantId, campaignId: Number(couponCampaignId), code: couponCode.trim(), discountPercent: Number(couponDiscount), usageLimit: couponUsageLimit ? Number(couponUsageLimit) : null })} className="rounded-xl bg-[#111c2e]">{createCoupon.isPending || updateCoupon.isPending ? "جارٍ الحفظ..." : editingCouponId !== null ? "حفظ تعديل الكوبون" : "حفظ الكوبون"}</Button></CardContent>}<CardHeader className="flex-row items-center justify-between"><div><CardTitle className="text-base">الكوبونات</CardTitle><p className="mt-1 text-xs text-slate-500">الكوبونات مرتبطة بحملات هذا المطعم وتُحفظ في قاعدة البيانات.</p></div><Button type="button" onClick={() => setCouponFormOpen((value) => !value)} className="rounded-xl bg-[#e76f3c] text-xs">كوبون جديد</Button></CardHeader><CardContent className="p-0">{remoteCoupons.isError ? <div className="p-6 text-sm text-red-600">تعذر تحميل الكوبونات. Request ID: coupons-{restaurantId} <button onClick={() => void remoteCoupons.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : remoteCoupons.isLoading ? <div className="p-8 text-center text-sm text-slate-400">جارٍ تحميل الكوبونات...</div> : coupons.length === 0 ? <div className="p-8 text-center text-sm text-slate-400">لا توجد كوبونات محفوظة بعد.</div> : <div className="divide-y divide-slate-100">{coupons.map((coupon) => <div key={coupon.id} className="flex flex-wrap items-center justify-between gap-3 px-5 py-3"><div><p className="font-mono text-sm font-bold">{coupon.code}</p><p className="text-xs text-slate-500">خصم {coupon.discountPercent}% · مستخدم {coupon.usedCount}{coupon.usageLimit ? ` من ${coupon.usageLimit}` : ""}</p></div><div className="flex gap-3"><button type="button" onClick={() => { setEditingCouponId(coupon.id); setCouponCampaignId(String(coupon.campaignId)); setCouponCode(coupon.code); setCouponDiscount(String(coupon.discountPercent)); setCouponUsageLimit(coupon.usageLimit ? String(coupon.usageLimit) : ""); setCouponFormOpen(true); }} className="text-xs font-semibold text-[#e76f3c]">تعديل</button><button type="button" onClick={() => deleteCoupon.mutate({ restaurantId, id: coupon.id })} className="text-xs font-semibold text-red-500">حذف</button></div></div>)}</div>}</CardContent></Card></div>; }

function SuperAdminView() { const { user } = useAuth(); const utils = trpc.useUtils(); const remoteRestaurants = trpc.admin.restaurants.useQuery(undefined, { enabled: Boolean(user), retry: 2 }); const remoteCustomers = trpc.admin.customers.useQuery(undefined, { enabled: Boolean(user), retry: 2 }); const roleCatalog = trpc.admin.roles.useQuery({}, { enabled: Boolean(user), retry: false }); const permissionCatalog = trpc.admin.permissions.useQuery(undefined, { enabled: Boolean(user), retry: false }); const saasMetrics = trpc.admin.saasMetrics.useQuery(undefined, { enabled: Boolean(user), retry: 2 }); const systemHealth = trpc.admin.systemHealth.useQuery(undefined, { enabled: Boolean(user), retry: 2, refetchInterval: 30000 }); const createRestaurant = trpc.admin.createRestaurant.useMutation({ onSuccess: () => { void utils.admin.restaurants.invalidate(); toast.success("تم إنشاء المطعم"); }, onError: (error) => toast.error(`تعذر إنشاء المطعم: ${error.message}`) }); const updateRestaurant = trpc.admin.updateRestaurant.useMutation({ onSuccess: () => { void utils.admin.restaurants.invalidate(); toast.success("تم تحديث المطعم"); }, onError: (error) => toast.error(`تعذر تحديث المطعم: ${error.message}`) }); const deleteRestaurant = trpc.admin.deleteRestaurant.useMutation({ onSuccess: () => { void utils.admin.restaurants.invalidate(); toast.success("تم تعليق المطعم"); }, onError: (error) => toast.error(`تعذر تعليق المطعم: ${error.message}`) }); const [statusFilter, setStatusFilter] = useState("الكل"); const [selectedAccount, setSelectedAccount] = useState<{ name: string; barcode: string } | null>(null); const [selectedFeatureRestaurantId, setSelectedFeatureRestaurantId] = useState<number | null>(null); const [createOpen, setCreateOpen] = useState(false); const [restaurantEditOpen, setRestaurantEditOpen] = useState(false); const [restaurantEditId, setRestaurantEditId] = useState<number | null>(null); const [restaurantEditName, setRestaurantEditName] = useState(""); const [restaurantEditPlan, setRestaurantEditPlan] = useState(""); const [pendingDeleteRestaurantId, setPendingDeleteRestaurantId] = useState<number | null>(null); const accountRows = (remoteRestaurants.data ?? []).map((item) => ({ id: item.id, name: item.name, barcode: item.barcode, branches: item.branchCount, plan: item.plan, status: item.status === "active" ? "نشط" : item.status === "trial" ? "تجربة" : "معلّق" })); const shown = accountRows.filter((item) => statusFilter === "الكل" || item.status === statusFilter); const liveCount = remoteRestaurants.data?.length ?? 0; return <div><div className="mb-6 flex items-center justify-between"><div><h2 className="text-xl font-bold">لوحة Super Admin</h2><p className="mt-1 text-sm text-slate-500">تحكم مركزي في المطاعم والعملاء والاشتراكات والصلاحيات مع حفظ السجل التشغيلي.</p></div><Button onClick={() => setCreateOpen(true)} className="gap-2 rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]"><Plus className="h-4 w-4" /> مطعم جديد</Button></div><CreateRestaurantDialog open={createOpen} pending={createRestaurant.isPending} onClose={() => setCreateOpen(false)} onSubmit={(input) => { createRestaurant.mutate(input); setCreateOpen(false); }} />{restaurantEditOpen && <div className="mb-5 grid gap-2 rounded-2xl border border-orange-100 bg-orange-50/50 p-4 sm:grid-cols-[1fr_1fr_auto_auto]"><Input value={restaurantEditName} onChange={(event) => setRestaurantEditName(event.target.value)} placeholder="اسم المطعم" className="rounded-xl bg-white" /><Input value={restaurantEditPlan} onChange={(event) => setRestaurantEditPlan(event.target.value)} placeholder="الباقة" className="rounded-xl bg-white" /><Button disabled={restaurantEditName.trim().length < 2 || !restaurantEditPlan.trim() || updateRestaurant.isPending} onClick={() => { if (restaurantEditId !== null) updateRestaurant.mutate({ id: restaurantEditId, name: restaurantEditName.trim(), plan: restaurantEditPlan.trim() }); setRestaurantEditOpen(false); setRestaurantEditId(null); }} className="rounded-xl bg-[#e76f3c]">{updateRestaurant.isPending ? "جارٍ الحفظ..." : "حفظ التعديل"}</Button><Button variant="outline" onClick={() => { setRestaurantEditOpen(false); setRestaurantEditId(null); }} className="rounded-xl">إلغاء</Button></div>}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{([["المطاعم النشطة", String(remoteRestaurants.data?.filter((item) => item.status === "active").length ?? 0), Store], ["MRR", saasMetrics.isError ? "تعذر" : saasMetrics.data ? `${saasMetrics.data.mrr.toFixed(2)} ر.س` : "...", CircleDollarSign], ["ARR", saasMetrics.isError ? "تعذر" : saasMetrics.data ? `${saasMetrics.data.arr.toFixed(2)} ر.س` : "...", WalletCards], ["Churn آخر 30 يومًا", saasMetrics.isError ? "تعذر" : saasMetrics.data ? `${saasMetrics.data.churnRate.toFixed(1)}%` : "...", TrendingDown]] as const).map(([label, value, Icon]) => { const StatIcon = Icon; return <Card key={label} className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-center justify-between"><p className="text-xs text-slate-500">{label}</p><div className="rounded-xl bg-orange-50 p-2 text-[#e76f3c]"><StatIcon className="h-4 w-4" /></div></div><p className="mt-4 text-2xl font-bold">{value}</p></CardContent></Card>; })}</div><Card className="mt-6 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-base">صحة SaaS</CardTitle><p className="mt-1 text-xs text-slate-500">توزيع الاشتراكات ومؤشرات الاستقرار التجاري من البيانات الفعلية.</p></div><Badge variant="outline" className="rounded-lg">{saasMetrics.isLoading ? "جارٍ التحميل" : saasMetrics.isError ? "تعذر التحميل" : "محدّثة"}</Badge></CardHeader><CardContent className="space-y-5 p-5">{saasMetrics.isError ? <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">تعذر تحميل صحة SaaS. Request ID: saas-health <button onClick={() => void saasMetrics.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : saasMetrics.isLoading ? <div className="h-24 animate-pulse rounded-xl bg-slate-100" /> : <><div className="grid gap-3 sm:grid-cols-4">{[["نشطة", saasMetrics.data?.activeSubscriptions ?? 0, "text-emerald-600"], ["تجريبية", saasMetrics.data?.trialSubscriptions ?? 0, "text-amber-600"], ["متأخرة", saasMetrics.data?.pastDueSubscriptions ?? 0, "text-red-600"], ["ملغاة آخر 30 يومًا", saasMetrics.data?.cancelledLast30Days ?? 0, "text-slate-600"]].map(([label, value, color]) => <div key={String(label)} className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">{label}</p><p className={`mt-1 text-xl font-bold ${color}`}>{value}</p></div>)}</div><div><p className="mb-2 text-xs font-semibold text-slate-500">التوزيع حسب الباقة</p>{Object.keys(saasMetrics.data?.byPlan ?? {}).length === 0 ? <p className="rounded-xl bg-slate-50 p-4 text-center text-xs text-slate-500">لا توجد باقات محفوظة بعد.</p> : <div className="grid gap-2 sm:grid-cols-3">{Object.entries(saasMetrics.data?.byPlan ?? {}).map(([plan, value]) => <div key={plan} className="flex items-center justify-between rounded-xl border border-slate-100 px-3 py-2 text-xs"><span className="font-semibold">{plan}</span><span className="text-slate-500">{value.active} نشطة · {value.mrr.toFixed(2)} ر.س</span></div>)}</div>}</div></>}</CardContent></Card><Card className="mt-6 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-base">المطاعم والعملاء</CardTitle><p className="mt-1 text-xs text-slate-500">آخر المطاعم المسجلة وحالة اشتراكها.</p></div><div className="flex gap-1 rounded-xl bg-slate-100 p-1">{["الكل", "نشط", "تجربة", "معلّق"].map((item) => <button key={item} onClick={() => setStatusFilter(item)} className={`rounded-lg px-3 py-1.5 text-[11px] font-semibold ${statusFilter === item ? "bg-white text-[#e76f3c] shadow-sm" : "text-slate-500"}`}>{item}</button>)}</div></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[620px] text-right text-sm"><thead className="bg-slate-50 text-[11px] text-slate-500"><tr><th className="px-5 py-3">المطعم</th><th className="px-5 py-3">الباركود</th><th className="px-5 py-3">الفروع</th><th className="px-5 py-3">الباقة</th><th className="px-5 py-3">الحالة</th><th className="px-5 py-3">إجراء</th></tr></thead><tbody>{remoteRestaurants.isError ? <tr><td colSpan={6} className="px-5 py-12 text-center text-sm text-red-600">تعذر تحميل المطاعم. <button onClick={() => void remoteRestaurants.refetch()} className="mr-1 font-bold underline">إعادة المحاولة</button></td></tr> : remoteRestaurants.isLoading ? <tr><td colSpan={6} className="px-5 py-12 text-center text-sm text-slate-500">جارٍ تحميل المطاعم...</td></tr> : shown.length === 0 ? <tr><td colSpan={6} className="px-5 py-12 text-center text-sm text-slate-500">لا توجد مطاعم محفوظة في قاعدة البيانات لهذا الفلتر.</td></tr> : shown.map((item) => <tr key={item.name} className="border-t border-slate-100"><td className="px-5 py-4 font-bold">{item.name}</td><td className="px-5 py-4"><div className="flex items-center gap-1"><button onClick={() => { navigator.clipboard?.writeText(item.barcode); toast.success(`تم نسخ ${item.barcode}`); }} className="flex items-center gap-2 rounded-lg bg-slate-50 px-2 py-1 text-left" title="نسخ الباركود"><Barcode value={item.barcode} width={0.8} height={24} displayValue={false} margin={0} /><span className="font-mono text-[10px] text-slate-500">{item.barcode}</span></button><button onClick={() => window.print()} className="rounded-lg px-2 py-1 text-[10px] font-semibold text-[#e76f3c] hover:bg-orange-50" title="طباعة الباركود">طباعة</button></div></td><td className="px-5 py-4 text-slate-500">{item.branches === null ? "غير متاح" : `${item.branches} فروع`}</td><td className="px-5 py-4"><Badge variant="outline" className="rounded-lg text-[11px]">{item.plan}</Badge></td><td className="px-5 py-4"><span className={`text-xs font-bold ${item.status === "نشط" ? "text-emerald-600" : item.status === "تجربة" ? "text-amber-600" : "text-slate-400"}`}>{item.status}</span></td><td className="px-5 py-4"><div className="flex gap-2"><button onClick={() => setSelectedAccount({ name: item.name, barcode: item.barcode })} className="text-xs font-semibold text-[#e76f3c]">عرض</button>{item.id > 0 && <><button onClick={() => { setRestaurantEditId(item.id); setRestaurantEditName(item.name); setRestaurantEditPlan(item.plan); setRestaurantEditOpen(true); }} className="text-xs font-semibold text-slate-600">تعديل</button><button onClick={() => setPendingDeleteRestaurantId(item.id)} className="text-xs font-semibold text-red-500">تعليق</button>{pendingDeleteRestaurantId === item.id && <span className="flex items-center gap-1 rounded-lg bg-red-50 px-2 py-1 text-[10px] text-red-700"><span>تأكيد؟</span><button onClick={() => { deleteRestaurant.mutate({ id: item.id }); setPendingDeleteRestaurantId(null); }} className="font-bold underline">نعم</button><button onClick={() => setPendingDeleteRestaurantId(null)} className="font-bold underline">لا</button></span>}</>}</div></td></tr>)}</tbody></table></div></CardContent></Card>{selectedAccount && <Card className="mt-5 rounded-2xl border-orange-200 bg-orange-50/40 shadow-sm"><CardContent className="flex flex-wrap items-center gap-5 p-5"><div><p className="text-xs text-slate-500">ملف الحساب</p><h3 className="mt-1 font-bold">{selectedAccount.name}</h3><p className="mt-1 font-mono text-xs text-slate-500">{selectedAccount.barcode}</p></div><div className="rounded-xl bg-white p-3"><Barcode value={selectedAccount.barcode} width={1.25} height={52} displayValue={false} margin={0} /></div><div className="mr-auto flex gap-2"><Button onClick={() => { navigator.clipboard?.writeText(selectedAccount.barcode); toast.success("تم نسخ باركود الحساب"); }} variant="outline" size="sm" className="rounded-lg text-xs">نسخ الباركود</Button><Button onClick={() => window.print()} size="sm" className="rounded-lg bg-[#e76f3c] text-xs hover:bg-[#d85f2e]">طباعة الباركود</Button></div></CardContent></Card>}<PlatformSettingsPanel /><ActivityAnalyticsPanel title="نشاط ومبيعات المنصة" /> {remoteRestaurants.data?.[0]?.id ? <><LoyaltyPanel restaurantId={selectedFeatureRestaurantId ?? remoteRestaurants.data[0].id} /><ReviewsPanel restaurantId={selectedFeatureRestaurantId ?? remoteRestaurants.data[0].id} /></> : null} <SubscriptionAdminPanel /> <CustomerAdminPanel /> <RoleAdminPanel /> <RolePermissionsPanel roles={roleCatalog.data ?? []} /> <FeatureUsagePanel /> {remoteRestaurants.data?.length ? <><Card className="mt-5 rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="flex flex-wrap items-center justify-between gap-3 p-5"><div><p className="font-bold">المطعم المستهدف للصلاحيات</p><p className="mt-1 text-xs text-slate-500">اختر مطعمًا فعليًا لإدارة Feature Override.</p></div><select value={selectedFeatureRestaurantId ?? remoteRestaurants.data[0].id} onChange={(event) => setSelectedFeatureRestaurantId(Number(event.target.value))} className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm"><option value={remoteRestaurants.data[0].id}>{remoteRestaurants.data[0].name}</option>{remoteRestaurants.data.slice(1).map((restaurant) => <option key={restaurant.id} value={restaurant.id}>{restaurant.name}</option>)}</select></CardContent></Card><FeatureAccessPanel restaurantId={selectedFeatureRestaurantId ?? remoteRestaurants.data[0].id} /></> : null}<div className="mt-5 grid gap-4 md:grid-cols-3"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-center gap-3"><ShieldCheck className="h-5 w-5 text-[#e76f3c]" /><div><p className="font-bold">الأدوار والصلاحيات</p><p className="mt-1 text-xs text-slate-500">{roleCatalog.isLoading || permissionCatalog.isLoading ? "جارٍ تحميل الكتالوج" : roleCatalog.isError || permissionCatalog.isError ? "تعذر تحميل الكتالوج" : `${roleCatalog.data?.length ?? 0} أدوار · ${permissionCatalog.data?.length ?? 0} صلاحية محفوظة`}</p></div><span className="mr-auto rounded-lg bg-slate-100 px-2.5 py-1.5 text-[10px] font-semibold text-slate-500">عرض الكتالوج</span></div></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-center gap-3"><CircleDollarSign className="h-5 w-5 text-emerald-600" /><div><p className="font-bold">الاشتراكات</p><p className="mt-1 text-xs text-slate-500">{liveCount} حسابًا في النظام{remoteRestaurants.isFetching ? " · جارٍ التحديث" : ""} · {remoteCustomers.isLoading ? "جارٍ حساب العملاء" : `${remoteCustomers.data?.length ?? 0} عميل محفوظ`}.</p></div><span className="mr-auto rounded-lg bg-slate-100 px-2.5 py-1.5 text-[10px] font-semibold text-slate-500">البيانات متاحة بالأعلى</span></div></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-center gap-3"><Activity className={`h-5 w-5 ${systemHealth.data?.status === "healthy" ? "text-emerald-600" : "text-amber-600"}`} /><div><p className="font-bold">صحة النظام</p><p className="mt-1 text-xs text-slate-500">{systemHealth.isLoading ? "جارٍ فحص الخدمات..." : systemHealth.isError ? "تعذر فحص الصحة" : systemHealth.data?.status === "healthy" ? `API وDB يعملان · ${new Date(systemHealth.data.checkedAt).toLocaleTimeString("ar-SA")}` : `الحالة متدهورة · قاعدة البيانات: ${systemHealth.data?.database ?? "غير متاحة"}`}</p></div><span className="mr-auto rounded-lg bg-slate-100 px-2.5 py-1.5 text-[10px] font-semibold text-slate-500">تحديث كل 30 ثانية</span></div></CardContent></Card></div></div>; }


function CustomerAdminPanel() { const { user } = useAuth(); const utils = trpc.useUtils(); const [customerFormOpen, setCustomerFormOpen] = useState(false); const [customerName, setCustomerName] = useState(""); const [customerEmail, setCustomerEmail] = useState(""); const [editingCustomerId, setEditingCustomerId] = useState<number | null>(null); const [pendingDeleteCustomerId, setPendingDeleteCustomerId] = useState<number | null>(null); const customers = trpc.admin.customers.useQuery(undefined, { enabled: Boolean(user), retry: 2 }); const createCustomer = trpc.admin.createCustomer.useMutation({ onSuccess: () => { void utils.admin.customers.invalidate(); toast.success("تم إنشاء العميل"); }, onError: (error) => toast.error(`تعذر إنشاء العميل: ${error.message}`) }); const updateCustomer = trpc.admin.updateCustomer.useMutation({ onSuccess: () => { void utils.admin.customers.invalidate(); toast.success("تم تحديث العميل"); }, onError: (error) => toast.error(`تعذر تحديث العميل: ${error.message}`) }); const deleteCustomer = trpc.admin.deleteCustomer.useMutation({ onSuccess: () => { void utils.admin.customers.invalidate(); toast.success("تم حذف العميل"); }, onError: (error) => toast.error(`تعذر حذف العميل: ${error.message}`) }); const rows = customers.data ?? []; return <Card className="mt-5 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-base">العملاء</CardTitle><p className="mt-1 text-xs text-slate-500">بيانات الحسابات العامة فقط؛ لا تظهر كلمات المرور أو رموز الجلسات.</p></div><Button onClick={() => { setEditingCustomerId(null); setCustomerName(""); setCustomerEmail(""); setCustomerFormOpen(true); }} className="rounded-xl bg-[#e76f3c] text-xs hover:bg-[#d85f2e]">عميل جديد</Button></CardHeader><CardContent className="p-0">{customerFormOpen && <div className="m-5 grid gap-2 rounded-2xl border border-orange-100 bg-orange-50/50 p-4 sm:grid-cols-[1fr_1fr_auto_auto]"><Input value={customerName} onChange={(event) => setCustomerName(event.target.value)} placeholder="اسم العميل" className="rounded-xl bg-white" /><Input value={customerEmail} onChange={(event) => setCustomerEmail(event.target.value)} placeholder="البريد الإلكتروني اختياري" className="rounded-xl bg-white" /><Button disabled={customerName.trim().length < 2 || (customerEmail.trim() && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(customerEmail.trim())) || createCustomer.isPending || updateCustomer.isPending} onClick={() => { const payload = { name: customerName.trim(), ...(customerEmail.trim() ? { email: customerEmail.trim() } : {}) }; if (editingCustomerId !== null) updateCustomer.mutate({ id: editingCustomerId, ...payload }); else createCustomer.mutate(payload); setCustomerFormOpen(false); setEditingCustomerId(null); setCustomerName(""); setCustomerEmail(""); }} className="rounded-xl bg-[#e76f3c]">{createCustomer.isPending || updateCustomer.isPending ? "جارٍ الحفظ..." : editingCustomerId !== null ? "حفظ التعديل" : "إنشاء العميل"}</Button><Button variant="outline" onClick={() => { setCustomerFormOpen(false); setEditingCustomerId(null); setCustomerName(""); setCustomerEmail(""); }} className="rounded-xl">إلغاء</Button></div>}{customers.isError ? <div className="p-6 text-sm text-red-600">تعذر تحميل العملاء. Request ID: customers-admin <button onClick={() => void customers.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : customers.isLoading ? <div className="m-5 h-20 animate-pulse rounded-xl bg-slate-100" /> : rows.length === 0 ? <div className="p-8 text-center text-sm text-slate-500">لا يوجد عملاء محفوظون بعد.</div> : <div className="overflow-x-auto"><table className="w-full min-w-[600px] text-right text-sm"><thead className="bg-slate-50 text-[11px] text-slate-500"><tr><th className="px-5 py-3">الاسم</th><th className="px-5 py-3">البريد</th><th className="px-5 py-3">طريقة الدخول</th><th className="px-5 py-3">آخر دخول</th><th className="px-5 py-3">إجراء</th></tr></thead><tbody>{rows.map((customer) => <tr key={customer.id} className="border-t border-slate-100"><td className="px-5 py-3 font-semibold">{customer.name || "بدون اسم"}</td><td className="px-5 py-3 text-slate-600">{customer.email || "غير متاح"}</td><td className="px-5 py-3 text-xs text-slate-500">{customer.loginMethod || "غير محددة"}</td><td className="px-5 py-3 text-xs text-slate-500">{customer.lastSignedIn ? new Date(customer.lastSignedIn).toLocaleString("ar-SA") : "لم يسجل الدخول"}</td><td className="px-5 py-3"><div className="flex gap-3"><button onClick={() => { setEditingCustomerId(customer.id); setCustomerName(customer.name ?? ""); setCustomerEmail(customer.email ?? ""); setCustomerFormOpen(true); }} className="text-xs font-semibold text-[#e76f3c]">تعديل</button><button onClick={() => setPendingDeleteCustomerId(customer.id)} className="text-xs font-semibold text-red-500">حذف</button>{pendingDeleteCustomerId === customer.id && <span className="flex items-center gap-1 rounded-lg bg-red-50 px-2 py-1 text-[10px] text-red-700"><span>تأكيد؟</span><button onClick={() => { deleteCustomer.mutate({ id: customer.id }); setPendingDeleteCustomerId(null); }} className="font-bold underline">نعم</button><button onClick={() => setPendingDeleteCustomerId(null)} className="font-bold underline">لا</button></span>}</div></td></tr>)}</tbody></table></div>}</CardContent></Card>; }

function SubscriptionAdminPanel() { const { user } = useAuth(); const utils = trpc.useUtils(); const [subscriptionFormOpen, setSubscriptionFormOpen] = useState(false); const [subscriptionRestaurantId, setSubscriptionRestaurantId] = useState(""); const [subscriptionPlan, setSubscriptionPlan] = useState("Growth"); const [subscriptionMonthlyPrice, setSubscriptionMonthlyPrice] = useState("0"); const [subscriptionStatus, setSubscriptionStatus] = useState<"trial" | "active" | "past_due" | "cancelled">("trial"); const [editingSubscriptionId, setEditingSubscriptionId] = useState<number | null>(null); const [pendingCancelSubscriptionId, setPendingCancelSubscriptionId] = useState<number | null>(null); const remoteSubscriptions = trpc.admin.subscriptions.useQuery({}, { enabled: Boolean(user), retry: false }); const createSubscription = trpc.admin.createSubscription.useMutation({ onSuccess: () => { void utils.admin.subscriptions.invalidate(); toast.success("تم إنشاء الاشتراك"); }, onError: (error) => toast.error(`تعذر إنشاء الاشتراك: ${error.message}`) }); const updateSubscription = trpc.admin.updateSubscription.useMutation({ onSuccess: () => { void utils.admin.subscriptions.invalidate(); toast.success("تم تحديث الاشتراك"); }, onError: (error) => toast.error(`تعذر تحديث الاشتراك: ${error.message}`) }); const cancelSubscription = trpc.admin.cancelSubscription.useMutation({ onSuccess: () => { void utils.admin.subscriptions.invalidate(); toast.success("تم إلغاء الاشتراك"); }, onError: (error) => toast.error(`تعذر إلغاء الاشتراك: ${error.message}`) }); const subscriptions = remoteSubscriptions.data ?? []; return <Card className="mt-5 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between"><div><CardTitle className="text-base">إدارة الاشتراكات</CardTitle><p className="mt-1 text-xs text-slate-500">حفظ فعلي للحزمة والحالة؛ الإلغاء يحافظ على السجل ولا يحذف الاشتراك.</p></div><Button onClick={() => { setEditingSubscriptionId(null); setSubscriptionRestaurantId(""); setSubscriptionPlan("Growth"); setSubscriptionMonthlyPrice("0"); setSubscriptionStatus("trial"); setSubscriptionFormOpen(true); }} className="rounded-xl bg-[#e76f3c] text-xs hover:bg-[#d85f2e]">اشتراك جديد</Button></CardHeader><CardContent className="p-0">{subscriptionFormOpen && <div className="m-5 grid gap-2 rounded-2xl border border-orange-100 bg-orange-50/50 p-4 md:grid-cols-2 xl:grid-cols-5"><Input type="number" min={1} value={subscriptionRestaurantId} onChange={(event) => setSubscriptionRestaurantId(event.target.value)} placeholder="رقم المطعم" className="rounded-xl bg-white" /><Input value={subscriptionPlan} onChange={(event) => setSubscriptionPlan(event.target.value)} placeholder="الباقة" className="rounded-xl bg-white" /><Input value={subscriptionMonthlyPrice} onChange={(event) => setSubscriptionMonthlyPrice(event.target.value)} placeholder="السعر الشهري" className="rounded-xl bg-white" /><select value={subscriptionStatus} onChange={(event) => setSubscriptionStatus(event.target.value as typeof subscriptionStatus)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="trial">تجريبية</option><option value="active">نشطة</option><option value="past_due">متأخرة</option><option value="cancelled">ملغاة</option></select><div className="flex gap-2"><Button disabled={Number(subscriptionRestaurantId) <= 0 || !subscriptionPlan.trim() || !/^\\d+(\\.\\d{1,2})?$/.test(subscriptionMonthlyPrice) || createSubscription.isPending || updateSubscription.isPending} onClick={() => { if (editingSubscriptionId !== null) updateSubscription.mutate({ id: editingSubscriptionId, plan: subscriptionPlan.trim(), monthlyPrice: subscriptionMonthlyPrice, status: subscriptionStatus }); else createSubscription.mutate({ restaurantId: Number(subscriptionRestaurantId), plan: subscriptionPlan.trim(), monthlyPrice: subscriptionMonthlyPrice, status: subscriptionStatus }); setSubscriptionFormOpen(false); setEditingSubscriptionId(null); }} className="rounded-xl bg-[#e76f3c]">{createSubscription.isPending || updateSubscription.isPending ? "جارٍ الحفظ..." : editingSubscriptionId !== null ? "حفظ التحديث" : "إنشاء الاشتراك"}</Button><Button variant="outline" onClick={() => { setSubscriptionFormOpen(false); setEditingSubscriptionId(null); }} className="rounded-xl">إلغاء</Button></div></div>}{remoteSubscriptions.isError ? <div className="p-6 text-sm text-red-600">تعذر تحميل الاشتراكات. Request ID: admin-subscriptions <button onClick={() => void remoteSubscriptions.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : remoteSubscriptions.isLoading ? <div className="p-8 text-center text-sm text-slate-500">جارٍ تحميل الاشتراكات...</div> : subscriptions.length === 0 ? <div className="p-8 text-center text-sm text-slate-400">لا توجد اشتراكات محفوظة.</div> : <div className="overflow-x-auto"><table className="w-full text-right text-sm"><thead className="bg-slate-50 text-xs text-slate-500"><tr><th className="px-5 py-3">المطعم</th><th className="px-5 py-3">الباقة</th><th className="px-5 py-3">السعر الشهري</th><th className="px-5 py-3">الحالة</th><th className="px-5 py-3">إجراء</th></tr></thead><tbody>{subscriptions.map((subscription) => <tr key={subscription.id} className="border-t border-slate-100"><td className="px-5 py-4">#{subscription.restaurantId}</td><td className="px-5 py-4 font-semibold">{subscription.plan}</td><td className="px-5 py-4">{subscription.monthlyPrice} ر.س</td><td className="px-5 py-4">{subscription.status}</td><td className="px-5 py-4"><div className="flex gap-2"><button onClick={() => { setEditingSubscriptionId(subscription.id); setSubscriptionRestaurantId(String(subscription.restaurantId)); setSubscriptionPlan(subscription.plan); setSubscriptionMonthlyPrice(String(subscription.monthlyPrice ?? "0")); setSubscriptionStatus(subscription.status as typeof subscriptionStatus); setSubscriptionFormOpen(true); }} className="text-xs font-semibold text-[#e76f3c]">تحديث</button>{subscription.status !== "cancelled" && <><button onClick={() => setPendingCancelSubscriptionId(subscription.id)} className="text-xs font-semibold text-red-500">إلغاء</button>{pendingCancelSubscriptionId === subscription.id && <span className="flex items-center gap-1 rounded-lg bg-red-50 px-2 py-1 text-[10px] text-red-700"><span>تأكيد؟</span><button onClick={() => { cancelSubscription.mutate({ id: subscription.id }); setPendingCancelSubscriptionId(null); }} className="font-bold underline">نعم</button><button onClick={() => setPendingCancelSubscriptionId(null)} className="font-bold underline">لا</button></span>}</>}</div></td></tr>)}</tbody></table></div>}</CardContent></Card>; }

function RoleAdminPanel() { const { user } = useAuth(); const utils = trpc.useUtils(); const [roleFormOpen, setRoleFormOpen] = useState(false); const [roleName, setRoleName] = useState(""); const [roleRestaurantId, setRoleRestaurantId] = useState(""); const [editingRoleId, setEditingRoleId] = useState<number | null>(null); const [pendingDeleteRoleId, setPendingDeleteRoleId] = useState<number | null>(null); const rolesQuery = trpc.admin.roles.useQuery({}, { enabled: Boolean(user), retry: false }); const createRole = trpc.admin.createRole.useMutation({ onSuccess: () => { void utils.admin.roles.invalidate(); toast.success("تم إنشاء الدور"); }, onError: (error) => toast.error(`تعذر إنشاء الدور: ${error.message}`) }); const updateRole = trpc.admin.updateRole.useMutation({ onSuccess: () => { void utils.admin.roles.invalidate(); toast.success("تم تحديث الدور"); }, onError: (error) => toast.error(`تعذر تحديث الدور: ${error.message}`) }); const deleteRole = trpc.admin.deleteRole.useMutation({ onSuccess: () => { void utils.admin.roles.invalidate(); toast.success("تم حذف الدور"); }, onError: (error) => toast.error(`تعذر حذف الدور: ${error.message}`) }); const roles = rolesQuery.data ?? []; return <Card className="mt-5 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between"><div><CardTitle className="text-base">إدارة الأدوار</CardTitle><p className="mt-1 text-xs text-slate-500">إنشاء وتعديل وحذف أدوار المنصة والمطاعم من قاعدة البيانات.</p></div><Button onClick={() => { setEditingRoleId(null); setRoleName(""); setRoleRestaurantId(""); setRoleFormOpen(true); }} className="rounded-xl bg-[#e76f3c] text-xs hover:bg-[#d85f2e]">دور جديد</Button></CardHeader><CardContent className="p-0">{roleFormOpen && <div className="m-5 grid gap-2 rounded-2xl border border-orange-100 bg-orange-50/50 p-4 sm:grid-cols-[1fr_220px_auto_auto]"><Input value={roleName} onChange={(event) => setRoleName(event.target.value)} placeholder="اسم الدور" className="rounded-xl bg-white" /><Input type="number" min={1} value={roleRestaurantId} onChange={(event) => setRoleRestaurantId(event.target.value)} placeholder="رقم المطعم، فارغ لدور المنصة" className="rounded-xl bg-white" /><Button disabled={roleName.trim().length < 2 || (roleRestaurantId.trim() && Number(roleRestaurantId) <= 0) || createRole.isPending || updateRole.isPending} onClick={() => { if (editingRoleId !== null) updateRole.mutate({ id: editingRoleId, name: roleName.trim() }); else createRole.mutate({ name: roleName.trim(), ...(roleRestaurantId.trim() ? { restaurantId: Number(roleRestaurantId) } : {}) }); setRoleFormOpen(false); setEditingRoleId(null); }} className="rounded-xl bg-[#e76f3c]">{createRole.isPending || updateRole.isPending ? "جارٍ الحفظ..." : editingRoleId !== null ? "حفظ التعديل" : "إنشاء الدور"}</Button><Button variant="outline" onClick={() => { setRoleFormOpen(false); setEditingRoleId(null); }} className="rounded-xl">إلغاء</Button></div>}{rolesQuery.isError ? <div className="p-6 text-sm text-red-600">تعذر تحميل الأدوار. Request ID: admin-roles <button onClick={() => void rolesQuery.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : rolesQuery.isLoading ? <div className="p-8 text-center text-sm text-slate-500">جارٍ تحميل الأدوار...</div> : roles.length === 0 ? <div className="p-8 text-center text-sm text-slate-500">لا توجد أدوار محفوظة بعد.</div> : <div className="overflow-x-auto"><table className="w-full text-right text-sm"><thead className="bg-slate-50 text-xs text-slate-500"><tr><th className="px-5 py-3">الدور</th><th className="px-5 py-3">النطاق</th><th className="px-5 py-3">المطعم</th><th className="px-5 py-3">إجراء</th></tr></thead><tbody>{roles.map((role) => <tr key={role.id} className="border-t border-slate-100"><td className="px-5 py-4 font-semibold">{role.name}</td><td className="px-5 py-4 text-xs text-slate-500">{role.scope}</td><td className="px-5 py-4 text-xs text-slate-500">{role.restaurantId ? `#${role.restaurantId}` : "المنصة"}</td><td className="px-5 py-4"><div className="flex gap-3"><button onClick={() => { setEditingRoleId(role.id); setRoleName(role.name); setRoleRestaurantId(role.restaurantId ? String(role.restaurantId) : ""); setRoleFormOpen(true); }} className="text-xs font-semibold text-slate-600">تعديل</button><button onClick={() => setPendingDeleteRoleId(role.id)} className="text-xs font-semibold text-red-500">حذف</button>{pendingDeleteRoleId === role.id && <span className="flex items-center gap-1 rounded-lg bg-red-50 px-2 py-1 text-[10px] text-red-700"><span>تأكيد؟</span><button onClick={() => { deleteRole.mutate({ id: role.id }); setPendingDeleteRoleId(null); }} className="font-bold underline">نعم</button><button onClick={() => setPendingDeleteRoleId(null)} className="font-bold underline">لا</button></span>}</div></td></tr>)}</tbody></table></div>}</CardContent></Card>; }

function RolePermissionsPanel({ roles }: { roles: Array<{ id: number; name: string }> }) { const [selectedRoleId, setSelectedRoleId] = useState<number | undefined>(roles[0]?.id); const permissionsQuery = trpc.admin.permissions.useQuery(undefined, { retry: false }); const rolePermissionsQuery = trpc.admin.rolePermissions.useQuery({ roleId: selectedRoleId ?? 0 }, { enabled: Boolean(selectedRoleId), retry: false }); const [selectedPermissionIds, setSelectedPermissionIds] = useState<number[]>([]); useEffect(() => { setSelectedRoleId((current) => current && roles.some((role) => role.id === current) ? current : roles[0]?.id); }, [roles]); useEffect(() => { setSelectedPermissionIds((rolePermissionsQuery.data ?? []).map((permission) => permission.permissionId)); }, [rolePermissionsQuery.data]); const setRolePermissions = trpc.admin.setRolePermissions.useMutation({ onSuccess: () => { void rolePermissionsQuery.refetch(); toast.success("تم حفظ صلاحيات الدور"); }, onError: (error) => toast.error(`تعذر حفظ صلاحيات الدور: ${error.message}`) }); return <Card className="mt-5 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader><CardTitle className="text-base">صلاحيات الأدوار</CardTitle><p className="mt-1 text-xs text-slate-500">اختر دورًا ثم حدّد الصلاحيات المسموح بها واحفظها في rolePermissions.</p></CardHeader><CardContent>{roles.length === 0 ? <p className="rounded-xl bg-slate-50 p-6 text-center text-sm text-slate-500">أنشئ دورًا أولًا لإدارة صلاحياته.</p> : <><select value={selectedRoleId ?? ""} onChange={(event) => setSelectedRoleId(Number(event.target.value))} className="mb-4 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm">{roles.map((role) => <option key={role.id} value={role.id}>{role.name}</option>)}</select>{permissionsQuery.isError || rolePermissionsQuery.isError ? <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">تعذر تحميل صلاحيات الدور. Request ID: role-permissions <button onClick={() => { void permissionsQuery.refetch(); void rolePermissionsQuery.refetch(); }} className="font-bold underline">إعادة المحاولة</button></div> : permissionsQuery.isLoading || rolePermissionsQuery.isLoading ? <div className="h-28 animate-pulse rounded-xl bg-slate-100" /> : <><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{(permissionsQuery.data ?? []).map((permission) => <label key={permission.id} className="flex cursor-pointer items-center gap-2 rounded-xl border border-slate-100 p-3 text-xs hover:bg-slate-50"><input type="checkbox" checked={selectedPermissionIds.includes(permission.id)} onChange={(event) => setSelectedPermissionIds((current) => event.target.checked ? Array.from(new Set([...current, permission.id])) : current.filter((id) => id !== permission.id))} /><span><span className="block font-semibold">{permission.label}</span><span className="font-mono text-[10px] text-slate-400">{permission.key}</span></span></label>)}</div><Button disabled={!selectedRoleId || setRolePermissions.isPending} onClick={() => selectedRoleId && setRolePermissions.mutate({ roleId: selectedRoleId, permissionIds: selectedPermissionIds })} className="mt-4 rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">{setRolePermissions.isPending ? "جارٍ الحفظ..." : "حفظ الصلاحيات"}</Button></>}</>}</CardContent></Card>; }

function FeatureUsagePanel() { const query = trpc.admin.featureUsageMetrics.useQuery(undefined, { retry: false }); const rows = query.data ?? []; return <Card className="mt-5 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="border-b border-slate-100"><CardTitle className="text-base">استخدام الميزات عبر المطاعم</CardTitle><p className="mt-1 text-xs text-slate-500">مؤشرات حقيقية من إعدادات الميزات المحفوظة، وليست بيانات تجريبية.</p></CardHeader><CardContent className="p-0">{query.isLoading ? <div className="p-8 text-center text-sm text-slate-500">جارٍ تحميل التحليلات...</div> : query.isError ? <div className="p-6 text-sm text-red-600">تعذر تحميل تحليلات الميزات. Request ID: feature-usage <button onClick={() => void query.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : rows.length === 0 ? <div className="p-8 text-center text-sm text-slate-500">لا توجد بيانات استخدام ميزات بعد.</div> : <div className="overflow-x-auto"><table className="w-full text-right text-sm"><thead className="bg-slate-50 text-xs text-slate-500"><tr><th className="px-5 py-3">الميزة</th><th className="px-5 py-3">المطاعم المهيّأة</th><th className="px-5 py-3">المطاعم المفعّلة</th></tr></thead><tbody>{rows.map((row) => <tr key={row.featureId} className="border-t border-slate-100"><td className="px-5 py-4"><p className="font-semibold">{row.label}</p><p className="mt-1 font-mono text-[10px] text-slate-400">{row.key}</p></td><td className="px-5 py-4">{row.configuredRestaurants}</td><td className="px-5 py-4 font-bold text-emerald-600">{row.enabledRestaurants}</td></tr>)}</tbody></table></div>}</CardContent></Card>; }

function FeatureAccessPanel({ restaurantId }: { restaurantId: number }) {
  const [forbiddenAction, setForbiddenAction] = useState<string | null>(null);
  const definitions = trpc.features.definitions.useQuery(undefined, { retry: false });
  const [selectedKey, setSelectedKey] = useState("offline_pos");
  const selected = definitions.data?.find((feature) => feature.key === selectedKey) ?? definitions.data?.[0];
  const access = trpc.features.access.useQuery({ restaurantId, key: selected?.key ?? selectedKey }, { retry: false, enabled: Boolean(selected?.key ?? selectedKey) });
  const setOverride = trpc.features.setOverride.useMutation({ onSuccess: () => { toast.success("تم حفظ إعداد الميزة للمطعم"); access.refetch(); }, onError: (error) => { if (error.data?.code === "FORBIDDEN") setForbiddenAction("feature.override.update"); else toast.error(error.message); } });
  if (forbiddenAction) return <AccessDeniedView feature={forbiddenAction} />;
  return <Card className="mt-5 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between border-b border-slate-100"><div><CardTitle className="text-base">الميزات الديناميكية</CardTitle><p className="mt-1 text-xs text-slate-500">تحكم في التفعيل والحدود والتبعيات دون تغيير الباقة.</p></div><Badge className={access.data?.enabled ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-600"}>{access.isLoading ? "جارٍ الفحص" : access.data?.enabled ? "مفعّلة" : "غير مفعّلة"}</Badge></CardHeader><CardContent className="space-y-4 p-5">{(definitions.data ?? []).length === 0 ? <p className="rounded-xl bg-slate-50 p-6 text-center text-sm text-slate-500">لا توجد تعريفات ميزات بعد.</p> : <><select value={selected?.key ?? selectedKey} onChange={(event) => setSelectedKey(event.target.value)} className="h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm outline-none">{(definitions.data ?? []).map((feature) => <option key={feature.key} value={feature.key}>{feature.label} · {feature.key}{feature.isAddOn ? ` · Add-on${feature.addonPrice ? ` ${feature.addonPrice} ر.س` : ""}` : ""}</option>)}</select><div className="grid gap-3 sm:grid-cols-4"><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">الحالة</p><p className="mt-1 text-sm font-bold">{access.data?.reason ?? "—"}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">الحد الحالي</p><p className="mt-1 text-sm font-bold">{access.data?.limit ?? "غير محدود"}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">المعرف</p><p className="mt-1 truncate text-sm font-bold">{selected?.key}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">النوع</p><p className="mt-1 text-sm font-bold">{selected?.isAddOn ? `Add-on${selected.addonPrice ? ` · ${selected.addonPrice} ر.س` : ""}` : "ضمن الباقة"}</p></div></div><div className="flex gap-2"><Button disabled={!selected || setOverride.isPending} onClick={() => selected && setOverride.mutate({ restaurantId, featureId: selected.id, enabled: !access.data?.enabled, limit: access.data?.limit ?? null })} className="rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">{access.data?.enabled ? "تعطيل Override" : "تفعيل Override"}</Button><Button variant="outline" onClick={() => access.refetch()} className="rounded-xl">تحديث</Button></div></>}</CardContent></Card>;
}

function BrandingPanel({ restaurantId }: { restaurantId: number }) { const { user } = useAuth(); const utils = trpc.useUtils(); const brandingQuery = trpc.platform.branding.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false }); const customDomainAccess = trpc.features.access.useQuery({ restaurantId, key: "custom_domain" }, { enabled: Boolean(user), retry: false }); const publicOrigin = customDomainAccess.data?.enabled && brandingQuery.data?.customDomain ? `https://${brandingQuery.data.customDomain}` : window.location.origin; const [draft, setDraft] = useState({ brandName: "", brandColor: "#e76f3c", brandLogoUrl: "", brandDescription: "", homepageContent: "", termsOfService: "", privacyPolicy: "", refundPolicy: "", phone: "", whatsapp: "", instagramUrl: "", facebookUrl: "", tiktokUrl: "", websiteUrl: "", address: "", reservationEnabled: true, customDomain: "" }); useEffect(() => { if (brandingQuery.data) setDraft({ brandName: brandingQuery.data.brandName, brandColor: brandingQuery.data.brandColor, brandLogoUrl: brandingQuery.data.brandLogoUrl, brandDescription: brandingQuery.data.brandDescription, homepageContent: brandingQuery.data.homepageContent, termsOfService: brandingQuery.data.termsOfService, privacyPolicy: brandingQuery.data.privacyPolicy, refundPolicy: brandingQuery.data.refundPolicy, phone: brandingQuery.data.phone, whatsapp: brandingQuery.data.whatsapp, instagramUrl: brandingQuery.data.instagramUrl, facebookUrl: brandingQuery.data.facebookUrl, tiktokUrl: brandingQuery.data.tiktokUrl, websiteUrl: brandingQuery.data.websiteUrl, address: brandingQuery.data.address, reservationEnabled: brandingQuery.data.reservationEnabled, customDomain: brandingQuery.data.customDomain }); }, [brandingQuery.data]); const updateBranding = trpc.platform.updateBranding.useMutation({ onSuccess: () => { void utils.platform.branding.invalidate(); toast.success("تم حفظ هوية المطعم"); }, onError: (error) => toast.error(`تعذر حفظ الهوية: ${error.message}`) }); const updateCustomDomain = trpc.platform.updateCustomDomain.useMutation({ onSuccess: () => { void utils.platform.branding.invalidate(); void customDomainAccess.refetch(); toast.success("تم حفظ نطاق المطعم"); }, onError: (error) => toast.error(`تعذر حفظ النطاق: ${error.message}`) }); return <Card className="mb-6 overflow-hidden rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader><CardTitle className="text-base">هوية المطعم وWhite Label</CardTitle><p className="text-xs text-slate-500">خصّص الاسم واللون والوصف الذي يظهران لعملاء هذا المطعم.</p></CardHeader><CardContent>{brandingQuery.isError ? <div className="p-4 text-sm text-red-600">تعذر تحميل الهوية. Request ID: branding-{restaurantId} <button onClick={() => void brandingQuery.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : brandingQuery.isLoading ? <div className="p-8 text-center text-sm text-slate-500">جارٍ تحميل هوية المطعم...</div> : <div className="grid gap-5 lg:grid-cols-[1fr_280px]"><div className="grid gap-4 sm:grid-cols-2"><label className="space-y-2 text-sm font-semibold">اسم العرض<Input value={draft.brandName} onChange={(event) => setDraft({ ...draft, brandName: event.target.value })} className="mt-1 rounded-xl" placeholder="اسم المطعم للعملاء" /></label><label className="space-y-2 text-sm font-semibold">اللون الأساسي<div className="mt-1 flex gap-2"><Input value={draft.brandColor} onChange={(event) => setDraft({ ...draft, brandColor: event.target.value })} className="rounded-xl font-mono" placeholder="#e76f3c" /><input type="color" value={/^#[0-9A-Fa-f]{6}$/.test(draft.brandColor) ? draft.brandColor : "#e76f3c"} onChange={(event) => setDraft({ ...draft, brandColor: event.target.value })} className="h-10 w-12 cursor-pointer rounded-lg border border-slate-200 bg-white p-1" aria-label="اختيار لون الهوية" /></div></label><label className="space-y-2 text-sm font-semibold sm:col-span-2">رابط الشعار<Input value={draft.brandLogoUrl} onChange={(event) => setDraft({ ...draft, brandLogoUrl: event.target.value })} className="mt-1 rounded-xl" placeholder="https://..." dir="ltr" /></label><label className="space-y-2 text-sm font-semibold">الهاتف<Input value={draft.phone} onChange={(event) => setDraft({ ...draft, phone: event.target.value })} className="mt-1 rounded-xl" dir="ltr" placeholder="05xxxxxxxx" /></label><label className="space-y-2 text-sm font-semibold">واتساب<Input value={draft.whatsapp} onChange={(event) => setDraft({ ...draft, whatsapp: event.target.value })} className="mt-1 rounded-xl" dir="ltr" placeholder="9665xxxxxxxx" /></label><label className="space-y-2 text-sm font-semibold">Instagram<Input value={draft.instagramUrl} onChange={(event) => setDraft({ ...draft, instagramUrl: event.target.value })} className="mt-1 rounded-xl" dir="ltr" placeholder="https://instagram.com/..." /></label><label className="space-y-2 text-sm font-semibold">Facebook<Input value={draft.facebookUrl} onChange={(event) => setDraft({ ...draft, facebookUrl: event.target.value })} className="mt-1 rounded-xl" dir="ltr" placeholder="https://facebook.com/..." /></label><label className="space-y-2 text-sm font-semibold">TikTok<Input value={draft.tiktokUrl} onChange={(event) => setDraft({ ...draft, tiktokUrl: event.target.value })} className="mt-1 rounded-xl" dir="ltr" placeholder="https://tiktok.com/@..." /></label><label className="space-y-2 text-sm font-semibold">الموقع الإلكتروني<Input value={draft.websiteUrl} onChange={(event) => setDraft({ ...draft, websiteUrl: event.target.value })} className="mt-1 rounded-xl" dir="ltr" placeholder="https://..." /></label><label className="space-y-2 text-sm font-semibold sm:col-span-2">العنوان<Input value={draft.address} onChange={(event) => setDraft({ ...draft, address: event.target.value })} className="mt-1 rounded-xl" /></label><label className="flex items-center gap-3 text-sm font-semibold sm:col-span-2"><input type="checkbox" checked={draft.reservationEnabled} onChange={(event) => setDraft({ ...draft, reservationEnabled: event.target.checked })} className="h-4 w-4 accent-orange-500" /> استقبال الحجوزات العامة</label><label className="space-y-2 text-sm font-semibold sm:col-span-2">نطاق المطعم المستقل{customDomainAccess.data?.enabled ? <span className="mr-2 text-xs font-normal text-emerald-600">متاح ضمن الباقة</span> : <span className="mr-2 text-xs font-normal text-amber-600">غير مفعّل ضمن الباقة</span>}<div className="mt-1 flex gap-2"><Input value={draft.customDomain} onChange={(event) => setDraft({ ...draft, customDomain: event.target.value.toLowerCase().replace(/^https?:\/\//, "").replace(/\/+$/, "") })} className="rounded-xl font-mono" dir="ltr" placeholder="restaurant.example.com" disabled={!customDomainAccess.data?.enabled} /><Button type="button" variant="outline" className="rounded-xl" disabled={!customDomainAccess.data?.enabled || updateCustomDomain.isPending || !/^[a-z0-9.-]+$/i.test(draft.customDomain)} onClick={() => updateCustomDomain.mutate({ restaurantId, customDomain: draft.customDomain })}>حفظ النطاق</Button></div><p className="mt-1 text-xs font-normal text-slate-500">هذا النطاق منفصل عن نطاق NFOOD ويحتاج توجيه DNS عند مزود النطاق.</p></label><label className="space-y-2 text-sm font-semibold sm:col-span-2">وصف قصير<textarea value={draft.brandDescription} onChange={(event) => setDraft({ ...draft, brandDescription: event.target.value })} className="mt-1 min-h-24 w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm outline-none ring-offset-2 focus:ring-2 focus:ring-orange-200" placeholder="وصف يظهر في صفحة المطعم" /></label><label className="space-y-2 text-sm font-semibold sm:col-span-2">محتوى الصفحة الأولى<textarea value={draft.homepageContent} onChange={(event) => setDraft({ ...draft, homepageContent: event.target.value })} className="mt-1 min-h-28 w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm outline-none" placeholder="العنوان والمزايا والعروض الخاصة بالمطعم" /></label><label className="space-y-2 text-sm font-semibold sm:col-span-2">الشروط والأحكام<textarea value={draft.termsOfService} onChange={(event) => setDraft({ ...draft, termsOfService: event.target.value })} className="mt-1 min-h-28 w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm outline-none" /></label><label className="space-y-2 text-sm font-semibold sm:col-span-2">سياسة الخصوصية<textarea value={draft.privacyPolicy} onChange={(event) => setDraft({ ...draft, privacyPolicy: event.target.value })} className="mt-1 min-h-28 w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm outline-none" /></label><label className="space-y-2 text-sm font-semibold sm:col-span-2">سياسة الاسترجاع<textarea value={draft.refundPolicy} onChange={(event) => setDraft({ ...draft, refundPolicy: event.target.value })} className="mt-1 min-h-24 w-full rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm outline-none" /></label><Button disabled={updateBranding.isPending || brandingQuery.isLoading || !/^#[0-9A-Fa-f]{6}$/.test(draft.brandColor) || draft.brandName.trim().length < 2} onClick={() => updateBranding.mutate({ restaurantId, ...draft })} className="w-fit rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">{updateBranding.isPending ? "جارٍ الحفظ..." : "حفظ الهوية"}</Button></div><div className="rounded-2xl p-5 text-white shadow-inner" style={{ backgroundColor: /^#[0-9A-Fa-f]{6}$/.test(draft.brandColor) ? draft.brandColor : "#e76f3c" }}><div className="flex items-center justify-between gap-2"><div><p className="text-xs opacity-80">الرابط العام المخصص للمطعم</p>{brandingQuery.data?.slug && <p className="mt-1 max-w-[220px] truncate font-mono text-[10px] text-white/75" dir="ltr">{publicOrigin}/restaurant/{brandingQuery.data.slug}</p>}</div>{brandingQuery.data?.slug && <div className="flex gap-2"><button type="button" onClick={() => { window.location.assign(publicMenuUrl(publicOrigin, brandingQuery.data.slug)); }} className="rounded-lg bg-white/15 px-2 py-1 text-[10px] font-semibold text-white hover:bg-white/25">فتح المنيو</button><button type="button" onClick={() => { void navigator.clipboard?.writeText(publicMenuUrl(publicOrigin, brandingQuery.data.slug)); toast.success("تم نسخ رابط المطعم"); }} className="rounded-lg bg-white/15 px-2 py-1 text-[10px] font-semibold text-white hover:bg-white/25">نسخ</button></div>}</div>{draft.brandLogoUrl ? <img src={draft.brandLogoUrl} alt="شعار المطعم" className="mt-5 h-14 w-14 rounded-2xl bg-white/90 object-contain p-2" /> : <div className="mt-5 flex h-14 w-14 items-center justify-center rounded-2xl bg-white/20 text-xl font-bold">{draft.brandName.slice(0, 1) || "N"}</div>}<h3 className="mt-5 text-lg font-bold">{draft.brandName || "اسم المطعم"}</h3><p className="mt-2 text-xs leading-5 text-white/80">{draft.brandDescription || "وصف المطعم سيظهر هنا بعد الحفظ."}</p></div></div>}</CardContent></Card>; }

function RestaurantProfilePanel({ restaurantId }: { restaurantId: number }) { const { user } = useAuth(); const restaurantQuery = trpc.platform.restaurantById.useQuery({ id: restaurantId }, { enabled: Boolean(user), retry: false }); return <Card className="mb-6 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader><CardTitle className="text-base">بيانات المطعم</CardTitle><p className="mt-1 text-xs text-slate-500">بيانات الحساب الأساسية والباركود محفوظة من قاعدة البيانات.</p></CardHeader><CardContent>{restaurantQuery.isError ? <div className="p-4 text-sm text-red-600">تعذر تحميل بيانات المطعم. Request ID: restaurant-profile-{restaurantId} <button onClick={() => void restaurantQuery.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : restaurantQuery.isLoading ? <div className="h-24 animate-pulse rounded-xl bg-slate-100" /> : !restaurantQuery.data ? <div className="p-4 text-sm text-slate-500">لا توجد بيانات مطعم مرتبطة بمساحة العمل.</div> : <div className="grid gap-4 sm:grid-cols-[1fr_auto] sm:items-center"><div className="grid gap-3 sm:grid-cols-3"><div><p className="text-[11px] text-slate-500">الاسم</p><p className="mt-1 font-bold">{restaurantQuery.data.name}</p></div><div><p className="text-[11px] text-slate-500">المعرّف العام</p><p className="mt-1 font-mono text-sm" dir="ltr">/{restaurantQuery.data.slug}</p></div><div><p className="text-[11px] text-slate-500">الحالة</p><p className="mt-1 font-semibold">{restaurantQuery.data.status === "active" ? "نشط" : restaurantQuery.data.status === "trial" ? "تجريبي" : "معلّق"}</p></div></div><div className="flex items-center gap-3 rounded-xl bg-slate-50 p-3"><Barcode value={restaurantQuery.data.barcode} width={1} height={38} displayValue={false} margin={0} /><div><p className="text-[10px] text-slate-500">باركود الحساب</p><p className="font-mono text-xs" dir="ltr">{restaurantQuery.data.barcode}</p></div></div><div className="mt-4 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-orange-100 bg-orange-50/70 p-3"><div><p className="text-sm font-bold text-slate-900">الصفحة العامة للمطعم</p><p className="mt-1 text-xs text-slate-500">اعرض المنيو والحجز والتواصل للعملاء مباشرة.</p></div><Button type="button" onClick={() => window.location.assign(publicMenuUrl(window.location.origin, restaurantQuery.data.slug))} className="rounded-xl bg-[#e76f3c] text-white hover:bg-[#d85f2e]">فتح صفحة المطعم</Button></div></div>}</CardContent></Card>; }

function BranchesView({ restaurantId }: { restaurantId: number }) { const { user } = useAuth(); const [pendingDeleteBranchId, setPendingDeleteBranchId] = useState<number | null>(null); const utils = trpc.useUtils(); const [branchFormOpen, setBranchFormOpen] = useState(false); const [branchName, setBranchName] = useState(""); const [branchCity, setBranchCity] = useState(""); const [branchOpeningTime, setBranchOpeningTime] = useState("09:00"); const [branchClosingTime, setBranchClosingTime] = useState("23:00"); const [editingBranchId, setEditingBranchId] = useState<number | null>(null); const remoteBranches = trpc.platform.branches.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false }); const branchLimit = trpc.platform.branchLimit.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false }); const createBranch = trpc.platform.createBranch.useMutation({ onSuccess: () => { void utils.platform.branches.invalidate(); void branchLimit.refetch(); toast.success("تمت إضافة الفرع"); }, onError: (error) => toast.error(`تعذر إضافة الفرع: ${error.message}`) }); const updateBranch = trpc.platform.updateBranch.useMutation({ onSuccess: () => { void utils.platform.branches.invalidate(); toast.success("تم تحديث حالة الفرع"); }, onError: (error) => toast.error(`تعذر تحديث الفرع: ${error.message}`) }); const deleteBranch = trpc.platform.deleteBranch.useMutation({ onSuccess: () => { void utils.platform.branches.invalidate(); toast.success("تم حذف الفرع"); }, onError: (error) => toast.error(`تعذر حذف الفرع: ${error.message}`) }); const branches = remoteBranches.data ?? []; return <div><SectionHeading title="الفروع والإعدادات" description="الفروع محفوظة في قاعدة البيانات مع عزل المطعم." action="إضافة فرع" onAction={() => { if (branchLimit.data && !branchLimit.data.canCreate) { toast.error(`تم بلوغ حد الفروع في باقة ${branchLimit.data.plan ?? "الحالية"}. قم بترقية الباقة لإضافة فرع جديد.`); return; } setBranchFormOpen((value) => !value); }} />{branchFormOpen && <Card className="mb-6 rounded-2xl border-orange-100 bg-orange-50/40"><CardContent className="grid gap-3 p-4 sm:grid-cols-[1fr_1fr_150px_150px_auto]"><Input value={branchName} onChange={(event) => setBranchName(event.target.value)} placeholder="اسم الفرع" className="rounded-xl bg-white" /><Input value={branchCity} onChange={(event) => setBranchCity(event.target.value)} placeholder="المدينة" className="rounded-xl bg-white" /><Input value={branchOpeningTime} onChange={(event) => setBranchOpeningTime(event.target.value)} placeholder="يفتح HH:MM" className="rounded-xl bg-white" /><Input value={branchClosingTime} onChange={(event) => setBranchClosingTime(event.target.value)} placeholder="يغلق HH:MM" className="rounded-xl bg-white" /><Button disabled={createBranch.isPending || branchName.trim().length < 2 || !/^\d{2}:\d{2}$/.test(branchOpeningTime) || !/^\d{2}:\d{2}$/.test(branchClosingTime)} onClick={() => createBranch.mutate({ restaurantId, name: branchName.trim(), city: branchCity.trim() || undefined, status: "open", openingTime: branchOpeningTime, closingTime: branchClosingTime })} className="rounded-xl bg-[#e76f3c]">{createBranch.isPending ? "جارٍ الحفظ..." : "حفظ الفرع"}</Button></CardContent></Card>}<Card className="mb-6 rounded-2xl border-orange-100 bg-orange-50/50 shadow-sm"><CardContent className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-bold text-slate-800">استخدام الفروع حسب الباقة</p><p className="mt-1 text-xs text-slate-500">تُطبق الصلاحية من الخادم قبل إنشاء أي فرع جديد.</p></div>{branchLimit.isLoading ? <span className="text-xs text-slate-500">جارٍ حساب الحد...</span> : branchLimit.isError ? <span className="text-xs text-red-600">تعذر تحميل حد الباقة. Request ID: branch-limit-{restaurantId}</span> : <div className="rounded-xl bg-white px-4 py-2 text-center"><span className="text-lg font-bold text-[#e76f3c]">{branchLimit.data?.used ?? 0}</span><span className="mx-1 text-xs text-slate-400">/</span><span className="text-sm font-semibold text-slate-700">{branchLimit.data?.limit === null ? "غير محدود" : branchLimit.data?.limit ?? 0}</span><p className="text-[10px] text-slate-400">{branchLimit.data?.plan ? `باقة ${branchLimit.data.plan}` : "الحد الافتراضي"}</p></div>}</CardContent></Card><RestaurantProfilePanel restaurantId={restaurantId} /><BrandingPanel restaurantId={restaurantId} /><div className="grid gap-4 md:grid-cols-3">{remoteBranches.isError ? <div className="p-6 text-sm text-red-600">تعذر تحميل الفروع. Request ID: branches-{restaurantId} <button onClick={() => void remoteBranches.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : remoteBranches.isLoading ? <div className="col-span-full p-8 text-center text-sm text-slate-400">جارٍ تحميل الفروع...</div> : branches.length === 0 ? <div className="p-8 text-center text-sm text-slate-400">لا توجد فروع محفوظة بعد.</div> : branches.map((branch) => <Card key={branch.id} className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-start justify-between"><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-orange-50 text-[#e76f3c]"><Store className="h-5 w-5" /></div><Badge variant="outline" className={`rounded-lg text-[10px] ${branch.status === "open" ? "border-emerald-200 bg-emerald-50 text-emerald-700" : "border-amber-200 bg-amber-50 text-amber-700"}`}>{branch.status === "open" ? "مفتوح" : "مغلق"}</Badge></div><h3 className="mt-5 font-bold">{branch.name}</h3><p className="mt-1 text-xs text-slate-500">{branch.city}</p><div className="mt-4 flex items-center justify-between border-t border-slate-100 pt-3 text-xs"><span className="text-slate-500">ساعات العمل</span><strong>{branch.openingTime && branch.closingTime ? `${branch.openingTime} — ${branch.closingTime}` : "غير محددة"}</strong></div><div className="mt-4 flex gap-2"><Button onClick={() => { setEditingBranchId(branch.id); setBranchName(branch.name); setBranchCity(branch.city ?? ""); setBranchOpeningTime(branch.openingTime ?? "09:00"); setBranchClosingTime(branch.closingTime ?? "23:00"); }} variant="outline" size="sm" className="rounded-lg text-xs">تعديل</Button>{editingBranchId === branch.id && <div className="absolute inset-x-4 bottom-16 z-10 grid gap-2 rounded-xl border border-orange-100 bg-white p-3 shadow-lg"><Input value={branchName} onChange={(event) => setBranchName(event.target.value)} placeholder="اسم الفرع" className="h-9 rounded-lg text-xs" /><Input value={branchCity} onChange={(event) => setBranchCity(event.target.value)} placeholder="المدينة" className="h-9 rounded-lg text-xs" /><div className="grid grid-cols-2 gap-2"><Input value={branchOpeningTime} onChange={(event) => setBranchOpeningTime(event.target.value)} placeholder="يفتح HH:MM" className="h-9 rounded-lg text-xs" /><Input value={branchClosingTime} onChange={(event) => setBranchClosingTime(event.target.value)} placeholder="يغلق HH:MM" className="h-9 rounded-lg text-xs" /></div><div className="flex gap-2"><Button size="sm" disabled={updateBranch.isPending || branchName.trim().length < 2 || !/^\d{2}:\d{2}$/.test(branchOpeningTime) || !/^\d{2}:\d{2}$/.test(branchClosingTime)} onClick={() => { updateBranch.mutate({ restaurantId, id: branch.id, name: branchName.trim(), city: branchCity.trim() || undefined, openingTime: branchOpeningTime, closingTime: branchClosingTime }); setEditingBranchId(null); }} className="h-8 flex-1 rounded-lg text-xs">حفظ</Button><Button size="sm" variant="outline" onClick={() => setEditingBranchId(null)} className="h-8 rounded-lg text-xs">إلغاء</Button></div></div>}<Button onClick={() => updateBranch.mutate({ restaurantId, id: branch.id, status: branch.status === "open" ? "closed" : "open" })} variant="outline" size="sm" className="flex-1 rounded-lg text-xs">تبديل الحالة</Button><Button onClick={() => setPendingDeleteBranchId(branch.id)} variant="outline" size="sm" className="rounded-lg text-xs">حذف</Button>{pendingDeleteBranchId === branch.id && <span className="flex items-center gap-1 rounded-lg bg-red-50 px-2 py-1 text-[10px] text-red-700"><span>تأكيد؟</span><button onClick={() => { deleteBranch.mutate({ restaurantId, id: branch.id }); setPendingDeleteBranchId(null); }} className="font-bold underline">نعم</button><button onClick={() => setPendingDeleteBranchId(null)} className="font-bold underline">لا</button></span>}</div></CardContent></Card>)}</div></div>; }

const remoteTypeLabels = { orders: "متابعة الطلبات", reservations: "الحجوزات", social: "حسابات التواصل", support: "الدعم", marketing: "التسويق", other: "أخرى" } as const;
const remoteStatusLabels = { published: "منشورة", reviewing: "قيد المراجعة", accepted: "مقبولة", in_progress: "قيد التنفيذ", submitted: "بانتظار المراجعة", completed: "مكتملة", cancelled: "ملغاة" } as const;

type RemoteTaskType = keyof typeof remoteTypeLabels;
type RemoteTaskStatus = keyof typeof remoteStatusLabels;

function RemoteWorkView({ restaurantId }: { restaurantId: number }) {
  const { user } = useAuth();
  const tasksQuery = trpc.remote.tasks.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false, refetchInterval: 5000 });
  const workersQuery = trpc.remote.workers.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false });
  const utils = trpc.useUtils();
  const createWorker = trpc.remote.createWorker.useMutation({ onSuccess: () => { void utils.remote.workers.invalidate(); toast.success("تم ربط العامل بالمطعم"); }, onError: (error) => toast.error(`تعذر ربط العامل: ${error.message}`) });
  const updateWorker = trpc.remote.updateWorker.useMutation({ onSuccess: () => { void utils.remote.workers.invalidate(); toast.success("تم تحديث العامل"); }, onError: (error) => toast.error(`تعذر تحديث العامل: ${error.message}`) });
  const deleteWorker = trpc.remote.deleteWorker.useMutation({ onSuccess: () => { void utils.remote.workers.invalidate(); toast.success("تم إلغاء ارتباط العامل"); }, onError: (error) => toast.error(`تعذر إلغاء العامل: ${error.message}`) });
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("0");
  const [dueAt, setDueAt] = useState("");
  const [assignedWorkerId, setAssignedWorkerId] = useState("");
  const [taskType, setTaskType] = useState<RemoteTaskType>("orders");
  const [activeTask, setActiveTask] = useState<number | null>(null);
  const [mode, setMode] = useState<"restaurant" | "worker">("restaurant");
  const [workerFormOpen, setWorkerFormOpen] = useState(false);
  const [workerUserId, setWorkerUserId] = useState("");
  const [workerRole, setWorkerRole] = useState("متابع طلبات");
  const [pendingDeleteWorkerId, setPendingDeleteWorkerId] = useState<number | null>(null);
  const [applicationFormOpen, setApplicationFormOpen] = useState(false);
  const [applicationRole, setApplicationRole] = useState("متابع طلبات");
  const [applicationMessage, setApplicationMessage] = useState("أرغب بالعمل عن بُعد");
  const currentWorkerQuery = trpc.remote.currentWorker.useQuery({ restaurantId }, { enabled: Boolean(user && mode === "worker"), retry: false });
  const applicationsQuery = trpc.remote.workerApplications.useQuery({ restaurantId }, { enabled: Boolean(user && mode === "restaurant"), retry: false });
  const myApplicationsQuery = trpc.remote.myWorkerApplications.useQuery(undefined, { enabled: Boolean(user && mode === "worker"), retry: false });
  const applyWorker = trpc.remote.applyAsRemoteWorker.useMutation({ onSuccess: () => { void myApplicationsQuery.refetch(); toast.success("تم إرسال طلب الانضمام للمطعم"); }, onError: (error) => toast.error(`تعذر إرسال الطلب: ${error.message}`) });
  const reviewApplication = trpc.remote.reviewWorkerApplication.useMutation({ onSuccess: () => { void applicationsQuery.refetch(); void workersQuery.refetch(); toast.success("تم تحديث طلب العامل"); }, onError: (error) => toast.error(`تعذر مراجعة الطلب: ${error.message}`) });
  const [message, setMessage] = useState("");
  const [deliveryNote, setDeliveryNote] = useState("");
  const messagesQuery = trpc.remote.messages.useQuery({ taskId: activeTask ?? 1 }, { enabled: Boolean(user && activeTask), retry: false, refetchInterval: 4000 });
  const createTask = trpc.remote.createTask.useMutation({ onSuccess: () => { tasksQuery.refetch(); setTitle(""); setDescription(""); setAmount("0"); setDueAt(""); setAssignedWorkerId(""); toast.success("تم نشر المهمة وحفظ قيمتها"); }, onError: (error) => toast.error(`تعذر نشر المهمة: ${error.message}`) });
  const updateStatus = trpc.remote.updateTaskStatus.useMutation({ onSuccess: () => tasksQuery.refetch(), onError: (error) => toast.error(`تعذر تحديث المهمة: ${error.message}`) });
  const acceptTask = trpc.remote.acceptTask.useMutation({ onSuccess: () => { tasksQuery.refetch(); toast.success("تم قبول المهمة"); }, onError: (error) => toast.error(`تعذر قبول المهمة: ${error.message}`) });
  const sendMessage = trpc.remote.sendMessage.useMutation({ onSuccess: () => { setMessage(""); messagesQuery.refetch(); }, onError: (error) => toast.error(`تعذر إرسال الرسالة: ${error.message}`) });
  const deliverTask = () => { if (!activeTask || !deliveryNote.trim()) return; sendMessage.mutate({ taskId: activeTask, body: `تسليم الموظف: ${deliveryNote}` }, { onSuccess: () => { setDeliveryNote(""); updateStatus.mutate({ taskId: activeTask, status: "submitted" }); } }); };
  const submitTask = (event: React.FormEvent) => { event.preventDefault(); const validationMessage = validateRemoteTaskDraft({ title, amount, description, dueAt }); if (validationMessage) { toast.error(validationMessage); return; } createTask.mutate({ restaurantId, type: taskType, title: title.trim(), description: description || undefined, amount: Number(amount || 0).toFixed(2), currency: "SAR", paymentMethod: "manual", assignedWorkerId: assignedWorkerId ? Number(assignedWorkerId) : undefined, dueAt: dueAt ? new Date(dueAt).toISOString() : undefined }); };
  const tasks = tasksQuery.data ?? [];
  return <div><div className="mb-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-xl font-bold">التوظيف عن بُعد</h2><p className="mt-1 text-sm text-slate-500">أنشئ مهامًا للطلبات والحجوزات والتواصل الاجتماعي، وحدد القيمة وطريقة التواصل والتسليم.</p></div><div className="flex items-center gap-2 rounded-xl bg-slate-100 p-1"><button onClick={() => setMode("restaurant")} className={`rounded-lg px-3 py-2 text-xs font-semibold ${mode === "restaurant" ? "bg-white text-[#e76f3c] shadow-sm" : "text-slate-500"}`}>وضع المطعم</button><button onClick={() => setMode("worker")} className={`rounded-lg px-3 py-2 text-xs font-semibold ${mode === "worker" ? "bg-white text-[#e76f3c] shadow-sm" : "text-slate-500"}`}>وضع الموظف</button></div></div>{mode === "worker" && <div className="mt-3 max-w-sm text-xs text-slate-500">{currentWorkerQuery.isLoading ? "جارٍ التحقق من ارتباط حسابك..." : currentWorkerQuery.data ? `مرتبط بالمطعم كـ ${currentWorkerQuery.data.role}` : "لم يتم قبول طلب انضمامك لهذا المطعم بعد."}</div>}</div><Card className="mb-5 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-base">حسابات العاملين عن بُعد</CardTitle><p className="mt-1 text-xs text-slate-500">اربط مستخدمًا بالمطعم وحدد دوره وتوفره لاستقبال المهام.</p></div>{mode === "restaurant" && <Button type="button" onClick={() => { setWorkerUserId(""); setWorkerRole("متابع طلبات"); setWorkerFormOpen(true); }} className="rounded-xl bg-[#e76f3c] text-xs hover:bg-[#d85f2e]">ربط عامل</Button>}</CardHeader><CardContent className="p-0">{workerFormOpen && mode === "restaurant" && <div className="m-5 grid gap-2 rounded-2xl border border-orange-100 bg-orange-50/50 p-4 sm:grid-cols-[180px_1fr_auto_auto]"><Input type="number" min={1} value={workerUserId} onChange={(event) => setWorkerUserId(event.target.value)} placeholder="معرّف المستخدم" className="rounded-xl bg-white" /><Input value={workerRole} onChange={(event) => setWorkerRole(event.target.value)} placeholder="الدور" className="rounded-xl bg-white" /><Button disabled={Number(workerUserId) <= 0 || workerRole.trim().length < 2 || createWorker.isPending} onClick={() => { createWorker.mutate({ restaurantId, userId: Number(workerUserId), role: workerRole.trim(), isAvailable: true }); setWorkerFormOpen(false); }} className="rounded-xl bg-[#e76f3c]">{createWorker.isPending ? "جارٍ الربط..." : "حفظ الربط"}</Button><Button variant="outline" onClick={() => setWorkerFormOpen(false)} className="rounded-xl">إلغاء</Button></div>}{workersQuery.isError ? <div className="p-5 text-sm text-red-600">تعذر تحميل العاملين. Request ID: remote-workers-{restaurantId} <button onClick={() => void workersQuery.refetch()} className="font-bold underline">إعادة المحاولة</button></div> : workersQuery.isLoading ? <div className="p-6 text-center text-sm text-slate-400">جارٍ تحميل العاملين...</div> : (workersQuery.data ?? []).length === 0 ? <div className="p-6 text-center text-sm text-slate-400">لا توجد حسابات مرتبطة بعد.</div> : <div className="divide-y divide-slate-100">{(workersQuery.data ?? []).map((worker) => <div key={worker.id} className="flex flex-wrap items-center justify-between gap-3 px-5 py-3"><div><p className="text-sm font-semibold">مستخدم #{worker.userId}</p><p className="text-xs text-slate-500">{worker.role} · {worker.isAvailable ? "متاح" : "غير متاح"}</p></div><div className="flex gap-2"><button type="button" onClick={() => updateWorker.mutate({ restaurantId, id: worker.id, isAvailable: !worker.isAvailable })} className="text-xs font-semibold text-[#e76f3c]">تبديل التوفر</button><button type="button" onClick={() => setPendingDeleteWorkerId(worker.id)} className="text-xs font-semibold text-red-500">إلغاء</button>{pendingDeleteWorkerId === worker.id && <span className="flex items-center gap-1 rounded-lg bg-red-50 px-2 py-1 text-[10px] text-red-700"><span>تأكيد؟</span><button onClick={() => { deleteWorker.mutate({ restaurantId, id: worker.id }); setPendingDeleteWorkerId(null); }} className="font-bold underline">نعم</button><button onClick={() => setPendingDeleteWorkerId(null)} className="font-bold underline">لا</button></span>}</div></div>)}</div>}</CardContent></Card><Card className="mb-5 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="border-b border-slate-100 px-5 py-4"><CardTitle className="text-base">طلبات الانضمام المستقل</CardTitle><p className="mt-1 text-xs text-slate-500">{mode === "restaurant" ? "راجع طلبات العاملين قبل ربطهم بالمطعم." : "قدّم طلبًا للعمل عن بُعد وتابع حالته."}</p></CardHeader><CardContent className="p-5">{mode === "worker" ? <div className="space-y-3"><Button type="button" onClick={() => { setApplicationRole("متابع طلبات"); setApplicationMessage("أرغب بالعمل عن بُعد"); setApplicationFormOpen(true); }} className="rounded-xl bg-[#e76f3c]">إرسال طلب انضمام</Button>{applicationFormOpen && <div className="grid gap-2 rounded-2xl border border-orange-100 bg-orange-50/50 p-4 sm:grid-cols-[1fr_1fr_auto_auto]"><Input value={applicationRole} onChange={(event) => setApplicationRole(event.target.value)} placeholder="الدور المطلوب" className="rounded-xl bg-white" /><Input value={applicationMessage} onChange={(event) => setApplicationMessage(event.target.value)} placeholder="رسالة مختصرة للمطعم" className="rounded-xl bg-white" /><Button type="button" disabled={applyWorker.isPending || applicationRole.trim().length < 2} onClick={() => { applyWorker.mutate({ restaurantId, role: applicationRole.trim(), message: applicationMessage.trim() || undefined }); setApplicationFormOpen(false); }} className="rounded-xl bg-[#e76f3c]">{applyWorker.isPending ? "جارٍ الإرسال..." : "إرسال"}</Button><Button type="button" variant="outline" onClick={() => setApplicationFormOpen(false)} className="rounded-xl">إلغاء</Button></div>}{myApplicationsQuery.isLoading ? <p className="text-xs text-slate-400">جارٍ تحميل طلباتك...</p> : myApplicationsQuery.isError ? <p className="text-xs text-red-600">تعذر تحميل طلباتك. Request ID: remote-my-applications <button type="button" onClick={() => void myApplicationsQuery.refetch()} className="mr-1 font-bold underline">إعادة المحاولة</button></p> : (myApplicationsQuery.data ?? []).length === 0 ? <p className="text-xs text-slate-400">لا توجد طلبات مرسلة بعد.</p> : <div className="space-y-2">{(myApplicationsQuery.data ?? []).map((application) => <div key={application.id} className="flex items-center justify-between rounded-xl bg-slate-50 p-3 text-xs"><span>{application.restaurantName} · {application.role}</span><Badge variant="outline" className="rounded-lg">{application.status === "pending" ? "قيد المراجعة" : application.status === "approved" ? "مقبول" : "مرفوض"}</Badge></div>)}</div>}</div> : applicationsQuery.isLoading ? <p className="text-sm text-slate-400">جارٍ تحميل طلبات الانضمام...</p> : applicationsQuery.isError ? <p className="text-sm text-red-600">تعذر تحميل طلبات الانضمام. Request ID: remote-applications-{restaurantId} <button type="button" onClick={() => void applicationsQuery.refetch()} className="mr-1 font-bold underline">إعادة المحاولة</button></p> : (applicationsQuery.data ?? []).length === 0 ? <p className="text-sm text-slate-400">لا توجد طلبات جديدة.</p> : <div className="space-y-3">{(applicationsQuery.data ?? []).map((application) => <div key={application.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-100 p-3"><div><p className="text-sm font-semibold">{application.applicantName || application.applicantEmail || `مستخدم #${application.applicantUserId}`}</p><p className="text-xs text-slate-500">{application.role} · {application.message || "بدون رسالة"}</p></div>{application.status === "pending" ? <div className="flex gap-2"><Button type="button" size="sm" onClick={() => reviewApplication.mutate({ restaurantId, applicationId: application.id, status: "approved" })} className="rounded-lg bg-emerald-600 text-xs">قبول وربط</Button><Button type="button" size="sm" variant="outline" onClick={() => reviewApplication.mutate({ restaurantId, applicationId: application.id, status: "rejected" })} className="rounded-lg text-xs text-red-600">رفض</Button></div> : <Badge variant="outline" className="rounded-lg text-xs">{application.status === "approved" ? "مقبول" : "مرفوض"}</Badge>}</div>)}</div>}</CardContent></Card><div className="grid gap-5 xl:grid-cols-[360px_1fr]"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="border-b border-slate-100 px-5 py-4"><CardTitle className="text-base">مهمة جديدة</CardTitle></CardHeader><CardContent className="p-5"><form onSubmit={submitTask} className="space-y-4"><div><label className="mb-1.5 block text-xs font-semibold">نوع المهمة</label><select value={taskType} onChange={(event) => setTaskType(event.target.value as RemoteTaskType)} className="h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="orders">متابعة الطلبات</option><option value="reservations">الحجوزات</option><option value="social">حسابات التواصل</option><option value="support">الدعم</option><option value="marketing">التسويق</option><option value="other">أخرى</option></select></div><div><label className="mb-1.5 block text-xs font-semibold">عنوان المهمة</label><Input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="مثال: متابعة رسائل Instagram" className="rounded-xl" /></div><div><label className="mb-1.5 block text-xs font-semibold">التفاصيل وطريقة التواصل</label><textarea value={description} onChange={(event) => setDescription(event.target.value)} placeholder="اذكر المطلوب، الحساب أو القناة، وطريقة التسليم..." className="min-h-24 w-full rounded-xl border border-slate-200 p-3 text-sm outline-none focus:border-orange-300" /></div><div><label className="mb-1.5 block text-xs font-semibold">قيمة المهمة (ر.س)</label><Input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" className="rounded-xl" /></div><div className="grid grid-cols-2 gap-2"><div><label className="mb-1.5 block text-xs font-semibold">الموعد النهائي</label><Input type="datetime-local" value={dueAt} onChange={(event) => setDueAt(event.target.value)} className="rounded-xl" /></div><div><label className="mb-1.5 block text-xs font-semibold">تعيين موظف</label><select value={assignedWorkerId} onChange={(event) => setAssignedWorkerId(event.target.value)} className="h-10 w-full rounded-xl border border-slate-200 bg-white px-2 text-xs"><option value="">نشر للفريق</option>{(workersQuery.data ?? []).map((worker) => <option key={worker.id} value={worker.id}>{worker.role} #{worker.id}</option>)}</select></div></div><Button type="submit" disabled={!user || createTask.isPending} className="w-full rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">{createTask.isPending ? "جارٍ النشر..." : "نشر المهمة"}</Button>{!user && <p className="text-center text-xs text-amber-600">سجّل الدخول لحفظ المهمة في قاعدة البيانات.</p>}</form></CardContent></Card><div className="space-y-4"><div className="grid gap-3 sm:grid-cols-3"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-4"><p className="text-xs text-slate-500">المهام المنشورة</p><p className="mt-2 text-2xl font-bold">{tasks.filter((task) => task.status === "published").length}</p></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-4"><p className="text-xs text-slate-500">قيد التنفيذ</p><p className="mt-2 text-2xl font-bold">{tasks.filter((task) => task.status === "in_progress").length}</p></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-4"><p className="text-xs text-slate-500">العاملون المتاحون</p><p className="mt-2 text-2xl font-bold">{workersQuery.data?.filter((worker) => worker.isAvailable).length ?? 0}</p></CardContent></Card></div><div className="grid gap-4 lg:grid-cols-[1fr_320px]"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="border-b border-slate-100 px-5 py-4"><CardTitle className="text-base">المهام الحالية</CardTitle><p className="mt-1 text-xs font-normal text-slate-500">الدفع اليدوي يبقى معلّقًا وغير مدفوع حتى دمج بوابة دفع معتمدة.</p></CardHeader><CardContent className="space-y-3 p-5">{tasksQuery.isLoading ? <div className="space-y-3"><div className="h-20 animate-pulse rounded-xl bg-slate-100" /><div className="h-20 animate-pulse rounded-xl bg-slate-100" /></div> : tasksQuery.isError ? <div className="rounded-xl border border-red-200 bg-red-50 p-6 text-center text-sm text-red-700">تعذر تحميل المهام. رقم الطلب: remote-tasks-{restaurantId}<Button type="button" onClick={() => tasksQuery.refetch()} variant="outline" className="mx-auto mt-3 rounded-lg text-xs">إعادة المحاولة</Button></div> : tasks.length === 0 ? <div className="rounded-xl bg-slate-50 p-8 text-center text-sm text-slate-500">لا توجد مهام محفوظة بعد.</div> : tasks.map((task) => <button key={task.id} onClick={() => setActiveTask(task.id)} className={`w-full rounded-xl border p-4 text-right transition ${activeTask === task.id ? "border-orange-300 bg-orange-50/50" : "border-slate-100 bg-white hover:border-orange-200"}`}><div className="flex items-start justify-between gap-3"><div><p className="font-bold">{task.title}</p><p className="mt-1 text-xs text-slate-500">{remoteTypeLabels[task.type as RemoteTaskType]} · {task.amount} {task.currency}</p></div><Badge variant="outline" className="rounded-lg text-[10px]">{remoteStatusLabels[task.status as RemoteTaskStatus]}</Badge></div><div className="mt-3 flex gap-2" onClick={(event) => event.stopPropagation()}>{mode === "worker" && task.status === "published" && <Button type="button" size="sm" disabled={!currentWorkerQuery.data || acceptTask.isPending} onClick={() => { if (currentWorkerQuery.data) acceptTask.mutate({ taskId: task.id, workerId: currentWorkerQuery.data.id }); }} className="h-8 rounded-lg bg-[#e76f3c] text-xs">قبول المهمة</Button>}{mode === "restaurant" && task.status === "published" && <Button type="button" size="sm" onClick={() => updateStatus.mutate({ taskId: task.id, status: "reviewing" })} className="h-8 rounded-lg bg-[#e76f3c] text-xs">بدء المراجعة</Button>}{task.status === "reviewing" && <Button type="button" size="sm" onClick={() => updateStatus.mutate({ taskId: task.id, status: "in_progress" })} className="h-8 rounded-lg bg-[#e76f3c] text-xs">بدء التنفيذ</Button>}{mode === "restaurant" && task.status !== "completed" && task.status !== "cancelled" && <Button type="button" size="sm" variant="outline" onClick={() => updateStatus.mutate({ taskId: task.id, status: "cancelled" })} className="h-8 rounded-lg text-xs text-red-600">إلغاء</Button>}{task.status === "submitted" && <Button type="button" size="sm" onClick={() => updateStatus.mutate({ taskId: task.id, status: "completed" })} className="h-8 rounded-lg bg-emerald-600 text-xs">اعتماد التسليم</Button>}</div></button>)}</CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="border-b border-slate-100 px-5 py-4"><CardTitle className="text-base">التواصل مع الموظف</CardTitle></CardHeader><CardContent className="p-5">{!activeTask ? <p className="py-10 text-center text-sm text-slate-500">اختر مهمة لفتح المحادثة.</p> : <><div className="mb-4 max-h-64 space-y-2 overflow-y-auto">{(messagesQuery.data ?? []).map((item) => <div key={item.id} className="rounded-xl bg-slate-50 p-3 text-sm">{item.body}<p className="mt-1 text-[10px] text-slate-400">{new Date(item.createdAt).toLocaleString("ar-SA")}</p></div>)}</div><div className="flex gap-2"><Input value={message} onChange={(event) => setMessage(event.target.value)} placeholder="اكتب رسالة..." className="rounded-xl" /><Button type="button" disabled={!message.trim() || sendMessage.isPending} onClick={() => sendMessage.mutate({ taskId: activeTask, body: message })} className="rounded-xl bg-[#e76f3c]">إرسال</Button></div>{mode === "worker" && <div className="mt-3 flex gap-2"><Input value={deliveryNote} onChange={(event) => setDeliveryNote(event.target.value)} placeholder="ملاحظة التسليم أو رابط النتيجة" className="rounded-xl" /><Button type="button" disabled={!deliveryNote.trim() || sendMessage.isPending} onClick={deliverTask} className="rounded-xl bg-emerald-600">تسليم المهمة</Button></div>}</>}</CardContent></Card></div></div></div></div>;
}

function TestLoginScreen({ email, password, setEmail, setPassword, onSubmit, pending, onOAuth, onRegister }: { email: string; password: string; setEmail: (value: string) => void; setPassword: (value: string) => void; onSubmit: () => void; pending: boolean; onOAuth: () => void; onRegister: () => void }) {
  const { t, direction } = useLanguage();
  const quickRoles = [{ label: "Super Admin", value: "admin" }, { label: "المطعم", value: "restaurant" }, { label: "النادل", value: "waiter" }, { label: "المطبخ", value: "kitchen" }, { label: "الكاشير", value: "cashier" }, { label: "العميل", value: "customer" }, { label: "السائق", value: "driver" }];
  return <div dir={direction} className="min-h-screen bg-[#f7f8fb] text-slate-900"><div className="mx-auto grid min-h-screen max-w-6xl lg:grid-cols-[0.85fr_1.15fr]"><aside className="relative hidden overflow-hidden bg-[#101d31] p-10 text-white lg:flex lg:flex-col lg:justify-between"><div className="absolute -left-20 top-20 h-64 w-64 rounded-full bg-orange-400/20 blur-3xl" /><div className="relative"><div className="flex items-center gap-3"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#e76f3c]"><Utensils className="h-6 w-6" /></div><div><p className="text-lg font-black">NFOOD</p><p className="text-[10px] tracking-[0.18em] text-slate-400">RESTAURANT OPERATING SYSTEM</p></div></div><div className="mt-24 max-w-sm"><p className="text-sm font-bold text-orange-200">مساحة واحدة لكل فريقك</p><h1 className="mt-4 text-4xl font-black leading-[1.25]">ادخل إلى التشغيل الذي يفهم مطعمك.</h1><p className="mt-5 text-sm leading-7 text-slate-300">POS، المطبخ، الطلبات، العملاء والتحليلات في تجربة واحدة واضحة.</p></div></div><div className="relative rounded-3xl border border-white/10 bg-white/5 p-5"><p className="text-xs font-bold text-orange-200">دخول موحد</p><p className="mt-2 text-sm leading-6 text-slate-300">اختر الحساب المناسب، وستظهر لك لوحتك وصلاحياتك تلقائيًا.</p></div></aside><main className="flex items-center justify-center p-5 sm:p-8"><div className="fixed right-5 top-5 z-20"><LanguageSwitcher compact /></div><Card className="w-full max-w-xl rounded-[2rem] border-white/70 bg-white/90 shadow-[0_24px_80px_rgba(15,23,42,0.10)] backdrop-blur"><CardContent className="p-6 sm:p-10"><div className="mb-8 flex items-center justify-between"><div><p className="text-xs font-bold text-[#e76f3c]">{t("welcomeBack")}</p><h1 className="mt-2 text-3xl font-black tracking-tight">{t("signIn")} NFOOD</h1><p className="mt-2 text-sm leading-6 text-slate-500">أدخل بياناتك، وسنوجهك إلى مساحة العمل المناسبة.</p></div><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-orange-100 text-[#e76f3c]"><Utensils className="h-6 w-6" /></div></div><div className="mb-6 rounded-2xl border border-slate-200 bg-slate-50/80 p-4"><p className="mb-3 text-xs font-bold text-slate-500">{t("signIn")} · {t("allRoles")}</p><div className="flex flex-wrap gap-2">{quickRoles.map((role) => <button key={role.value} type="button" onClick={() => setEmail(role.value)} className={email === role.value ? "rounded-full border border-[#e76f3c] bg-orange-100 px-3 py-2 text-[11px] font-bold text-[#c75325]" : "rounded-full border border-slate-200 bg-white px-3 py-2 text-[11px] font-bold text-slate-600 hover:border-orange-200"}>{role.label}</button>)}</div></div><div className="space-y-5"><label className="block text-xs font-bold">{t("email")}<div className="relative mt-2"><Input type="text" autoComplete="username" value={email} onChange={(event) => setEmail(event.target.value)} placeholder="admin أو name@example.com" className="h-13 rounded-2xl border-slate-200 bg-slate-50/70 px-4" /></div></label><label className="block text-xs font-bold">{t("password")}<Input type="password" value={password} onChange={(event) => setPassword(event.target.value)} onKeyDown={(event) => event.key === "Enter" && onSubmit()} placeholder="أدخل كلمة المرور" className="mt-2 h-13 rounded-2xl border-slate-200 bg-slate-50/70 px-4" /></label><Button type="button" onClick={onSubmit} disabled={pending || !email || !password} className="h-13 w-full rounded-2xl bg-[#e76f3c] text-base font-bold shadow-lg shadow-orange-200 hover:bg-[#d85f2e]">{pending ? "جارٍ الدخول إلى مساحتك..." : "دخول آمن"}</Button><div className="relative py-1 text-center"><span className="relative z-10 bg-white px-3 text-[11px] text-slate-400">أو</span><div className="absolute inset-x-0 top-1/2 h-px bg-slate-100" /></div><Button type="button" variant="outline" onClick={onOAuth} className="h-12 w-full rounded-2xl border-slate-200">{t("continueWithGoogle")}</Button><Button type="button" variant="ghost" onClick={onRegister} className="h-11 w-full rounded-2xl text-[#e76f3c]">{t("joinRestaurant")} <ArrowLeft className="mr-1 h-4 w-4" /></Button></div><p className="mt-6 text-center text-[11px] leading-5 text-slate-400">تسجيل الدخول موحد للأدمن والمطعم والفريق والعملاء والسائقين. يتم تحديد لوحة التحكم تلقائيًا حسب الدور.</p></CardContent></Card></main></div></div>;
}
